-- ============================================================
-- Migration 0130: 품질환경매뉴얼(QM)·프로세스(PROC) 본문 재적재
--
-- 0126~0129 로 규정 55종을 재적재했으나 QM·PROC 는 원본 xlsx 를 못 찾아 미변경으로
-- 남겼다. 사장님 지시(8/1)로 전체 폴더를 훑어 정본을 확보 —
--   QM   = 1.품질&환경 메뉴얼_230501\1.품질환경 매뉴얼 (REV.7_250106_프로세스맵 포함)…xlsx (21시트)
--   PROC = 2.품질&환경 프로세스 _230501\{CP-01~03, MP-01~03, SP-01~03} (9파일, REV.5)
-- 둘 다 규정과 같은 템플릿(페이지 라벨열 41·번호열 47, 좌단 1/우단 30)이라 같은 도구로 처리.
--
-- QM: 시트=장(章). 본문 장은 --sublevel 로 절(8.1) 단위 분할 — 구본은 8장이 32,306자
--     한 덩어리라 KB 검색이 어디를 볼지 못 짚어줬다. 매트릭스/목록 시트는 표 1섹션.
--     ⚠️ ZF CSR 매트릭스 2시트는 페이지 머리글이 없어 경계 탐지가 0이 되는 함정이 있었다
--        (36,268자 통째 누락) → 마커 없으면 시트 전체를 1페이지로 읽도록 보완.
-- PROC: 흐름도 문서라 번호 표제가 없다 → 프로세스당 1섹션(구본과 같은 입자).
--
-- 검증: 원본 셀 QM 3,011 / PROC 1,287 대조 — 양쪽 커버리지 100.00%(미포함 0).
--       규정 55종 회귀 없음(486섹션·커버리지 100.00% 유지).
-- regulation_sections 는 시드 전용 → DELETE+INSERT 무손실·재실행 멱등.
-- ============================================================

-- ── QM (72섹션 · 114,524자) ──
DELETE FROM regulation_sections WHERE reg_code = 'QM';
