제품 특성 안전관리 규정 | 개발 | 1.12. 제품 안전
제품 안전 및 제품 책임은 자동차 산업의 기업에게 특히 중요합니다.
공급 업체는 ZF가 최종 제품을 만들기 위해 구매하는 하위 공급 업체의 부품 또는 프로세스를 포함하여 부품 및 프로세스에 대한 생산자
책임(제품 책임)을 갖습니다.
따라서 제품 책임 위험을 방지하기 위해 제품 안전을 보장하기 위해 조직 및 기술 문제와 관련하여 모든 권한을 다하는 것은 공급자의
책임입니다.
공급 업체는 "제품 안전"관련 제품 및 제조 프로세스를 관리하기위한 문서화 된 프로세스를 보유해야합니다.
ZF는 공급업체가 모든 작업을 담당 할 PSR(제품 안전 담당자)을 지정하도록 요구합니다.
IATF 16949 섹션 4.4.1.2에 설명 된 관련 작업. 또한 공급 업체는 이러한 요구 사항을 공급망에 적용해야 합니다. | 없음
1.22. 고객 별 요구 사항
공급 업체는 ZF 고객의 특정 요구 사항을 준수해야합니다.
일반 고객별 요구 사항은 이미 지침에 포함되어 있으며 구현되어야합니다.
ZF고객에서 발행 한 추가 고객별 요구사항,
ZF 고객은 프로젝트 기반으로 커뮤니케이션됩니다. 이들의 적용은 ZF와 공급업체 간의 합의에 따릅니다.
경영관리
(MP-01) | IATF16949 & ISO9001
인증 유지 관리 | 품질경영 | 1.4. 품질 관리 시스템
IATF의 표준 및 규정에 따라 설정된 효과적인 품질관리 시스템 IATF16949는 ZF와의 공급업체 관계를위한 전제 조건입니다.
QM 시스템의 효과는 다음에 의해 반영되어야합니다.
 • 프로세스, 절차 및 제품의 지속적이고 검증 가능한 개선
 • 제공 품질
 • 배달 신뢰성
 • 시정 조치의 신속하고 효과적인 구현
 • 모든 수준의 커뮤니케이션
 • 신규 및 수정된 프로젝트의 적절하고, 시기 적절한 처리
이 품질 관리 시스템의 목표는 "무결점"목표를 달성하는 것입니다.
최소 요구 사항은 공인인증 기관의 ISO 9001에 따른 인증입니다.
IATF16949에 따른 인증은 자동차 및 서비스 부품 공급 업체에 필요합니다.
IATF16949에 아직 인증되지 않은 경우 해당 공급업체는 인증을 획득할 계획을 가지고 있어야합니다.
공급자는 인증서가 다음과 같은 경우 즉시 ZF에 알려야합니다
 • 취소되었습니다.
 • 성공적인 재 인증없이 만료되었습니다.
 • 일시적으로 정지되었습니다.
재 인증이 계획되지 않은 경우 공급 업체는 만료일 최소 3개월전에 ZF에 알려야합니다.
성공적인 재 인증 후, 새로운 인증서는 ZF 통신을 사용하여 명시적으로 요청하지 않고 전자적으로 ZF 수신 공장으로 전송됩니다
플랫폼 (ZF 인터넷 웹 사이트 https://www.zfsachskorea.co.kr/ – 섹션 1.13 참조). 각 ZF 수신 공장에 새 인증서에 대한 정보를 제공하는
것은 공급 업체의 책임입니다.
인증은 공인인증 기관에서 제공해야합니다.
감사 : ZF는 사전 통지 후 ZF 고객 또는 ZF가 지정한 제 3자와 함께 품질관리 시스템, 프로세스 및 제품에 대한 감사 및 평가를 수행 할
권리를 보유합니다. | 없음
