품질경영 | 1.7. 품질 목표
공급업체는 고객 요구 사항을 충족하기위한 품질목표가 조직 전체의 관련 기능, 프로세스 및 수준에 대해 정의, 설정,
유지 및 검토되도록해야합니다.
품질계획의 맥락에서 공급 업체는 "무결점 전략"을 개발하고, "무결점"목표를 달성하기 위해 필요한 모든 조치를
취해야합니다
