A-8101
비상상태 대비 및 대응 규정 | 총무 | 1.15.비상시 계획
공급업체는 생산량을 유지하고 ZF 요구사항이 충족되는지 확인하는데 필수적인 모든 제조공정 및 인프라 장비에 대한 내부 및 외부
위험을 식별하고 평가해야합니다.
공급 업체는 ZF로의 제품 흐름을 방해 할 수있는 각 공급 업체 제조/배송 위치에 대한 비상 계획을 개발해야합니다.
ZF는 실제 재난 (예 : 외부 제공 제품, 서비스 중단, 반복되는 자연 재해, 화재 등)이 발생한 경우 즉시 알려야합니다.
이 경우 공급 업체는 ZF의 도구 및 / 또는 대체품에 대한 ZF 액세스 권한을 제공해야합니다.
공급 업체는 최소한 매년 각 비상 계획을 정기적으로 검토하고 업데이트해야합니다.
비상 계획에는 복구 조치에 대한 포괄적인 테스트가 포함되어야하며 구성요소/원료의 잠재적인 격차를 해결해야합니다. 구현
이러한 비상계획과 관련된 모든 변경사항은 문서화되어야하며, 변경될 수 있습니다.
관리 프로세스 (섹션 1.11 – 제품 또는 프로세스 변경 참조). | 없음
