품질보증 | 1.13. 전자 데이터 교환에 기반한 비즈니스 프로세스
ZF와 공급업체간의 전자 데이터 교환을 기반으로하는 비즈니스 프로세스는 ZF전략의 주요 초점입니다.
이 전략에 따르면, 이 지침에 설명 된 프로세스 중 점점 더 많은 프로세스가“와 같은 ZF의 전자 통신 플랫폼을 사용하여 관리됩니다. SupplyOn ”및“ VIN-Vendor 정보 네트워크-https://www.zfsachskorea.co.kr/”
ZF는 공급 업체가 위에서 언급한 통신 플랫폼을 통해 ZF와의 전자 데이터 교환을 지원하고 ZF의 웹 기반 애플리케이션을 통해 거래를
수행하는데 필요한 조치를 취할 것으로 기대합니다.
연락. 공급 업체는 공급 업체 정보 네트워크 (공급 업체 마스터 및 SupplyOn 비즈니스 디렉토리)에서 최신 연락처 정보를 유지할 책임이
있습니다.
모든 공급 업체는 최신 상태를 유지하기 위해 ZF 통신 플랫폼에 자주 액세스해야합니다. | 없음
