ZF 공급업체는 전체 공급망의 공급업체에 적용 가능한 모든 법적 및 규제 요건을 준수하고 전달해야합니다.
공급업체는 APQP 단계 동안 모든 제품, 프로세스 또는 서비스(내부 및 외부)에 생산위치 및 사용 국가 (ZF에서 명명 한 경우)의 법적 요구
