1.9. 특별한 특징 (특별특성)
ZF는 기술 도면, 사양 및 관련 구매 문서에 제품 및 서비스 요구 사항을 설명합니다.
모든 특성을 준수해야합니다. 특별한 고려가 필요한 더 높은 위험이있는 특성이 있습니다. 이것이“특별한 특성(특별특성)”입니다.
이러한 특성의 편차는 제품안전, 제품수명, 조립능력, 제품기능, 품질에 심각한 영향을 미칠 수 있으며, 공식 또는 법적 규정을 위반할
수 있습니다.
특수 특성은 ZF에 의해 지정되고 도면 / 또는 사양에 문서화됩니다. 그들은 또한 위험 분석에서 식별되어야합니다.
공급자 (예 : 공급자의 경험과 지식에 기반한 제품 / 또는 공정 FMEA에서).
ZF에서 정의한 특수 특성은 다음과 같이 분류됩니다.
 • 중요 특성 (C) - 특별제품특성
 • 중요한 특성 (S)
 • 통과 특성 (PTC) - 무검사 제품
 • 공정 특성 (P) - 특별공정특성
ZF 표준 정의, 결정 및 관련 요구 사항에 대한 자세한 설명은 다음 사이트에서 다운로드 할 수 있습니다.
ZF 인터넷 웹 사이트-https://www.zfsachskorea.co.kr/(보다
"ZF 그룹 내 특수 특성 (SC) 규제” ). 프로젝트 계획 단계에서 특수 특성에 대한 ZF 요구 사항은 섹션 2.11
– 특수 특성에 설명되어 있습니다 | 없음
