(CP-02) | J-3100
4M변경관리 규정 | 개발 | 1.11. 제품 또는 프로세스 변경
공급자는 제품, 제품 실현 및 제조 프로세스에 영향을 미치는 변경사항을 제어하고 구현하기위한 문서화된 프로세스를 보유해야합니다.
"변경"은 AIAG PPAP 매뉴얼 / 또는 VDA 볼륨 2, 부품 내역의 트리거 매트릭스에 참조 된 모든 상황을 나타냅니다.
하위 공급업체로 인한 변경을 포함하여 변경의 영향은 구현전에 ZF 요구사항을 준수하는지 확인하기 위해 평가, 확인 및 검증되어야
합니다. 
변경과 관련된 위험의 증거를 문서화하고 평가해야합니다.
최신 PPF / PPAP 승인에서 벗어난 의도된 변경은 ZF의 적시 검토 및 승인을 위해 가능한 한 빨리 ZF에 전달되어야합니다.
공급 업체는 지정된 양식을 전송하여 서면 요청을 제출해야합니다. (F1.11) 
영향을받는 모든 ZF 시설 (웹 사이트에서 다운로드 가능) ZF 인터넷 웹 사이트-https://www.zfsachskorea.co.kr/ ).
요청에는 적시에 ZF / 고객 승인 및 검증을 허용하기 위해 필요한 안전 재고 / 은행 요구사항 및 시기를 식별하는 적절한 변경 관리를
보여주는 자세한 일정표가 첨부되어야합니다
ZF로부터 서면 승인을 받기 전에는 변경 사항이 적용되지 않습니다.
변경 구현 후 생산 재료를 배송하려면 새로운 PPF / PPAP 승인이 필요합니다.
변경사항이 전자 부품 (특히 반도체 장치, 수동 구성 요소 및 LED 구성 요소), 섹션 5.4가 적용됩니다. | 없음
