공정FMEA 작성 및 관리 지침 | 개발 | 1.19. 교훈
협력업체는 일반적으로 조직 내 경험을 통해 얻은 지식을 문서화하고 공유하는 프로세스를 보유해야합니다
효율적인 제품 및 프로세스 개발 프로세스를 실현하기 위해 공급업체는 이전 프로젝트, 고객 클레임, 리콜 조치, 공급 업체 불만, 변경 및
편차 요청, 감사, 재 작업, 수리 및 폐기에서 얻은 최소한의 지식을 고려해야합니다.
공급 업체는 프로젝트의 첫 번째 단계로 배운 교훈을 검토하고 적용해야합니다.
이 프로세스는 전체 공급망에서 결함을 감지하는 대신 결함을 방지하는 데 중점을 둡니다.
그 효과는 생산공정 신뢰성, 공급 품질 및 배송성능의 지속적인 개선으로 입증 됩니다 | 없음
