지그관리 규정 | 개발
생산 | 1.21. 고객 재산 표시
ZF 또는 ZF 고객에게 속한 제조, 테스트 또는 검사 장비를 위한 모든 도구는 해당 도구가 ZF 또는 ZF 고객의 자산임을 명확하게 표시하기
위해 영구적으로 표시되어야합니다.
