도구 식별 요구사항을 준수하지 않으면 지불이 지연되거나 지불되지 않습니다 | 없음
H-1100
계약검토 규정 | 개발 | 2. APQP 고급 제품 품질 계획
ZF의 목표는 가능한 빠른단계에서 새로운 프로젝트를 위한 품질계획에 공급 업체를 참여시키는 것입니다.
ZF는 항상 VDA Volume Material Level Assurance (Product Creation – Maturity Level Assurance for New Parts) 또는 AIAG APQP에
따라 프로젝트 관리의 맥락에서 공급업체의 체계적인 계획을 요구합니다.
단, ZF가 다른 절차를 규정하지 않는 경우. 이 계획은 공급자가 만든 부품과 공급자가 구매한 부품 모두에 적용됩니다.
ZF는 프로젝트 관리자와 프로젝트 팀에 대해 통보를받습니다.
각 부품 또는 프로젝트에 대해 공급업체는 최소한 아래에 지정된 계획단계를 구현해야합니다
(섹션 2.1 ~ 2.35 참조). 각 섹션에서는 필요한 계획 항목 (APQP 요소)을 설명합니다.
ZF에서 별도로 지정하지 않은 경우 이러한 모든 요구 사항은 필수입니다.
피드백은 요청된 양식을 통해 제공됩니다.
(F2 – PSPP) 에서 다운로드 할 수 있습니다. ZF 인터넷 웹 사이트 및 / 또는 ZF에서 달리 명시하지 않는 한 ZF에서 지원하는 통신 플랫폼.
공급업체가 생산 및 구매한 부품(원자재, 외부 가공, 하위 공급업체)의 경우 개별평가를 요약하고 개별 중요항목을 강조하는 상태를
작성해야합니다.
이 품질 지침의 내용을 넘어서는 프로젝트 별 요구 사항은 ZF와 공급 업체간에 합의됩니다. | 없음
