계약검토 규정 | 개발 | 2.1. 공급 업체 준비 
품질위험을 조기에 인식하고 회피하는 것은 완벽한 출시와 안정적인 직렬 공급을 위한 핵심성공 요인입니다.
ZF는 위험이 증가한 구성 요소 또는 특별 우선 순위를 결정하고, 이러한 구성요소에 대한 공급업체 준비 프로그램을 시작할 권리를
보유합니다.
이 프로그램은 ZF와 협력하여 공급자가 수행해야합니다. 내용과 절차는“ ZF 공급 업체 준비지침 ”검토 가능
ZF 인터넷 웹 사이트-https://www.zfsachskorea.co.kr/ | 없음
2.2. 초기 공급 업체 참여
프로젝트에 따라 ZF는 동시 엔지니어링을 수행하기 위해 초기단계에서 공급 업체를 참여시킬 것입니다.
ZF는 공급업체가 ZF의 초대를받은 경우 이러한 동시 엔지니어링 활동에 적극적으로 참여하기를 기대합니다.
이러한 경우 ZF와 공급자 모두를 포함하는 동시 엔지니어링 프로세스가 수행되어야합니다.
공급업체 또는 ZF에 대한 명확한 책임과 함께 필요한 활동 목록을 작성해야합니다.
이러한 활동의 이행에 대한 약속은 문서화되고 확인되어야합니다. 최종 결과는 승인을 위해 ZF에 의해 평가됩니다 | 없음
H-1100
