계약검토 규정 | 개발 | 2.4. 타당성 조사
공급업체는 계약 검토의 일부로 모든 기술문서(예 : 도면, 사양, 환경, 작업 명세서, 상품별 및 고객 별 요구 사항 ...)뿐만 아니라 구매
조건 및이 품질 지침을 분석해야 합니다.
1)요구 사항은 다음을 결정하고 확인하는 것입니다.
 • 설계의 타당성 (설계 책임이있는 공급 업체의 경우),
 • 제조 능력
 • 특수특성(특별특성)에 대한 공정능력을 측정, 달성 및 유지하는 능력.
우리는 공급 업체가 설계, 프로세스 및 비용의 개선을 결정하기를 기대합니다.
이러한 맥락에서 ZF는 공급 업체가 포장 및 배송과 같은 문제를 고려할 것으로 기대합니다.
각 부품에 대해 모든 잠재적 공급 업체는 서명 된 타당성 조사 양식을 제출해야합니다.
F2.4 (다운로드 가능 ZF 인터넷 웹 사이트-https://www.zfsachskorea.co.kr/) 견적과 함께 계약을 소싱하고 수주하기 전에. 이것은
전제조건이며 비즈니스 수여를 보장하지 않습니다.
최종 소싱을 받기 전에 ZF는 적절한 공급업체 담당자와 공동으로 상세한 기술검토 / 검증을 수행 할 권리를 보유합니다.
타당성 조사의 제출은 ZF에서 요청하는 경우 용량 확인을 동반해야합니다.
기존 사업에 제품 또는 공정 변경이있을 때마다 타당성 조사를 확인하고 확인해야합니다.
확인 된 타당성 조사는 모든 부품 승인 보고서의 일부입니다 | 없음
2.5. 기획 내용
ZF는 요청된 양식을 통해 자세한 활동 계획을 통보받습니다.
(F2 – PSPP) , 사용 가능 ZF 인터넷 웹 사이트-https://www.zfsachskorea.co.kr/) 및 또는 ZF의 통신 플랫폼을 통해. | 없음
