2.7. 제품 설명
제품 설명은 소싱 프로세스의 매우 초기단계(APQP 단계 이전)에서 시작하여 ZF 및 ZF 고객의 모든 요구사항이 캡처되고 모든 관련 문서
(예 : 기술 사양, 도면, 내부 표준…)에 포함되도록합니다.
제품 설명 과정에서 확인 된 모든 문제는 합의 된 실행 계획을 통해 추적됩니다.
3D 데이터 모델 (해당되는 경우)에 설명되어 있지 않지만 생산 엔지니어링 관점에서 필요한 치수
(예 : 러너 위치, 분할 선)는 제조 및 조립시 간섭 및 문제를 방지하기 위해 항상 ZF와 결정, 지정 및 합의되어야합니다. | 없음
