필요한 경우 ZF는 개발 관련 작업 및 책임에 대한 프로젝트별 설명을 보장합니다.
이것은 "개발 인터페이스 계약"을 통해 이루어지며, ZF 인터넷 웹 사이트 -https://www.zfsachskorea.co.kr/.
이 문서는 ZF와 설계 책임이있는 공급자가 작성해야합니다. 양 당사자가 합의합니다. 양식보기 F2.8 LSV-E; F2.8 LSV-M; F2.8 LSV-S. | 없음
