생산 | 2.14. 운영 계획 - 공정별 작업표준서
모든 단일 구성품 및 조립품에 대한 운영 계획을 완료해야합니다.
여기에는 공정 단계, 내부 / 외부 운송, 운송 수단, 사용되는 기계 및 작동 재료에 대한 모든 정보가 포함되어야합니다.
예를들어 생산 단계, 미가공 부품 및 공정 설명에 필요한 도면이 발행되어야합니다 | 없음
J-1101
공정FMEA 작성 및 관리 지침 | 개발 | 2.15. 제품 및 공정 FMEA
FMEA(고장 모드 및 영향 분석)는 가능한 위험과 심각도, 발생 확률 및 탐지 가능성에 대한 평가를 검토하기 위해 수행되어야합니다.
이러한 위험은 적절한 조치를 도입하여 최소화되어야합니다.
따라서 FMEA는 결함을 예방하는 중요한 도구입니다.
FMEA는 적시에 수행되어야하므로 취해야 할 결과와 조치가 여전히 계획에 포함될 수 있습니다.
FMEA는 설계, 생산, 조립, 포장, 운송, 고객 사용, 재활용 및 폐기물 처리와 같은 제품 수명주기의 모든 단계에 사용됩니다.
FMEA는 지속적인 개선 도구로 사용되어야합니다.
 1)FMEA는 다음과 같은 경우에 개발 또는 수정되어야합니다.
 • 신규 부품 개발 / 생산
 • 새로운 제조 방법 도입
 • 식물 재배치
 • 도면 변경
 • 프로세스 변경
 • 결함이 발생하는 경우
 • 교훈
2)제품 (디자인) FMEA
제품 FMEA는 공급자의 책임하에 설계되는 모든 부품에 대해 작성되어야합니다. ZF의 요청에 따라 제품 FMEA가 ZF에 제공됩니다.
3)FMEA 처리
프로세스 FMEA는 구성요소의 모든 프로세스 단계에 대해 완료되어야합니다.
특히 공정 FMEA의 결과와 특수특성(특별특성)은 통제계획의 기초로 고려됩니다.
ZF의 요청에 따라 Process FMEA가 ZF에 제공됩니다. | 없음
8.운영 | 개발
(CP-02) | J-1101
공정FMEA 작성 및 관리 지침 | 개발 | 다음 주제를 고려해야합니다
1)FMEA (제품 및 프로세스)에 따른 실패 시뮬레이션
FMEA내에서 식별된 고장모드는 고장이 감지되었는지 확인하기 위해 생산공정의 산업화 후 작업현장에서 시뮬레이션되어야합니다.
추가 고장 모드 및 기타 잠재적 원인을 식별하고 FMEA에 통합해야합니다.
2)재료 혼합
하위 공급업체의 프로세스를 포함하여 생산 중 전체 프로세스 체인을 분석하여 재료 혼합과 관련된 위험 가능성을 분석해야합니다.
물질 혼합 위험을 제거하기 위해 필요한 모든 조치를 취해야합니다 (예 :효율적인 연동 시스템 구현).
3)부품 변형 관리
유사한 모양의 부품이 섞일 위험을 제거하는 시스템을 구현해야합니다.
4)스크랩 부품, 재 작업 부품, 설정 부품 및 참조 부품 제어
여기에는 특히 기계 충돌, 기계 정지 및 재시동과 같은 특수한 상황에서 의심스러운 부품과 양호한 부품의 혼합 방지가 포함됩니다.
5)기술적 청결
기술적 청정도는 특정요구 사항에 따라 FMEA에서 구현되어야합니다.
하위 공급 업체, 기계 제조업체 및 서비스 제공 업체도 고려해야합니다.
제품 및 모든 프로세스는 모든 요구 사항이 충족되도록 설계되어야합니다.
6)통과 / 건너 뛰기 프로세스
이전 단계가 성공적으로 완료된 경우에만 각 프로세스 단계가 시작될 수 있도록 시스템을 설계하고 구현해야합니다.
7)교훈
유사한 프로세스와 제품에서 얻은 모든 교훈을 새 프로젝트에 반영해야합니다.
무엇보다도 교훈을 얻은 문서, 모든 내부 및 외부 불만 기록, 8D 보고서 및 이전 FMEA를 고려해야 합니다.
하위 공급 업체 문제에 대해 배운 교훈도 고려해야합니다
8)FMEDA (고장 모드 효과 및 진단 분석)
ZF에서 요청하는 경우 전기/전자/프로그래밍 가능한 전자 안전을위한 SFF (Safe Failure Fraction) 관련 시스템은
IEC DIN EN 61508-2에 따라 FMEDA에 의해 결정됩니다. ZF는 안전 관련 시스템의 위험에 대해 서면으로 통보됩니다.
9)평가
FMEA 프로세스에 대한 평가가 수행되어야합니다.
VDA 및 AIAG의 국제 표준에 따라 또는 FMEA 체크리스트를 통해 F2.15 (검토 가능 ZF 인터넷 웹 사이트 ).
10)조치 실행
FMEA의 도움으로 확인된 위험은 적절한 조치를 취함으로써 최소화되어야합니다.
측정, 목표 날짜 및 책임은 생산 시작 전에 조치를 취할 수있는 방식으로 할당되어야합니다.
도입 된 조치는 그 효과에 대해 재평가 되어야 합니다. ZF는 필요한 설계 수정 사항에 대해 즉시알려야합니다. | 없음
