8.운영 | 개발
(CP-02) | J-1102
관리계획서 작성 및 관리 지침 | 개발
품질보증 | 2.17. 관리 계획서
관리계획서는 예방적 프로세스 보안을위한 계획 도구를 제공합니다.
생산, 조립 및 테스트 프로세스의 체계적인 분석을 통해 팀에 의해 구현됩니다.
이 팀은 계획, 제조 및 품질보증 및 기타 관련 부서의 직원으로 구성되어야합니다.
제품 및 공정 FMEA의 결과, 유사한 공정 및 제품에 대한 경험, 개선 방법의 적용은 관리 계획에서 고려되어야합니다.
제품 개발 프로세스에서 사전 시리즈 생산, 안전한 출시 및 시리즈 생산 단계에 대한 관리계획을 수립해야합니다.
ZF에서 요구하는 경우 프로토 타입에 대한 제어 계획을 작성해야합니다
특별한 특성의 경우 샘플 계획 빈도는 수량을 기준으로합니다
(예 : 50 개 중 5 개). "레이아웃 검사 및 기능 테스트 / 연간 재 검증"이 관리 계획에 포함되어야합니다.
자세한 내용은 4.3 절을 참조하십시오.
제어 계획을 준비하는 프로세스에 대한 자세한 설명은 VDA Volume 4 및 AIAG APQP에 포함되어 있습니다. | 없음
J-1100
개발업무 규정 | 개발 | 2.18. 제품 및 프로세스 개발 출시
공급업체는 제품 및 프로세스 개발의 개별단계에 대한 릴리스를 평가하고 문서화해야합니다.
각 단계에서 이러한 평가 결과는 요청된 계획 문서에 설명되어야합니다
(양식 참조). F2 – PSPP 에서 다운로드 할 수 있습니다. ZF 인터넷 웹 사이트-https://www.zfsachskorea.co.kr/). | 없음
