측정시스템 평가 지침

L-4102
공정능력 운영 지침 | 개발
품질보증 | 2.19. 생산 제어 조정 - PPK 1.67이상
기본 원칙으로 모든 제품 및 공정 특성이 중요하며, 이를 준수해야합니다.
특수한 특성에는 공정능력 증명이 필요합니다.
이를 위해 공급업체는 통계적 공정 관리 (SPC)와 같은 적절한 방법으로 이러한 특성을 모니터링해야합니다.
공정능력을 달성 할 수없는 경우 100 % 검사를 수행해야합니다.
측정 할 수 없거나 제품을 파괴함으로써 만 측정 할 수있는 특수특성은 적절한 방법으로 모니터링하고 문서화해야합니다.
시험 간격과 무작위 샘플의 크기를 결정하고 계획 해야합니다.
연속 생산의 특성에 대한 계획된 모니터링은 ZF와 합의되어야합니다. 이 정보는 통제 계획에 문서화되어야합니다. | 없음
