설비관리 규정 | 개발
생산기술 | 2.20. 플랜트, 도구, 설비 및 장비의 계획 및 조달
제조에 필요한 모든 공장, 시설, 도구, 비품 및 장비는 계약 수량을 충족하도록 계획 및 조달되어야합니다.
늦어도 초기 샘플링 날짜까지 배치되어야합니다. 내부 및 외부 운송 수단뿐만 아니라 다른 모든 장비도 고려되어야합니다. | 없음
