J-1101
공정FMEA 작성 및 관리 지침 | 개발 | 2.21. 청결
특정 요구사항에 따라 전체 프로세스 체인에 걸친 모든 유형의 오염 및 그 원인을 FMEA에서 고려해야합니다.
또는 공급자가 특정 청정도 FMEA를 수행 할 수 있습니다. 하위 공급업체, 기계 제조업체 및 서비스 제공 업체도 고려해야합니다.
제품, 포장 및 모든 프로세스(보관, 취급, 운송등)는 먼지 발생, 먼지 축적, 먼지 흔적 및 오염을 방지하는 방식으로 설계되어야
합니다. 계획된 적용에 영향을 미칠 가능성이있는 유해 물질의 사용은 보고되어야하며 ZF의 승인이 필요합니다. | 없음
J-1102
관리계획서 작성 및 관리 지침 | 개발
품질보증 | 2.22. 검사 계획
공급업체는 관리계획서을 기반으로 각 작업에 적합한 검사 장비로 검사할 모든 특성을 포함하는 검사 계획을 작성해야합니다.
또한 검사 빈도 및 결과 문서 유형은 검사계획에 정의 되어야합니다. | 없음
