L-2200
신뢰성 시험업무 규정 | 개발
품질보증 | 2.23. 검사 장비의 기획 및 조달
공급업체는 도면, 표준, 사양 등에 표시된 모든 특성에 대해 적절한 검사 장비를 사용하여 검사 방법을 결정합니다.
조달 프로세스는 PPF/PPAP 제출 및 적합성 시점까지 필요한 검사 장비를 사용할 수 있도록 계획해야합니다.
검사과정의 확인되었습니다. 서비스 제공 업체의 외부검사 및 테스트도 계획해야합니다.
외부 서비스 제공 업체는ISO / IEC 17025 또는 유사한 국가 표준에 따라 인증을 받아야합니다.
검증은 VDA Volume 5 또는 AIAG MSA의 요구 사항에 따라 수행되어야합니다.
에 MSA 결과 외에도 ZF는 선택된 경우 측정 정렬을 요청하거나 수행 할 수 있습니다. | 없음
L-3101
측정시스템 평가 지침

L-4102
공정능력 운영 지침 | 개발
품질보증 | 2.24. 기능 연구 - 공정 성능분석
공급업체는 자동차 표준 VDA Volume 2, VDA Volume 4 또는 AIAG book SPC 중 하나에 따라 기계 성능 연구 및 공정 능력 연구를
수행하는 데 동의해야합니다.
다음 설명은 VDA에 따른 것입니다. AIAG의 대체 정의에 유의하십시오.
 1)공정 능력 지수에 대한 최소 요구 사항 :
 •기계 능력 / 단기 공정 능력 Cm / Cmk 1.67
 •예비 공정 능력 Pp / Ppk 1.67
 •공정 능력 / 장기 공정 능력 Cp / Cpk 1.33 , 다른 요구 사항은 ZF가 공급 업체와 합의합니다.
2)기계 능력 연구 / 단기 능력
기계 성능 연구는 PPF / PPAP 제출 시점까지 모든 검증이 가능하도록 계획되어야합니다.
3)예비 공정 능력 연구
예비 공정능력 연구의 평가는 ZF와 달리 합의하지 않는 한 각각 5개의 샘플로 구성된 최소 25 개의 하위 그룹에서 제공되어야합니다
한정적 검사의 경우 ZF와 공급 업체간에 달리 합의하지 않는 한 샘플 크기는 최소 300 개 연속 조각입니다.
일반적으로 100 % 분류 또는 어떤 형태의 실수 교정과 같은 격리는 ZF와 달리 합의하지 않는 한 프로세스 Ppk가 예비 능력을 입증 할
때까지 계속되어야합니다.
4)공정 능력 연구 / 장기 공정 능력
장기 공정능력 연구는 위에서 언급한 요구사항에 따라 결정될 수 있는 즉시 ZF에 제출되어야합니다.
또한 요청시 공정 능력 연구 결과를 제출해야합니다
5)중심 생산
중심 생산은 조정될수있는 특성. 능력이없는 공정의 경우, 100 % 검사/분류 또는 어떤 형태의 실수 교정은 공정 Cpk가 장기 능력을
입증 할 때까지 계속되어야합니다.
측정 불확도는 다음과 같은 경우 사양 한계에서 공제됩니다
 • 공정 능력이 없어 100 % 검사가 필요한 기능 / 특성
 • 충분한 공정 잠재력 (Cp / Pp)을 보여 주지만 공정이 중앙에 있지 않고 조정할 수없는 공정 (예 : 스탬핑) | 없음
L-1100
설비관리 규정 | 개발
생산기술 | 2.25. 예방 및 예측 유지 보수 계획
납품능력을 보장하기 위해 생산장비 및 툴링에 대한 예방 및 예측 유지 보수 시스템을 개발해야합니다.
유지보수 간격 및 유지 보수 범위를 포함하는 유지 보수 계획을 설정해야합니다. 일관된 실행은 서면으로 문서화되어야합니다.
예방적 유지보수 간격을 정의하는 것 외에도 전달 능력에 영향을 미칠 수있는 모든 프로세스에 대한 비상 계획을 수립해야 합니다.
예를들어 용량 제약이있는 기계와 특수 도구가 있습니다. | 없음
8.운영 | 개발
(CP-02) | J-1100
개발업무 규정

J-2100
양산부품승인업무규정

K-1200
협력업체 관리 규정 | 개발 | 2.26. 협력사 및 구매 부품 현황 - 협력사 PPAP 접수
공급업체가 주문을 하위 공급업체에 할당하는 경우 하위 공급업체도이 품질 지침의 요구사항을 충족해야합니다.
여기에는 섹션 2– APQP 고급 제품 품질 계획의 요구사항에 따라 하위 공급업체와의 품질계획 및 피드백 시스템 구현이 포함됩니다.
프로젝트에 대한 자격을 갖춘 하위 공급업체의 사용이 보장되어야합니다.
요구 사항이 충족되지 않으면 개선계획을 정의해야합니다. 구현은 전체 제품의 PPF / PPAP 승인전에 보장 됩니다.
특별한 프로세스도 고려되어야합니다. 섹션 2.34 – CQI / 특별 프로세스의 자격을 참조하십시오.
사용 된 모든 하위 공급 업체 목록은 규정된 양식을 사용하여 ZF에 제출해야합니다. F2.26 에서 다운로드 할 수 있습니다.
ZF 인터넷 웹사이트-https://www.zfsachskorea.co.kr/ . 승인 된 각 하위 공급 업체가 서명 한 PPF / PPAP 표지의 사본은 공급
업체의 PPF / PPAP 제출에 포함되어야합니다.
품질계획 프로세스의 상태는 정기적으로 제시되어야합니다.
구매한 부품의 생산부품 승인 절차 (PPF / PPAP)가 전체 제품의 생산 공정 및 제품 승인 전에 완료되도록 활동을 구성해야 합니다. | 없음
M-3100
완성품 관리 규정

M-2100
식별 및 추적성관리 규정 | 개발
생산
영업 | 2.27. 물류 센터
원칙적으로 ZF는 공급업체와 물류 계약을 체결합니다.
그러한 합의가 이루어졌는지 여부에 관계없이 차이가 명시적으로 합의되지 않는한 다음 최소 요구 사항이 적용됩니다.
1)라벨링을 포함한 포장 계획 - 포장사양결정서
공급업체는 구성요소를 포장하고 의도한 목적에 맞지 않을 경우 포장을 개선 할 책임이 있습니다.
포장은 육로, 항공, 해상 등의 운송을 견딜 수있을만큼 충분히 견고하고 도착할 수 있도록 설계되어야합니다.
손상이나 오염없이 시간. 계획된 포장 유형은 PPF / PPAP 또는 시리즈 생산 납품전에 충분한 시간내에 공급업체의 이니셔티브에 따라
ZF와 합의해야합니다.
다음 ZF 표준을 준수해야합니다.
 • "일반 포장 규정 물류, 환경 보호" (ZFN 9004-1)
 •“Global Logistics Directive” (GLD)
둘 다 다운로드 및 검토 할 수 있습니다. 
ZF 인터넷 웹 사이트-https://www.zfsachskorea.co.kr/). 요청시 현장 별 세부 규정이 적용됩니다
2)부식 방지
환경과의 상호작용에 의해 손상 될 수있는 모든 제품은 적절하게 보호되어야합니다.
계획된 부식 억제제 (필요한 경우) 사용에 대한 승인은 공급업체의 주도에 따라 ZF와 적시에 조정되고 PPF/PPAP 제출에 포함되어야
합니다.
3)재료 흐름
배치의 혼합을 방지하고 배치, 원자재 부품, 하위 공급업체로부터 구매한 부품 및 공급업체 자체 생산부품을 추적 할 수 있도록 모든
프로세스와 배송에서 "선입 선출"원칙을 따라야 합니다.
공급업체는 ZF에서 하위 공급업체까지 제품의 추적 가능성을 보장해야합니다.
에 대한 이를 위해 부품 또는 용기는 배치 식별번호 및 개정상태와 함께 적절한 방식으로 라벨을 부착 해야합니다.
개정 상태는 납품서에 명시되어야합니다.
4)청결
공급업체는 부품 및 포장의 청결에 대한 책임이 있으며 ZF의 청결사양을 고려해야합니다.포장은 부품을 오염으로부터 보호해야합니다.
모든 포장재는 가능한 한 재활용, 재사용 또는 반환이 가능해야합니다.
포장 및 청결에 관한 추가 요구사항은 ZF 글로벌 물류 지침(검토 가능 ZF 인터넷 웹 사이트-https://www.zfsachskorea.co.kr/ ).
ZF에서 요구하는 경우 공급자는 전자부품의 포장이 다음을 준수하는지 확인해야합니다. ESD 특정 요구 사항 (정전기 방전). | 없음
M-2100
식별 및 추적성관리 규정 | 개발
생산
영업 | 2.28. 추적성
공급업체는 단일 부품, 배치 생산 또는 최대 8시간 생산을 추적 할 수 있도록 정의 된 프로세스를 설정하여 전체 공급망에서 원자재까지
각 생산 단계 및 검사 로트로 돌아갑니다. / 구매 한 부품.
추적성 계획은 공급업체의 이니셔티브에 대해 ZF와 합의하고 PPF / PPAP 제출 전에 충분한 시간 내에 설치되어야합니다.
추적성에 대한 ZF 특정 요구 사항을 고려해야합니다. | 없음
