F-2100
사내 자격관리 규정 | 개발
생산
품질경영 | 2.29. 인원
1)용량 요구 사항
직원은 프로젝트와 생산 모두를 위해 적시에 계획되어야합니다.
계획은 프로젝트 관리와 생산을 시작할 때 충분한 용량을 사용할 수 있도록 수행되어야합니다
2)자격
새 역이 설치되거나 역이 변경 될 때 직원은 새로운 조건에 따라 교육을 받아야합니다. 해당 검증은 문서화되어야합니다.
임시/계약 인력이 배치되면 작업장을 고려하여 사전에 위험 분석을 수행해야합니다. 이 직원은 그에 따라 교육을 받아야합니다. | 없음
