개발업무 규정

J-1103
작업표준서 작성 및 관리 지침 | 개발
생산 | 2.30. 역 출시 - 제조공정 설계출력
공급자는 PPF/PPAP전에 모든 제조 및 조립 스테이션을 해제해야합니다.
그렇게하는 동안 다음사항에 나열된 항목의 가용성과 적합성이 보장되어야합니다.
 • 능력 연구
 • 오류 시뮬레이션 완료 및 문서화 (예 : 자동 테스트 장비 검증)
 • 완전하고 유효한 작업 문서 (예 : 작업 시트, 제어 계획, 검사 계획 등)
 • 운영 재료 및 유지 관리 계획
 • 검사 장비
 • 운송 수단 (지게차, 대차 등)
 • 부품의 개정 수준을 나타내는 첨부 문서와 함께 자료 제공
검사는 적절한 체크리스트를 사용하여 수행되어야합니다.
모든 생산 및 조립작업이 포함되어야합니다. 편차가있는 경우 문서화해야합니다.
시정 및 개선 조치를 실행하기 위한 책임을 정의하고 목표 기한을 설정해야합니다.
정의된 조치를 완료 한 후 이전에 식별된 편차를 고려하여 또 다른 검사를 수행해야합니다. 결과도 문서화되어야 합니다.
PPF/PPAP에 대한 릴리스는 검사 결과가 성공한 후에만 발생할 수 있습니다. 이 릴리스는 문서화되어야합니다 | 없음
8.운영 | 개발
(CP-02) | J-1100
개발업무 규정 | 개발 | 2.31. 제조 프로토 타입
1)프로토 타입에 대한 일반 요구 사항
프로토 타입 부품의 경우,최초 배송 및 수정(색인/품목 번호)의 경우 프로토 타입 검사보고서(치수, 성능, 공정 데이터 등)를 제출
해야합니다. 이를 위해 초기 샘플링 양식 VDA Volume 2 또는 AIAG PPAP는 ZF 요구 사항에 따라 사용됩니다.
이 보고서에서 모든 도면 특성 또는 수정 범위는 각각 적어도 하나의 부분에서 확인되어야합니다.
그 외에도 ZF는 개별사례에서 필요한 문서 범위를 지정합니다.
프로토 타입 공급자와 생산 공급자가 다른 경우, 프로토 타입 공급자는 계약상 동의하는 경우 프로토 타입 제작에서 수집 한 프로세스
지식을 생산 공급자와 공유해야합니다.
검증을 위해 부품을 생산하기 위해 설정된 프로세스는 ZF의 사전 서면 동의 및 승인없이 변경 될 수 없습니다.
변경 요청은 섹션 1.11 – 제품 또는 프로세스 변경 사항에 따른 변경 관리 요구 사항을 준수해야합니다
프로토 타입 배송은 요청 된 양식을 통해 표시 및 문서화되어야합니다.
(F2.31B) , 사용 가능 ZF 인터넷 웹 사이트-https://www.zfsachskorea.co.kr/.
2)프로토 타입에 대한 위치 및 구성 요소 별 요구 사항
ZF의 요청에 따라 ZF에서 정의한 특수특성 및 추가특성은 프로토 타입 단계에서 주문수량으로 100 % 문서화됩니다.
이러한 특성은 도면에서 식별됩니다. ZF 수령 공장에서 요청하는 경우 다음 추가 요구 사항이 충족되어야합니다.
※프로토 타입 1 : 각 배치에 대해 모든 특수 특성 (자세한 내용은 섹션 1.9 및 2.11
참조)이 배송된 부품의 15 %(반올림 수량)에 대해 측정되고 문서화되어야합니다.
측정된 값에 추가하여 각각의 평균과 범위가 표시되어야합니다. 이 요구 사항에서 벗어나는것은 다음과 같은 상황에서만 가능합니다.
a)특성은 도구 관련:생산은 유사한 부품(재료,치수 및 공차)에 대해 이미 기계성능 값을 사용할 수있는 양산 기계 및 도구에서 이루어
집니다.
b)시리즈 생산에서 나오는 부품 : 이것이 적용된다면, 각각의 두 부분에있는 모든 특성 배송을 측정하고 문서화해야합니다.
이 경우 각각의 평균값과 양산 범위를보고해야한다. 측정 값 및 기타 요청 데이터(평균값, 범위, 성능 값 및 도구에 따른 특성)는 지정된
형식 ( F2.31A – 다운로드 가능 ZF 인터넷 웹 사이트-https://www.zfsachskorea.co.kr/) 또는 이에 상응하는 형식.
※프로토 2 : 각 프로토 타입 제공에 대한 특수특성에 대한 문서(자세한 내용은 섹션 참조) 1.9 및 2.11) 및 추가 합의 된 특성은 5개
부품으로 제공됩니다. 이에서 벗어난 수량은 ZF 수령 공장에서 결정합니다. 측정 된 값은 지정된 양식을 사용하여 문서화되어야합니다. 
F2.31A (다운로드 가능 ZF 인터넷 웹 사이트-https://www.zfsachskorea.co.kr/) 또는 이에 상응하는 형식. | 없음
J-1100
개발업무 규정 | 개발 | 2.33. 용량 확인 (속도로 실행)
실행 속도(R@R )는 연속 생산조건에서 성능중심의 시험 실행입니다.
R@R의 목적은 공급업체가 필요한 제품을 생산할 수 있다는 증거를 제공하기 위해 공급업체 능력에 대한 ZF 요구사항이 충족되었음을
입증하는 것입니다.
볼륨을 기존 용량으로 사양에 맞추고 잠재적인 프로세스 약점을 식별합니다.
1)R@R을 수행하는 잠재적 이유
 • ZF 요구 사항
 • 신제품/신규 공급 업체 • 제품, 프로세스 또는 장비의 변경 • 용량 증가 • 도구 및 / 또는 장비 재배치 • 공급 업체 성능 문제
달리 합의하지 않는한 R@R은 ZF에 공급되는 모든 생산재료에 적용됩니다. R@R 도구(F2.33) ZF에서 지정한 것을 사용합니다.
카탈로그 부품은 이 R@R에서 제외됩니다. 요구 사항. R@R 수행에서 예외가 발생하는 경우, 각 부품에 대한 공급자 능력이 보장되고
공급자가 서명한 별도의 능력 약속과 함께 문서화됩니다.
R@R은 모든 공정단계에서 또는 개별 병목/중요한 공정단계에 중 실시한다.
개별 프로세스 단계로 제한되는 경우 이유를 문서화 해야합니다.
R@R 결과는 공급 업체와 ZF가 서명한 ZF R@R 확인 양식을 사용하여 제공됩니다 .
PPF / PPAP 문서 에는 서명 된 " R @ R Verification" 양식 이 필요합니다.
이 양식은 ZF R@R 도구의 일부이며 다음 사이트에서 다운로드 할 수 있습니다. ZF 인터넷 웹 사이트-https://www.zfsachskorea.co.kr/ | 없음
8.운영 | 개발
(CP-02) | IATF16949 프로세스 | 전부서 | 2.34. CQI / 특수 프로세스의 자격 - CQI15 평가
AIAG(Automotive Industry Action Group)는 CQI 지침(지속적인 품질 개선)을 발행합니다.
CQI 형식은 www.aiag.org. AIAG에 따라 특수 프로세스를 처리하는 공급업체 및 하위 공급업체의 경우 관련 CQI 지침을 고려해야합니다.
결과에 "즉시 조치 필요"또는 "실패 결과"유형의 결과가 표시되면 공급업체는 즉시 ZF에 알리고 조치 계획을 제공해야합니다
1)열처리 공정
열처리의 중요한 성능으로 인해 ZF는 열처리 공급업체의 사용을 통제하기위한 조치를 취했습니다.
ZF는 공급업체가 이전에 ZF에서 승인한 열처리 하위 공급업체를 사용하도록 권장합니다.
ZF에서 승인하지 않은 열처리 공급업체를 사용해야하는 경우 공급업체는 RFQ(견적 요청)시 기본 기술 워크북과 함께 유효한 CQI-9
자체 평가를 제공해야합니다.
/ 타당성 조사 또는 APQP 단계 중. ZF는 선택한 열처리 공급 업체를 감사한 다음 승인하거나 거부 할 권리를 보유합니다.
CQI 평가는 자체평가이며 적어도 매년 CQI 요구사항에 따라 수행되어야합니다.
이러한 자체평가 및 격차를 해결하기 위한 실행계획은 요청된 통신 플랫폼을 통해 ZF에 전자적으로 제출되어야합니다 | 없음
J-1100
개발업무 규정 | 개발 | 2.35. 새 부품에 대한 성숙도 보증
새 부품의 경우 ZF는 VDA 볼륨 성숙도 수준 보증(제품생성 – 새 부품에 대한 성숙도 수준 보증)의 요구사항에 따라 프로젝트를 처리 할
권리를 보유합니다.
이 경우에 ZF는 공급자에게 연락할 것입니다.
게이트는 ZF 관련 이정표에 따라 계획됩니다. 자세한 내용은 아래 다이어그램과 관련 양식을 참조하십시오.
