양산부품승인업무규정 | 개발 | 3. PPAP / PPF 생산 부품 승인 프로세스
PPAP(생산 부품 승인 프로세스)는 VDA 볼륨 2(PPF) 또는 AIAG PPAP의 생산 부품 릴리스 프로세스를 기반으로합니다.
ZF는이 두 절차 중 하나 또는 유사한 절차를 지정할 권리를 보유합니다.
생산부품 승인 프로세스(PPF / PPAP)를 시작하기 전에 모든 프로세스 및 품질 계획 활동이 완료되었는지 확인해야합니다. | 없음
3.1. 초기 샘플
초기 샘플은 일련의 생산조건(플랜트, 기계, 작동 재료 및 테스트 장비, 가공 조건)에서 제조 및 테스트 된 제품입니다.
모든 특성에 대한 테스트 결과는 초기 샘플 보고서에 기록되어야합니다. 문서화 할 부품의 수량은 ZF와 합의해야합니다.
초기 샘플은 합의된 날짜까지 ZF 수령공장에 제출되어야하며 섹션에 명시된 제출 수준에 따라 초기 샘플 검사 보고서 및 문서를
포함해야합니다.
3.3 – 제출 수준. 초기 샘플은 지정된 양식을 사용하여 명확하게 식별되어야합니다. (F3.1B) 에서 다운로드 할 수 있습니다.
ZF 인터넷 웹 사이트-https://www.zfsachskorea.co.kr/
특성을 식별하기 위해 초기 샘플 검사 보고서와 ZF가 발표한 첨부된 현재 도면에 일치하는 번호를 사용해야합니다.
단일 구성요소를 포함하여 ZF 설계에 따라 제조된 어셈블리의 경우 초기 샘플 검사가 필수이며 ZF에 제출되어야합니다.
공급업체 자체 설계에 기반한 제품의 경우 공급업체는 어셈블리를 샘플링하여 ZF에 제출해야합니다.
단일 구성품 및 필요한 경우 부분 조립품에 대해서도 초기 샘플링을수행해야합니다.
ZF는 필요에 따라이 문서를 검토 할 수 있습니다.
ZF는 PPF / PPAP 승인 프로세스 중에 감지되지 않은 ZF 사양의 편차에 대해 나중에 불만을 제기 할 권리가 있습니다. | 없음
