J-2100
양산부품승인업무규정 | 개발 | 3.2. 초기 샘플의 정의
위에서 언급한 표준 및 규정에 따라 다음 변경사항이 공급업체 또는 하위 공급업체에 적용되는 경우 PPF/PPAP 승인 프로세스가
필요합니다.
 • 제품을 처음 주문한 경우 (주문에 표시됨)
 • 공급 업체가 하청 업체를 변경 한 후
 • 제품 수정 후 영향을받는 모든 특성
 • 도면 색인 수정 후 영향을받는 모든 특성
 • 배달 중지 후
 • 배송 중지 후 배송 중단 이후 (업무 보류 중)
 • 1 년 이상의 배송 중단 후
 • 1 년 이상의 생산 중단 후
 • 생산 절차 / 공정이 변경된 경우
 • 새/개조된 성형장비(예 : 스탬핑, 롤링, 프레싱, 단조, 성형 장비, 여러 다이 / 몰드 및 / 또는 여러 다이 / 몰드의 경우 각각에 대해
 • PPF / PPAP(캐비티 / 클러스터) 승인 생산의 모든 유형의 재배치 또는 새롭거나 재배치 된 기계 및 / 또는 작동 재료의 사용 후
 • 대체 재료를 사용하고 페인트, 가죽, 목재와 같은 재료에 적용되는 제품 외관 속성의 디자인 변경 후… 외관 사양이없는 경우.
 (예 :색, 냄새…)
 • 시험/검사방법 또는 새로운 기술의 변경 (승인 기준에 영향 없음). 테스트 방법 변경시 공급업체는 새로운 방법이 이전 (이전) 방법과
 동등하거나 더 나은 결과를 제공한다는 증거를 보유해야합니다.
• ZF에서 요청하는 경우 기존 툴링 또는 장비의 업그레이드, 보수, 재배치 후 생산
접근 및 범위에 대한 예외는 ZF와 합의한 경우에만 허용됩니다 (예 :다음과 같은 경우).
 • 1 년 이상의 배송 또는 생산 중단
 • 소규모 생산 배치, 판매 후 서비스 부품
 • 표준 및 카탈로그 부품 | 없음
3.3. 제출 수준
일반적으로 ZF에서 별도로 지정하지 않는 한 제출 수준3이 적용됩니다.
벌크 재료(예 : 그리스, 오일, 과립…)의 경우 ZF에서 달리 명시하지 않는한 관련 AIAG 벌크 재료 체크리스트를 통해 제출해야합니다.
제출 수준을 설명하는 양식 (F3.3A) 에서 다운로드 할 수 있습니다. ZF 인터넷 웹 사이트-https://www.zfsachskorea.co.kr/ | 없음
3.4. 3D 데이터 모델에 따른 초기 샘플링
해당되는 경우 유효한 3D 데이터 모델을 기반으로 측정을 수행해야합니다.
측정 지점의 수는 모든 치수를 확실하게 결정할 수있는 방식으로 선택해야합니다.
측정에 대한 세부사항은 ZF와 합의해야합니다. 
그만큼 2.7절에서 확인 및 결정된 특성– 제품 설명은 초기 샘플과 함께 문서화되어야합니다 | 없음
3.5 연속 생산 릴리스를위한 제품 및 프로세스 평가 - 양산 생산 (개발 완료 보고)
공급 업체는 VDA "제품 및 프로세스에 대한 연속 생산 성숙도 평가 매트릭스"를 사용하여 연속 생산에 대한 제품 및 프로세스
성숙도에 대한 서면 자체 평가를 수행해야합니다. | 없음
3.6. 초기 샘플 문서
요청된 제출 수준(섹션 3.3 참조)에 따른 초기 샘플 문서는 초기 샘플과 동시에 제공되어야합니다.
ZF는 공급자에게 AIAG / VDA에서 요구하는 것 외에 추가 문서 및 양식이 포함된 검증 패키지를 제출하도록 요구할 수 있습니다.
초기 샘플 문서의 누락, 부정확, 불완전 또는 지연 제출은 공급업체 성과 실패로 기록되며 공급업체의 성과 등급에 영향을 미칩니다.
완전한 문서가 없는 초기 샘플은 처리되지 않으며 이후 비용이 발생하여 공급 업체에 청구됩니다. | 없음
8.운영 | 개발
(CP-02) | J-1100
개발업무 규정

J-2100
양산부품승인업무규정 | 개발 | 3.7. 초기 샘플의 편차
문서, 기록 및 초기 샘플 부품은 모든 사양이 충족된 경우에만 제출할 수 있습니다.
편차가 있는 경우 공급자는 먼저 요청된 양식을 사용하여 ZF로부터 서면 허가를 받아야합니다.
F4.5A에서 다운로드 가능 ZF 인터넷 웹 사이트 또는 통신 플랫폼 (1.13 –전자 데이터 교환에 기반한 비즈니스 프로세스 참조)에서 제출
된 문서에 첨부하십시오.
편차 승인이 없는 편차가 있는 초기 샘플은 ZF에서 처리되지 않습니다.
위반 요청과 함께 다음을 제출해야합니다.
 • 8D 보고서
 • 계획된 연속 상태로 돌아 가기위한 실행 계획
 • 정상 생산을 재개 할 수있는 계획된 시점 | 없음
3.8. 재료 데이터보고
ZF에 대한 모든 공급에 대해 법적보고 의무가 적용되는 곳에 중요한 데이터를 제공해야합니다.
PPF / PPAP 요구사항이 적용되는 경우 공급업체는 IMD (International Material Data System) ( www.mdsystem.com ).
COEMS 프로그램 공급 업체 (중국 오리지널 장비 제조업체) 및 중국 시장을위한 글로벌 OEM (Original Equipment Manufacturer)과의
합작 투자는 또한 CAMDS 시스템 (China Automotive Material Data System)에 물질 및 물질 정보를보고해야합니다. www.camds.org ).
공급업체는 IMDS 및 ZF에서 요구하는 경우 CAMDS를 새로운 비즈니스 수주시 가능한 한 빨리 ZF에 제출해야합니다.
그러나 어떠한 경우에도 PSW (Part Submission Warrant) 이전 또는 PPF / PPAP 프로세스의 일부로 제출해야합니다.
공급 업체 IMDS / CAMDS 정보는 ZF 검토 및 승인을 받아야합니다. 누락 된 재료 데이터는 거부로 이어집니다.
추가 정보는 ZF Norm에서 사용할 수 있습니다. ZFN 9010 과 보충 1에 ZF 인터넷 웹 사이트-https://www.zfsachskorea.co.kr/
중국 자동차 시장을 위해 차량 조립을 위해 배송된 부품의 경우 공급업체는 공인 연구소에서 "End-of-Life / ELV 테스트 보고서"를
제공하여 중국 국가 표준 GB / T 30512를 준수하는지 확인해야합니다. -2014-자동차 금지 물질에 대한 요건.
법적 또는 기타 요구사항의 변경은 ZF에 제공된 데이터(IMDS 제출,CAMDS 제출, SDS, 준수 선언 등)의 재확인 및 후속 업데이트를
프롬프트해야합니다.
비 자동차 제품 또는 ZF 애프터 마켓에 대한 공급에는 다른보고 요구 사항이 적용될 수 있습니다. | 없음
3.9. PPF / PPAP 제출 프로세스
PPF / PPAP 문서는 ZF 주문 공장에서 요청한 프로세스를 통해 제출되어야합니다.
PPF / PPAP 요소 목록과 함께 "제출 수준"양식에 명시된 요소 번호 순서대로 제출해야합니다.
불완전하거나 잘못된 PPF / PPAP 문서는 거부됩니다. | 없음
4. 연속 생산 요구 사항 - 양산 생산
4.1. 소개
제조 프로세스가 성공적으로 검증되면 (PPF / PPAP 승인) 연속 생산단계가 시작됩니다.
이 단계에서 각 공급업체 및 하위 공급업체가 완전히 인식하고 따라야하는 여러 요구사항이 있습니다.
이 단계의 주요 영역은 다음 섹션에서 자세히 설명합니다. | 없음
