4M변경관리 규정

KPI지표 관리 | 개발
품질보증 | 4.2. 불만 처리
공급업체는 잠재적인 안전, 품질 또는 배송문제를 인지한 경우 영향을받을 수 있는 모든 ZF공장 및 공급망의 기타 관련 당사자에게
즉시 알려야합니다.
1)불만 관리 : ZF는 우려의 원인과 심각도에 따라 불만을 분류합니다. ZF는 또한 여러 Q-KPI를 사용하여 모든 배송의 품질을 평가합니다.
자세한 내용은 공급 업체 Q-KPI에 대한 ZF 설명에서다운로드 할 수 있습니다.
ZF 인터넷 웹 사이트-https://www.zfsachskorea.co.kr/ ZF가 불만을 제기 한 후 격리 조치를 즉시 실행해야합니다.
격리 상태 (8D 보고서의 D3)는 늦어도 1영업일 이내에 ZF에보고되고 주기적으로 업데이트되어야합니다.
ZF 공장 및 영향을 받을 가능성이 있는 ZF공급망의 기타 관련 당사자는 공급 업체가 즉시 알려야합니다.
보고는 ZF에서 지원하는 통신 플랫폼 (섹션 1.13 참조) 또는 요청된 양식을 통해 이루어집니다. F4.2A 에서 다운로드 할 수 있습니다.
ZF 인터넷 웹 사이트-https://www.zfsachskorea.co.kr/ 근본 원인분석은 항상 적절한 문제 해결 방법을 사용하여 수행하고 ZF에
제출해야합니다.
자세한 분석(예 : Ishikawa, 3x5 이유, 오류 시뮬레이션 등)도 수행됩니다. 언제 요청되면이 문서는 ZF에 제출되어야합니다.
완성 된 8D 보고서는 늦어도 10영업일 이내에 제출 되어야 합니다.
필요한 경우 공급업체와 ZF간에 합의하여 다른 목표 날짜를 설정할 수 있습니다.
8D 프로세스는 ZF의 승인에 의해서만 종료 될 수 있습니다.
2)불만 후 인증된 부품 또는 포장식별 : 클린 포인트 정보는 ZF 담당자에게 즉시 결정 및 전달됩니다.
또한 8D 보고서에 문서화되어야합니다.
불만으로 인해 100 % 검사 또는 테스트를 거친 창고 및 진행중인 작업의 후속 배송은 표시 또는 라벨을 부착해야합니다.
이는 적절한 라벨 또는 양식을 통해 수행되어야합니다.
F4.2B(다운로드 가능 ZF 인터넷 웹 사이트 ). 영구적인 시정조치가 성공적으로 구현 될 때까지 모든 포장 단위에는 요청 된 라벨
또는 양식이 명확하게 표시되어야합니다.
개별 부품의 마킹 유형은 요청된 "인증 부품"라벨 또는 양식에 설명되고 8D 보고서에 포함 된 ZF 수령 공장과 합의해야합니다
3)현장의 불만 : 현장에서 불만이 있는 경우 APQP 단계에서 이전에 계획된 관련 조치를 수행해야합니다.
조사 과정(NTF-No Trouble Found)에서 결함이 발견되지 않은 부품의 경우 VDA Volume"공급망의 공동 품질 관리 – 마케팅 및 서비스
– 현장 고장 분석”에 따라 조치를 취해야합니다. 섹션 2.9도 참조하십시오.
ZF는 분석을 위해 반환된 모든 자료의 소유권을 보유합니다.
결정을 위해 파괴적인 테스트가 필요한 경우 근본 원인, ZF는 테스트 프로세스 전에 알려야합니다.
ZF의 서면 허가없이 분석을 위해 반환된 부품의 파기 행위는 엄격히 금지됩니다.
불만 사항과 관련된 자료 (실패 책임이 불확실하거나 분쟁이있는 경우)는 서면으로 달리 합의하지 않는 한 ZF에 반환하여 보관
해야합니다. | 없음
4)공급 업체 품질 성과 측정 및 개선
공급업체가 제로결함과 100 % 정시납품을 달성하고 유지할 것이 ZF의 기대입니다.
ZF는 출시성과, 배송성과, 불만 및 보증성과, 연속 생산 품질성과를 평가하도록 설계된 핵심 성과지표 (KPI)를 사용하여 공급 기반의
성과를 지속적으로 모니터링합니다.
ZF는 다음을 위해 이러한 KPI를 모니터링하고 평가합니다.
 • 공급 업체 성과 비교 허용 및 활성화
 • 공급 업체 개발 활동에 필요한 전략 및 이니셔티브 도출
 • 공급 업체 품질 성과를 지속적으로 개선
이러한 성과 지표 및 관련 지표는 ZF 인터넷 웹 사이트-https://www.zfsachskorea.co.kr/ (공급 업체 품질 성과 결정 – Q-KPI 참조).
ZF는 공급업체 커뮤니케이션 플랫폼에서 매월 공급업체 성과 데이터를 업데이트합니다.
공급업체는 ZF 통신 플랫폼을 통해 성과 데이터에 액세스해야합니다.
공급업체의 성과 상태는 향후 소싱 결정 및 지속적인 개선 노력에 집중할 영역을 식별하기 위해 고려됩니다.
