통계적 기법적용 규정 | 개발
품질보증 | 4.3.레이아웃 검사 및 기능 테스트 / 연간 재 검증 - 도면 내 명시되어 있는 전치수 연 1회이상 검사
모든 제품은 매년 레이아웃 검사 및 기능 테스트 (재 검증)를 받아야합니다.
ZF와 달리 합의했습니다. ZF와 이전에 계약한 후 ZF와 유사한 부품에 대해 제품 그룹( "패밀리")별로 재 인증을 수행하거나, 현재 시리즈
생산 테스트에 대한 결과를 포함 할 수 있습니다.
예를 들면 다음과 같습니다.
 • 주기적 시리즈 생산 릴리스
 • 제품 감사 (집계, 모듈, 구성 요소, 부품 등)
 • 초기 항목 및 최종 항목 테스트에 대한 기록
 • SPC 평가
 • 초기 샘플링
 • 입고 물품 검사
유효한 ZF 사양은 재 검증 / 재 검증의 기초입니다. 레이아웃 검사 및 기능 테스트는 일반적으로 다음을 포함합니다.
 • 치수
 • 재료
 • 함수
다른 시험항목은 ZF수령 공장과 합의해야합니다. 레이아웃 검사 및 기능 테스트/연간 재 검증은 ZF 초기 샘플 검사와 함께 계획되고
제시되어야하며 관리계획서에 포함되어 야합니다.
결과는 문서화되고 ZF가 평가할 수 있도록 제공해야합니다. 이를 위해 초기 샘플 검사 보고서는 VDA Vol. AIAG의 2 (PPF) 또는 PPAP
(PSW)를 사용해야합니다.
테스트 결과가 음성이면 공급 업체는 즉시 ZF에 연락해야합니다
ZF에 대한 위험, 오류 원인 및 시정 조치를 명시해야합니다. 레이아웃 검사 결과는 요청시 ZF에 제출되어야합니다 | 없음
4.4.안전한 실행 - 양산 후 90일 (HKMC 100일 작전) : APQP3
1)소개 : 안전출시 계획은 제품 공급의 초기 단계에서 ZF와 공급업체를 모두 보호하도록 설계되었습니다.
새 프로세스에서 잠재적인 문제의 증상을 감지하고 새 출시에 결함이 없는지 확인하기 위해 안전한 출시 프로세스를 구현해야합니다.
이를 달성하기 위해 안전한 출시 계획은 계획 단계. Safe Launch 동안 지정된 특성 및 기타 합의 된 특성에 대해 검사 및 모니터링
빈도를 늘려야합니다.
2)팀 : 공급업체는 부품의 적합성을 보장하고 적시에 내부 불량품을 분석 및 제거하기 위해 정의된 책임이 있는, 권한있는 팀을 지명합니다.
3)안전한 실행 기간 : 일반적으로 안전 출시 단계는 PPF / PPAP 제출로 시작하여 ZF에서 별도로 지정하지 않는 한 생산 시작
(ZF 고객의 SOP) + 90 일까지 연장됩니다. 프로그램 기간은 제품 수량에 따라 지정 될 수도 있습니다.
4)종료 및 재시작 기준 : 전체 안전출시 단계 동안 무결점 소모품과 합의된 모든 기준을 충족하면, 공급업체가 안전출시 단계를 종료 할
수 있습니다. 안전 실행단계에서 발견 된 모든 결함은 이벤트를 "0"으로 재 설정하고 안전 실행단계가 다시 시작됩니다.
5)선적 서류 비치 : Safe Launch 양식을 작성한 후 검사원시 데이터 및 기능 차트는 ZF에서 정의한 정보 교환 플랫폼을 통해 합의 된
빈도로 ZF에 제출해야합니다 (ZF 인터넷 웹 사이트 https://www.zfsachskorea.co.kr/ – 섹션 1.13 참조).
6)안전한 실행 프로세스 설명 : 안전한 실행 프로세스에 대한 자세한 설명은 다음 사이트에서 검토 할 수 있습니다.
ZF 인터넷 웹 사이트-https://www.zfsachskorea.co.kr/ | 없음
