제출된 정보는 공급자가 정상 생산으로 복귀할 계획 인시기를 표시해야합니다.
편차 승인을 기반으로한 모든 배송에는 모든 화물 캐리어에 추가 식별 라벨이 있어야합니다.
이를 위해 요청 된 양식 F4.5B 사용됩니다 (다운로드 가능 ZF 인터넷 웹 사이트-https://www.zfsachskorea.co.kr/). | 없음
