개발 | 1.16. 재 작업 및 수리 된 제품 관리
제품의 재 작업 및 수리를 위해 공급업체는 문서화된 프로세스를 보유하고 위험 분석 (예 : FMEA)을 수행해야합니다.
PPF / PPAP 단계 동안 합의된 제어계획에 포함되지 않은 수리 또는 재 작업은 섹션 1.11
 – 제품 또는 프로세스 변경 사항에 따라 프로세스 변경으로 간주됩니다
