구매 | 1.10. 협력사 관리 - 사업부간 하위업체 연관
하위 공급업체는 최종 제품의 품질에 상당한 영향을 미칩니다. ZF 공급업체는 문서화된 공급업체 관리 시스템을 갖추고 있어야합니다
ZF 공급업체는 하위 공급업체의 개발을 담당합니다. 하위 공급업체(직접 구매 공급 업체 및 아웃소싱 프로세스 포함)를 관리하고 성과를
모니터링하는 데 필요한 프로세스, 역량 및 자원을 보유해야합니다.
또한 하위 공급업체가 이 지침에 포함된 모든 요구사항을 준수하는지 확인해야합니다.
하위 공급업체를 변경하려는 의도는 다음과 같습니다.
ZF에 미리 잘 전달되었습니다. 하위 공급업체의 변경은 ZF의 사전 승인을받은 경우에만 구현할 수 있습니다.
섹션 1.11 – 제품 또는 프로세스 변경을 참조하십시오. 이후 생산 부품 승인 프로세스 (PPF / PPAP)가 수행됩니다.
ZF는 품질에 관한 하위 공급업체의 감사 및 평가에 참여할 권리가 있습니다.
ZF 공급업체, ZF의 고객 또는 ZF가 지정한 제 3자와 공동으로 관리 시스템, 프로세스, 제품등. 사전 통지가 제공됩니다.
ZF가 하위 공급업체 감사에 참여한다고해서 ZF 공급업체가 하위 공급업체를 적절히 모니터링하고 개발할 책임이 면제되는것은 아닙니다. | 없음
