품질보증
생산 | 1.17. 부적합품 처분 
공급업체는 재 작업 또는 수리 대상이 아닌 부적합 제품의 처분을 위한 문서화 된 프로세스를 보유해야합니다.
요구사항을 충족하지 않는 제품의 경우 공급자는 ZF와 달리 합의하지 않는 한 폐기전에 폐기 할 제품을 사용할 수 없게되었는지
확인해야합니다.
ZF 또는 승인 된 제 3자에게 직접 보내지 않고 ZF에 공급하기 위해 생산된 모든 구성요소는 ZF와 달리 합의하지 않는한 구성 요소가
의도한 용도에 사용되지 않도록하기 위해 재활용전에 사내에서 폐기해야합니다.
여기에는 스크랩, 생산 시험 중 생산 된 부품, 엔지니어링 샘플링, 모든 설정 및 검사 조각이 포함됩니다.
공급업체는 ZF의 사전 승인없이 부적합 제품을 서비스 또는 기타 용도로 전환해서는 안됩니다.
공급업체는 이 관행에 대한 준수를 보장해야하며, 모든 하위 공급업체가 이 관행을 준수하도록 보장해야합니다.
이 정책을 하위 공급업체에 전달한 증거는 요청시 보관되고 ZF에 제시되어야합니다 | 없음
A-5100
내부심사 규정 | 품질경영 | 2.32. 감사 계획 - 품질 및 구매 2자 심사원 점검
공급업체는 정기적인 실행과 내부 제품 및 프로세스 감사의 범위를 정의하는 감사 프로그램을 발행해야합니다.
VDA Volume 6 part 5 또는 VDA Volume 6 part 3 또는 이와 동등한 절차가 적용됩니다. 하위 공급업체의 감사도 고려해야합니다.
공급업체는 자동차 표준을 충족 할 수있는 자격을 갖춘 감사관을 보유해야합니다.
특수 프로세스 및 제품과 관련된 특정 감사 요구사항 (CQI, 고객 특정 요구 사항, SPICE 평가 등)도 고려되어야합니다. | 없음
