총무 | 1.6. 정부 규제 준수,기업의 사회적 책임 및 지속 가능성
ZF는 공급업체와 하위 공급업체가 비즈니스 윤리, 근무 조건, 인권 및 환경 리더십에 대한 최소한의 기대치를 채택하고 준수하기를
기대합니다. 이러한 기대는 ZF의 "비즈니스 파트너 원칙" 에서 다운로드 할 수 있습니다.
ZF 인터넷 웹 사이트-https://www.zfsachskorea.co.kr/ (비즈니스 포털 >> 자재 관리 >> 규정 준수). 
ZF의 요청 또는 감사시 공급 업체는 이러한 요구 사항을 준수했다는 증거를 제공해야합니다. | 없음
ISO14001 인증 | 총무 | 1.8. 환경
적용 가능한 각 환경 규정을 준수하고 공급업체의 환경 조건을 지속적이고 효율적으로 개선하는 효과적인 환경관리는 공급 보안에
필수적인 기여입니다. ZF는 환경보호에 전념합니다.
모든 ZF공장은 ISO 14001 인증을 받았습니다. 따라서 우리는 공급업체가 환경관리 시스템을 구현하여 환경보호에 대한 자발적인
노력을 보여줄 것을 기대합니다.
파운드리, 아연 도금 및 페인트 공장을 운영하는 공급업체, 인쇄 회로기판(PCB) 제조업체, 1차 및 2차 전지, 전자부품 또는 화학물질 또는
염료, 수지, 가죽 등을 사용하여 표면 처리를 수행하는 공급업체는 그리스 및 오일에 따라 인증서를 제공해야합니다.
ISO 14001 또는 이와 동등한 시스템. 이 인증서를 사용할 수없는 경우 인증 일정을 제시 해야합니다.
1)제품 관련 환경 및 안전 데이터 시트 요구 사항
모든 공급품은 해당 법률, 환경 및 수입 규정
(예 : EU REACH (EC) No.1907/2006, EU ELV Directive 2000 / 53 / EC, 자동차의 금지 물질에 대한 중국 요구 사항 GB / T 30512- 2014)
ZF Norm 9003 "금지 및 규제 물질의 통제"및 ZFN 9004-1“일반 ZF 포장 사양; 물류, 환경 보호”가 적용됩니다
요청시 공급업체는 제품에 적합한 재활용 및 폐기 개념을 제공해야합니다.
ZF 제품의 수명주기 평가를 위해 추가 데이터 (예 : 에너지 소비 및 배출)를 요청할 수 있습니다.
공급업체는 물질 및 혼합물에 대한 안전 데이터 시트 (SDS)를 미국의 화학 물질 분류 및 라벨링에 대한 GHS
(Globally Harmonized System) 및 유럽 분류, 라벨링 및 포장 (CLP)규정에 따라 제출해야합니다.
위험물로 분류된 제품(예 : 가압식 충격 흡수기, 불꽃 제품, 리튬 배터리 등)의 경우 공급업체는 ZF가 취급 및 운송 요구사항을 충족 할 수
있도록 SDS 또는 유사한 정보를 제공 해야합니다
