SAE-J1879 | 자동차 전기 / 전자의 견고성 검증 핸드북 모듈
ZVEI 문서 | 자동차 애플리케이션에서 반도체 장치의 견고성 검증을위한 핸드북, 자동차 전기 / 전자 모듈의 견고성 검증을위한 핸드북
규칙 및 표준 – VDA 볼륨 | VDA – 독일 자동차 산업 협회 / www.vda-qmc.de
AIAG 표준 및 규칙 (CQI 포함) | www.aiag.org/
ZF 내부 그룹
표준 및 규칙 | ZFN 9003 | ZF Norm 9003“금지 및 규제 물질 관리"
ZFN 9004-1 | 일반 ZF 포장 사양; 물류, 환경 보호
ZFN 9010 | 재료 데이터 시트 생성에 대한 허용 기준 , 국제 재료 데이터 시스템 (IMDS)
ISO / IEC 17025에 대한 Gerneral 요구 사항 테스트 및 교정 실험실의 역량
GLD | 글로벌 물류 지침
3공장 제트에프삭스코리아 CSR반영한 요구사항 매트릭스 양식 (포뮬러)
※필요한 모든 커뮤니케이션 / 작업 양식 및 관련 문서는 다음 사이트에서 현재 버전으로 다운로드 할 수 있습니다.
 ZF 인터넷 웹 사이트- https://www.zfsachskorea.co.kr/
 그만큼 QD83 웹 페이지 ZF의 공개 웹 사이트에서 https://www.zf.com/ 다음을 따라 "비즈니스 포털 / ZF 공급 업체위원회" 경로 페이지 하단.
 이 플랫폼에서 사용할 수있는 양식과 문서는 ZF 표준을 나타내며, 최소 요구 사항을 다룹니다. 다른 양식은 최소 ZF 요구 사항을 충족하고 ZF 수신 공장이
 이러한 양식의 사용을 승인 한 경우 사용할 수 있습니다. 공급 업체는 항상 최신 버전의 양식을 사용하도록해야합니다', 11
WHERE NOT EXISTS (SELECT 1 FROM regulation_sections WHERE reg_code = 'QM' AND sort_order = 11);
INSERT INTO regulation_sections (reg_code, section_title, section_body, sort_order)
SELECT 'QM', '1. 적용범위', '본 품질 환경 매뉴얼에 기술한 품질 환경 경영시스템은 조직의 내.외부 이슈와 이해관계자의
요구 및 기대를 포함하여 당사에서 제공하는 제품의 계약된 생산, 제품 및 서비스에 이르는
전 과정을 대상으로 하여 ISO 9001:2015/ IATF 16949:2016 / ISO 14001:2015 의 요구사항을
적용한다.
적용범위는 다음과 같다.
품질 : 연료 주입구 및 파이프 제조(본사 및 1공장) / 엔진용 및 변속기용 파이프 제조 (2공장)
쇽업쇼바용 파이프 제조(3공장)
환경 : 파이프의 생산 및 가공
적용제외 : 본사,2공장,3공장 모두 8.3항 제품설계는 고객사 도면에 의한 공정개발만 진행되어
제외함.', 12
WHERE NOT EXISTS (SELECT 1 FROM regulation_sections WHERE reg_code = 'QM' AND sort_order = 12);
INSERT INTO regulation_sections (reg_code, section_title, section_body, sort_order)
SELECT 'QM', '2. 목 적', '본 품질 환경 매뉴얼은 ㈜티피씨 (이하 ‘당사’라 한다.)이 품질 환경 시스템을 정함에 있어
KS Q ISO 9001:2015 / IATF 16949:2016 / KS I ISO 14001:2015 규격에서의 요구사항을
적용하여 양품을 적시에 제공하고 고객요구사항을 충족시키는 것은 물론 안전보건 활동을
통한 기업의 손실을 최소화하고 환경 친화적 기업을 달성 할 목적으로 기술되어 지속적인
개선과 부적합을 방지하기 위한 시스템을 포함한다.
본 매뉴얼은 당사에서 고객의 요구사항을 적절하고 명확하게 정하여 당사의 품질 환경
경영시스템에 관련된 모든 프로세스에 적용할 수 있도록 변환하고 고객만족의 달성을
확실하게 행할 수 있도록 구성한다.', 13
WHERE NOT EXISTS (SELECT 1 FROM regulation_sections WHERE reg_code = 'QM' AND sort_order = 13);
INSERT INTO regulation_sections (reg_code, section_title, section_body, sort_order)
SELECT 'QM', '3. 책임과 권한', '이 품질 환경 매뉴얼은 대표이사의 책임과 권한으로 제정, 개정 및 폐기한다.', 14
WHERE NOT EXISTS (SELECT 1 FROM regulation_sections WHERE reg_code = 'QM' AND sort_order = 14);
INSERT INTO regulation_sections (reg_code, section_title, section_body, sort_order)
SELECT 'QM', '4. 승인, 발행 및 배포', '이 품질 환경 매뉴얼의 승인, 발행, 배포는 문서 관리 규정에 따르나, 승인 절차에서 최종
승인은 최고 책임자인 대표이사가 행한다.', 15
WHERE NOT EXISTS (SELECT 1 FROM regulation_sections WHERE reg_code = 'QM' AND sort_order = 15);
INSERT INTO regulation_sections (reg_code, section_title, section_body, sort_order)
SELECT 'QM', '5. 시 행', 'ISO 9001:2015 / IATF 16949:2016 / ISO 14001:2015 에 의해 만들어진 이 품질 환경 경영
시스템 매뉴얼은 2020년 08월 03일부터 시행한다.', 16
WHERE NOT EXISTS (SELECT 1 FROM regulation_sections WHERE reg_code = 'QM' AND sort_order = 16);
INSERT INTO regulation_sections (reg_code, section_title, section_body, sort_order)
SELECT 'QM', '1. 인용규격', '아래 인용문서에 포함된 조항은 매뉴얼의 본문에 인용됨으로써, 매뉴얼의 일부로 구성된다.
인용문서의 발행일자가 명시되어 있는 경우, 이 발행본의 차후 수정이나, 개정은 적용하지
않는다.
- ISO 9001 : 2015 품질경영시스템
- ISO 14001 : 2015 환경경영시스템', 17
WHERE NOT EXISTS (SELECT 1 FROM regulation_sections WHERE reg_code = 'QM' AND sort_order = 17);
INSERT INTO regulation_sections (reg_code, section_title, section_body, sort_order)
SELECT 'QM', '1. 용어 및 정의', '일반산업의 용어 및 정의와 KS Q ISO 9001:2015, KS I ISO 14001:2015 에 제시된
용어 및 정의는 다음과 같다.', 18
WHERE NOT EXISTS (SELECT 1 FROM regulation_sections WHERE reg_code = 'QM' AND sort_order = 18);
INSERT INTO regulation_sections (reg_code, section_title, section_body, sort_order)
SELECT 'QM', '2. 품질환경안전보건 경영시스템 기본사항 및 용어', '', 19
WHERE NOT EXISTS (SELECT 1 FROM regulation_sections WHERE reg_code = 'QM' AND sort_order = 19);
INSERT INTO regulation_sections (reg_code, section_title, section_body, sort_order)
SELECT 'QM', '2.1 품질환경 관련 용어', '(1) 품질 (Quality)
고유 특성의 집합이 요구사항을 충족시키는 정도
(2) 요구사항 (Requirement)
명시되어 있는, 보통 묵시적으로 이해되고 있는, 또는 의무로서 요구되어 있는
니즈 또는 기대
(3) 등급 (grade)
동일한 용도의 제품, 프로세스 또는 시스템에 대하여 상이한 품질 요구사항에 부여되는
범주 또는 순위(rank)
(4) 고객만족 (customer satisfaction)
고객의 요구사항이 충족되어 있는 정도에 관한 고객의 인식
(5) 능력 (capability)
제품에 대한 요구사항(3.1.2)을 충족시킬 제품을 실현하는 조직, 시스템 또는
프로세스의 능력
(6) 환경(environmental)
공기, 물, 천연자원, 식물 군, 동물 군, 인간 및 이들 요소들 간의 상호관계 등을 포함하여
회사가 움직이고 있는 주변 상황
(7) 환경측면
환경과 상호작용을 할 수 있는 회사의 활동, 제품 및 서비스의 요소
(8) 환경영향
회사의 환경측면이 전체적 또는 부분적으로 환경에 좋은 영향을 미치거나, 또는 나쁜
영향을 미칠 수 있는 환경 변화
(9) 오염예방
부정적인 환경영향을 감소시키기 위하여 어떠한 형태의 오염물질 또는 폐기물의 발생,
방출 또는 배출의 회피, 저감 또는 관리(분리 또는 조합하여)를 위한 프로세스, 관행,
기술, 재료, 제품, 서비스 또는 에너지의 활용', 20
WHERE NOT EXISTS (SELECT 1 FROM regulation_sections WHERE reg_code = 'QM' AND sort_order = 20);
INSERT INTO regulation_sections (reg_code, section_title, section_body, sort_order)
SELECT 'QM', '2.2 경영관련 용어', '(1) 시스템 (system)
상호 관련되거나 상호 작용하는 요소의 집합
(2) 경영시스템 (management system)
방침 및 목표를 수립하고 그 목표를 달성하기 위한 시스템
(3) 품질 환 경영시스템 (quality/environmental management system)
품질환경안전보건 방침을 개발하고, 이행하고, 달성하고, 검토하고, 유지하기 위한
조직구조, 계획하는 활동, 책임, 관행, 절차, 과정 및 자원을 포함하는 경영시스템으로서
리스크를 다루기 위한 조치 계획 및 실행에 필요한 개발, 관리 등 총괄경영시스템 중의
부분을 말한다.
(4) 품질환경방침 (quality/environmental policy)
조직의 전반적인 품질환경성과와 관련된 조직의 의도 및 원칙을 밝힌 성명, 이것은
품질환경목표 및 세부목표를 설정하고 행동하기 위한 기본 틀을 제공한다.
(5) 품질환경목표 (quality/environmental objective)
품질환경방침에 근거하여 조직이 달성하고자 스스로 설정한 총괄적인 품질환경목표로서,
실행 가능한 것은 정량화 한다.
(6) 품질환경성과
조직의 품질환경방침, 목표 및 세부목표에 근거하고 품질환경측면에 대한 조직의 관리와
관련된 품질 환경 경영시스템의 측정 가능한 결과를 말한다.
(7) 경영 (management)
조직을 지휘하고 관리하기 위한 조정된 활동
(8) 품질환경경영시스템 심사
조직의 품질환경경영시스템이 조직에 의해 설정된 품질환경경영시스템감사기준과
부합하는지 여부를 결정하기 위해 증거를 객관적으로 획득하고 평가하며 경영자에게
이러한 과정의 결과를 전달하기 위한 시스템적이고 문서화된 증명 과정을 말한다.
(9) 품질환경세부목표
조직의 전체 또는 일부에 적용 가능한 세부적인 성과요건으로 실행 가능한 것은 정량화
한다. 이것은 품질환경목표로부터 설정되며 품질환경목표의 달성을 위해 정해지고
이와 부합될 필요가 있다.
(10) 최고경영자 (top management)
최고 계층에서 조직을 지휘하고 관리하는 개인 또는 그룹
(11) 품질기획 (quality planning)
품질경영의 일부로서, 품질목표를 설정하고 품질목표를 달성하기 위해 필요한 운영
프로세스 및 관련자원을 규정하는데 초점을 맞추는 것
(12) 품질관리 (quality control)
품질경영의 일부로서, 품질 요구사항을 충족하는데 초점을 맞추는 것
(13) 품질보증 (quality assurance)
품질경영의 일부로서, 품질 요구사항이 충족될 것이라는 신뢰를 제공하는데 초점을
맞추는 것
(14) 품질개선 (quality improvement)
품질경영의 일부로서, 품질 요구사항을 충족시키는 능력을 증진하는데 초점을 맞추는 것
(15) 지속적 개선 (continual improvement)
회사의 품질환경방침에 따라 전체적인 품질환경성과의 개선을 성취하기 위해 품질 환경
경영시스템을 추진해나가는 과정
(16) 효과성 (effectiveness)
계획한 활동이 실현되어 계획한 결과가 달성된 정도
(17) 효율성 (efficiency)
달성된 결과와 사용된 자원과의 관계
(18) 리스크
리스크는 주변 환경의 변화를 포함하는 모든 불확실성의 영향이며 잠재적인 사건과
결과 또는 이들의 조합으로 특정지어져 사건의 결과와 연관된 발생가능성의 조합으로
표현 한 것을 말한다.
(19) 리스크 기반사고
효과적인 품질환경안전보건경영시스템을 달성하기 위한 필수적인 것으로 잠재적
부적합을 제거하기 위한 예장 조치의 모든 부적합의 분석, 그리고 부적합의 영향에
적절한 재발 방지 조치까지 포함하는 것
(20) 기회
회사가 고객을 유치하고 새로운 제품 및 서비스를 개발하며 낭비를 감소시키거나
생산성을 개선하도록 하는 등 의도한 결과를 달성하기에 유리한 상황의 결과로
나타날 수 있는 모든 것으로 말한다.', 21
WHERE NOT EXISTS (SELECT 1 FROM regulation_sections WHERE reg_code = 'QM' AND sort_order = 21);
INSERT INTO regulation_sections (reg_code, section_title, section_body, sort_order)
SELECT 'QM', '2.3 조직관련 용어', '(1) 조직 (organization)
책임, 권한 및 상호관계가 정해진(배치된) 인원 및 시설의 집단
(2) 조직구조 (organizational structure)
인원간의 책임, 권한 및 상호관계의 배치(arrangement)
(3) 기반구조 (infrastructure)
조직의 운영을 위하여 필요한 시설, 장비 및 서비스에 관한 시스템
(4) 업무환경 (work environment)
업무가 수행되는 조건의 집합
(5) 고객 (customer)
제품을 제공 받는 조직 또는 사람
(6) 공급자 (supplier)
제품을 제공하는 조직 또는 사람
(7) 이해관계자 (interested party)
회사의 품질환경안전보건경영성과에 의해 영향을 받거나 그 성과와 관련된 인원 또는
단체, 회사의 지속가능성에 심각한 리스크를 제공하는 모든 사람들을 말한다.', 22
WHERE NOT EXISTS (SELECT 1 FROM regulation_sections WHERE reg_code = 'QM' AND sort_order = 22);
INSERT INTO regulation_sections (reg_code, section_title, section_body, sort_order)
SELECT 'QM', '2.4 프로세스 및 제품관련 용어', '(1) 프로세스 (process)
입력을 출력으로 변환시키는 상호 관련되거나 상호 작용하는 일련의 활동
(2) 제품 (product)
프로세스의 결과
(3) 프로젝트 (project)
착수일과 종료일이 있는, 조정되고 관리되는 일련의 활동으로 구성되어, 시간, 코스트 및
자원의 제약을 포함한 특정요구사항에 적합하는 목표를 달성 수행되는 독특한 프로세스
(4) 설계 및 개발 (design and development)
요구사항을 제품, 프로세스 또는 시스템의 규정된 특성 또는 시방서로 변환하는
일련의 프로세스
(5) 절차 (procedure)
활동 또는 프로세스를 수행하기 위하여 규정된 방법', 23
WHERE NOT EXISTS (SELECT 1 FROM regulation_sections WHERE reg_code = 'QM' AND sort_order = 23);
INSERT INTO regulation_sections (reg_code, section_title, section_body, sort_order)
SELECT 'QM', '2.5 특성관련 용어', '(1) 특성 (characteristic)
그것을 식별하기 위한 특성
(2) 품질특성 (quality characteristic)
요구사항에 관련되는 제품, 프로세스 또는 시스템 고유의 특성(3.5.1)
(3) 신인성 (dependability)
가용성(availability) 및 그 영향을 미치는 요인
(신뢰성, 보전성 및 보전지원의 능력을 기술하기 위하여 사용하는 용어의 총칭)
(4) 추적성 (traceability)
고려대상이 되어 있는 것의 이력, 적용 또는 소재를 추적할 수 있는 것', 24
WHERE NOT EXISTS (SELECT 1 FROM regulation_sections WHERE reg_code = 'QM' AND sort_order = 24);
INSERT INTO regulation_sections (reg_code, section_title, section_body, sort_order)
SELECT 'QM', '2.6 적합성관련 용어', '(1) 적합 (conformity)
요구사항을 충족하고 있는 것
(2) 부적합 (nonconformity)
요구사항을 충족하지 않는 것
(3) 결함 (defect)
의도된 용도 또는 규정된 용도에 관련되는 요구사항을 충족하지 않는 것
(4) 예방 (preventive)
잠재적인 부적합 또는 기타 바람직하지 아니한 잠재적인 원인을 제거하기 위한 것
(5) 시정조치 (corrective action)
발견된 부적합 또는 기타 발견된 바람직하지 않은 상황의 원인을 제거하기 위한 조치
(6) 시정 (correction)
발견된 부적합을 제거하기 위한 조치
(7) 재작업 (rework)
요구사항에 적합시키기 위해 부적합제품에 대하여 취하는 조치
(8) 재등급 (regrade)
최초의 요구사항과 다른 요구사항에 적합하도록 부적합 제품에 대해 취하는 조치
(9) 수리 (repair)
의도된 용도에 쓰일 수 있도록 하기 위해 부적합 제품에 대해 취하는 조치
(10) 폐기 (scrap)
최초에 의도한 용도를 불가능으로 하기 위해 부적합 제품에 취하는 조치
(11) 특채 (concession)
규정 요구사항에 적합하지 않은 제품의 사용 또는 불출을 허용하는 것
(12) 불출 (release)
프로세스의 다음 단계 진행을 허용하는 것', 25
WHERE NOT EXISTS (SELECT 1 FROM regulation_sections WHERE reg_code = 'QM' AND sort_order = 25);
INSERT INTO regulation_sections (reg_code, section_title, section_body, sort_order)
SELECT 'QM', '2.7 문서관련 용어', '(1) 정보 (information)
의미가 있는 데이터
(2) 문서 (document)
정보 및 정보 지원 매체
(3) 시방서 (specification)
요구사항을 기술한 문서
(4) 품질매뉴얼 (quality manual)
조직의 품질경영시스템을 규정한 문서
(5) 기록 (record)
달성된 결과를 기술하거나 수행한 활동의 증거를 제공하는 문서', 26
WHERE NOT EXISTS (SELECT 1 FROM regulation_sections WHERE reg_code = 'QM' AND sort_order = 26);
INSERT INTO regulation_sections (reg_code, section_title, section_body, sort_order)
SELECT 'QM', '2.8 조사관련 용어', '(1) 객관적 증거 (objective evidence)
사물의 존재 또는 진실을 입증하는 자료
(2) 검사 (inspection)
필요에 의하여 측정, 시험 또는 게이지 사용을 동반하는 관찰 및 판정에 의한 적합성 평가
(3) 시험 (test)
절차에 따라 하나 또는 그 이상의 특성을 결정하는 것
(4) 검증 (verification)
규정된 요구사항이 충족되었음을 객관적 증거의 제시를 통하여 확인하는 것
(5) 타당성확인 (validation)
특정의 의도된 용도 또는 적용에 관한 요구사항이 충족되었음을 객관적 증거의 제시를
통하여 확인하는 것
(6) 자격인정 프로세스 (qualification process)
규정된 요구사항을 충족시키는 능력을 실증하는 프로세스
(7) 검토 (review)
설정된 목표를 달성하기 위한 검토대상의 적절성, 타당성 및 유효성을 판정하기
위해 시행되는 활동', 27
WHERE NOT EXISTS (SELECT 1 FROM regulation_sections WHERE reg_code = 'QM' AND sort_order = 27);
INSERT INTO regulation_sections (reg_code, section_title, section_body, sort_order)
SELECT 'QM', '2.9 심사관련 용어', '(1) 심사 (audit)
심사 기준이 충족되어 있는 정도를 판정하기 위하여 심사 증거를 수집하고 그것을
객관적으로 평가하기 위한 체계적이고, 독립적이며 문서화된 프로세스
(2) 심사프로그램 (audit program)
어떤 목적의 달성을 위하여 정해진 기간 내에 실시하도록 계획된 일련의 심사
(3) 심사기준 (audit criteria)
대조를 위한 자료로 사용되는 일련의 방침, 절차 또는 요구사항
(4) 심사증거 (audit evidence)
심사 기준에 관련되고 또 검증할 수 있는 기록, 사실의 기술 또는 기타의 정보
(5) 심사 발견사항 (audit findings)
수집된 심사 증거를 심사 기준에 대비하여 평가한 결과
(6) 심사결론 (audit conclusions)
심사 목적과 모든 심사 발견 사항을 고려한 후에 심사팀이 제출한 심사의 결론
(7) 심사 의뢰자 (audit client)
심사를 요청하는 조직 또는 사람
(8) 피심사자 (auditee)
심사를 받는 조직
(9) 심사원 (auditor)
심사를 행하는 역량을 가진 사람
(10) 심사팀 (audit team)
심사를 수행하는 1인 이상의 심사원
(11) 기술전문가 (technical expert)
심사의 대상에 관한 고유의 지식 또는 전문적 기술을 제공하는 사람
(12) 적격성 (competence)
지식과 기술을 적용하기 위한 실증된 능력', 28
WHERE NOT EXISTS (SELECT 1 FROM regulation_sections WHERE reg_code = 'QM' AND sort_order = 28);
INSERT INTO regulation_sections (reg_code, section_title, section_body, sort_order)
SELECT 'QM', '2.10 측정프로세스에 대한 품질보증 관련 용어', '(1) 측정관리시스템 (measurement control system)
계측 확인 및 측정 프로세스의 지속적인 관리를 달성하기 위해 필요한, 상호 관련되는
또는 작용하는 일련의 요소
(2) 측정프로세스 (measurement process)
어떤 양의 값을 결정하는 일련의 조작
(3) 도량학적 확인 (metrological confirmation)
측정기기가 의도된 용도에 관한 요구사항에 적합하다는 것을 보장하기 위해 요구되는
일련의 조작
(4) 측정장비 (measuring equipment)
측정 프로세스의 실현에 필요한 측정기기, 소프트웨어, 측정표준, 표준물질 또는
보조장치 또는 그들의 조합
(5) 도량학적 특성 (metrological characteristic)
측정 결과에 영향을 줄 수 있고 그것을 식별할 수 있는 성질
(6) 도량학적 기능 (metrological function)
측정 관리시스템을 정의하고 실행하기 위한 조직적 책임을 갖는 기능', 29
WHERE NOT EXISTS (SELECT 1 FROM regulation_sections WHERE reg_code = 'QM' AND sort_order = 29);
INSERT INTO regulation_sections (reg_code, section_title, section_body, sort_order)
SELECT 'QM', '2.11 자동차 산업을 위한 용어', '(1) 사전제품 품질기획 (APQP)
고객 요구사항을 만족시키는 제품 또는 서비스의 개발을 지원하는 제품 품질기획 프로세스
APQP는 개발프로세스에서 지침으로 역할을 하고 또한 조직과 그들의 고객 간의 결과를
공유하는 표준화 방식으로 역할을 함
(2) 관리계획서 (CP)
제품의 제조를 관리하는데 요구되는 시스템 및 포로세스의 서면 기술
(3) 고객 지정 요구사항 (CSRs)
자동차 산업 QMS 표준의 특정 조항에 연계된 해석 또는 보충 요구사항
(4) 설계-책임 조직
새로운 제품 시방을 제정하거나, 기존 제품 시방을 변경할 수 있는 권한을 가진 조직
비고) 이 책임은 고객의 지정 적용 범위 내에서 설계 성능의 시험 및 검증을 포함한다.
(5) 예측보전
언제 유지보수가 수행되어야 할 것인지를 예측하기 위하여, 장비 조건의 주기적인 또는
지속적인 모니터링 수행을 통해 가동 중에 있는 장비의 조건을 평가하는 일련의 기법들
및 접근법
(6) 예방보전
제조공정설계의 출력으로써 장비고장과 생산에 예정되지 않은 중단의 원인을
제거하기 위해 정기적으로 계획된 활동
(7) 특별 특성
제품의 안전 또는 규제사항 준수, 장착, 기능, 성능, 요구사항 또는 제품의 후속 공정에
영향을 미칠 수 있는 제품 특성 또는 제조 공정 변수의 분류
(8) 전문분야-=협력 접근법
프로세스를 하나의 팀에 의하여 운영하는데 영향을 주는 모든 이해관계자들로부터
입력사항을 포착하는 방법으로써 이러한 팀은 조직의 인원을 포함하고, 고객 및 공급자
대리인을 포함할 수 있다. 즉 팀멤버는 조직의 내부 또는 외부가 될 수 있다. 상황에 따라
기존팀이나 특별팀을 사용할 수 있다. 팀에 대한 입력은 조직 입력사항 및 고객 입력사항
모두를 포함할 수 있다.
(9) 고객 요구사항
고객에 의해 규정된 모든 요구사항 (예를 들면, 기술적, 상업적, 제품 및 제조공정 관련 요구사항
일반 용어 및 조건, 고객 지정 요구사항 등)
심사받는 조직이 자동차 제조업체, 자동차 제조업체 자회사 또는 자동차 제조업체와의 합작회사
인 경우 관련 고객은 자동차 제조업체 그들의 자회사 또는 합작 회사가 규정한다.
(10) 내장된 소프트 웨어
내장된 소프트웨어는 고객이 지정한 자동차 부품 (일반적으로 컴퓨터 칩 또는 기타 비 활성 기억
장치)에 저장되거나 시스템 설계의 일부로 기능을 제어하는 특수 프로그램이다. IATF 16949 인증의
범위와 관련하여 내장된 소프트웨어에 의해 제어되는 부분은 자동차 응용 프로그램 용(즉, 승용차,
영업용 경량 차량, 대형 트럭, 버스, 오토바이; “자동차” 자격을 갖춘 것에 대한, IATF 승인 획득
및 유지를 위한 규칙 5판, 섹션 1.0 IATF 16949 인증자격 참조)으로 개발되어야 한다.
비고: 제조 공정의 모든 측면(예: 구성부품 또는 자재를 제조하는 기계)을 제어하는 소프트웨어는
내장된 소프트웨어의 정의에 포함되지 않는다', 30
WHERE NOT EXISTS (SELECT 1 FROM regulation_sections WHERE reg_code = 'QM' AND sort_order = 30);
INSERT INTO regulation_sections (reg_code, section_title, section_body, sort_order)
SELECT 'QM', '4. 조직의 상황', '', 31
WHERE NOT EXISTS (SELECT 1 FROM regulation_sections WHERE reg_code = 'QM' AND sort_order = 31);
INSERT INTO regulation_sections (reg_code, section_title, section_body, sort_order)
SELECT 'QM', '4.1 조직 및 조직의 상황에 대한 이해', '당사의 목적과 전략적 방향과 관련된 외부와 내부 이슈를 파악하고 의도된 결과를
달성하기 위하여 조직의 능력에 영향을 주는 외부와 내부 이슈 및 환경, 안전보건여건을
포함하여야 하며 지속적으로 정보를 모니터링하고 검토하여야 한다. 해당부서는 다음을
포함한 상황을 이해하여 프로세스에 반영해야 하며 이 프로세스는 조직의 목적과 목표,
지속가능성에 영향을 미치는 요인을 정한다.
(1) 이슈는 긍정적, 부정적 요인을 고려해야 할 조건이 포함 될 수 있다
(2) 국제적, 국가적, 지역적 또는 지방적이든 법적, 기술적, 경쟁적, 시장, 문화적, 사회적 및
경제적 환경에서 비롯된 이슈를 고려함으로써 외부 상황에 대한 이해를 용이하게
할 수 있다
(3) 회사의 가치, 문화, 지식 및 성과와 관련되는 이슈를 고려함으로써 내부 상황에 대한
이해를 용이하게 할 수 있다.
(4) 조직은 기후변화가 조직의 상황과 관련된 이슈인지 여부를 결정해야 한다.', 32
WHERE NOT EXISTS (SELECT 1 FROM regulation_sections WHERE reg_code = 'QM' AND sort_order = 32);
INSERT INTO regulation_sections (reg_code, section_title, section_body, sort_order)
SELECT 'QM', '4.2 이해관계자의 니즈와 기대 이해', '고객 요구사항, 그리고 적용되는 법적 및 규제적 요구사항을 충족하는 제품 및 서비스를
일관성 있게 제공하기 위하여 이해관계자 또는 이해관계자 관련 요구사항에 대한 정보를
모니터링하고 검토하여야 한다.
각 부서는 조직의 능력에 이해관계자가 영향 또는 잠재적 영향을 미치기 때문에 조직은
다음 사항을 고려한다.
(1) 품질 환경 경영시스템에 관련되는 이해관계자
(2) 품질 환경 경영시스템에 관련되는 이해관계자의 니즈와 기대 및 그에서 비롯된
조직의 준수 의무사항.
(3) 조직의 상황을 이해하기 위하여 이해관계자를 파악하고 모든 이해관계자를 고려하여야
한다.
(4) 이해관계자는 자신의 니즈와 기대가 충족되지 않으면 조직의 지속가능성에 심각한
리스크를 제공하는 사람들로 조직은 리스크를 감소시키기 위해 관련 이해관계자에게
요구사황과 결과물을 지속적으로 제공한다
(5) 조직은 조직의 성공이 달려 있는 관련 이해관계자의 지지를 끌어들이고 획득하며
유지한다.
(6) 조직과 관련된 이해관계자에게 기후변화와 관련된 요구사항이 있을 수 있다.', 33
WHERE NOT EXISTS (SELECT 1 FROM regulation_sections WHERE reg_code = 'QM' AND sort_order = 33);
INSERT INTO regulation_sections (reg_code, section_title, section_body, sort_order)
SELECT 'QM', '4.3 품질 환경 경영시스템 적용범위', '(1) 본 매뉴얼은 ㈜티피씨의 품질 환경 경영을 수행하는데 있어서 품질 환경 경영시스템의
근간이 되며, 어떠한 규정 및 표준도 이를 위배 할 수 없다.
다만, 이해관계자가 특별히 요구하는 사항을 본 매뉴얼로써 만족시키기 어려운
경우에는 부속서를 작성하여 운영토록 한다.
(2) 본 매뉴얼의 적용범위는 다음과 같다.
가. 본 매뉴얼은 당 사업장에 한하여 적용되며, 당 사업장에 근무하는 외주가공업체에
대해서도 확대 적용한다.
나. 고객 요구사항과 적용되는 법적 및 규제적 요구사항을 충족하는 제품 및 서비스를
일관성 있게 제공하는 능력을 실증하는 니즈가 있는 경우 모두 적용한다.
다. 시스템 개선 그리고 고객 요구사항과 적용되는 법적 및 규제적 요구사항에 적합함을
보증하기 위한 프로세스를 포함하는 시스템의 효과적인 적용을 통하여 고객만족을
증진 시키고자 하는 경우 적용한다.
품질 : 연료 주입구 및 파이프 제조 / 엔진용 및 변속기용 파이프 제조 / 쇽업쇼바용 파이프 제조
환경 : 파이프의 생산 및 가공
적용제외 : 8.3항 제품설계는 고객사 도면에 의한 공정개발만 진행되어 제외함.
CSR (고객지정요구사항) : 3공장 제트에프삭스코리아 QD-83(2018년)
※ IATF 16949:2016 규격은 필라넥, 인발용 파이프, 엔진 및 변속기용 파이프, 쇽업쇼바용
파이프 제품에 한하여 적용한다. (이하 기울림체)
4.3.1 품질환경안전 경영시스템 적용범위 - 보충사항
현장에 있든 떨어져 있는 지원 기능은 품질환경안전 경영시스템의 범위에 포함한다.
4.3.2 고객 지정 요구사항
고객 지정 요구사항은 조직의 품질환경안전 경영시스템의 범위에 포함되고 평가한다.
(1) 개발 및 영업 팀장은 1회/주 고객사 홈페이지에 접속 및 신제품 개발시 CSR 변경 사항에
대하여 파악 후 대표이사 및 사업부장/ 팀장에게 보고, 승인을 득하여야 한다.
(2) 해당팀장은 변경사항에 대하여 매뉴얼 및 요구사항 매트릭스에 반영하여 개정 후
대표이사 및 사업부장/팀장에게 결재를 득한 후 관련 팀원 교육을 실시 하여야 한다.', 34
WHERE NOT EXISTS (SELECT 1 FROM regulation_sections WHERE reg_code = 'QM' AND sort_order = 34);
INSERT INTO regulation_sections (reg_code, section_title, section_body, sort_order)
SELECT 'QM', '4.4 품질환경안전경영시스템과 그 프로세스', '(1) 개요
해당부서장은 ISO 9001, IATF 16949, ISO 14001 의 요구사항에 부합하게 품질 환경 경영
시스템을 수립, 문서화, 실행 및 유지하고 품질 환경 경영시스템의 효과성을 지속적으로
개선하여야 한다.
(2) 절차
품질 환경 경영시스템을 실행하기 위하여 이 프로세스는 이 규격의 요구사항에 따라
조직에 의해 관리되어야 하며 다음 사항을 실행 하여야 한다.
가. 품질 환경 경영시스템에 필요한 프로세스 및 조직 전반에 걸친 프로세스 적용의 결정
나. 프로세스 순서와 상호작용의 결정
다. 프로세스에 대한 운영 및 관리가 모두 효과적임을 보장하는데 필요한 기준 및
방법의 결정
라. 프로세스의 운영 및 모니터링을 지원하는 데 필요한 자의 결정과 자원의 가용성 보장
마. 프로세스의 모니터링, 적용 가능한 경우 측정 및 분석
사. 프로세스에 대한 계획된 결과와 지속적 개선을 달성하는 데 필요한 조치의 실행
아. 프로세스에 대한 책임과 권한 부여
자. 6.1항 조직에 영향을 줄 수 있는 이슈나 요구사항에 따라 결정된 리스크 및 기회의 조치
차. 프로세스의 평가 그리고 그 프로세스가 의도된 결과를 달성함을 보장하기 위해 필요한
모든 변경사항의 실행
카. 프로세스 및 품질경영시스템의 개선
타. 프로세스의 운용을 지원하기 위하여 문서화된 정보의 유지
파. 프로세스가 계획대로 수행되고 있다는 확신을 갖기 위하여 문서화된 정보의 보유
회사가 요구사항에 대한 제품 적합성에 영향을 미치는 어떠한 프로세스를 외주처리 경우,
회사는 이러한 프로세스가 관리된다는 것을 보장하여야 한다.
이들 외주처리 된 프로세스에 적용되는 관리는 형태와 범위가 품질환경경영시스템 내에서
규정 되어야 한다.
4.4.1 제품 및 프로세스에 대한 적합성
조직은 서비스 부품 및 외주 처리된 부품을 포함하여 모든 제품 및 프로세스가 재료 요구사항에
대한 적합성을 포함하여 모든 해당하는 고객요구사항, 법적 요구사항 및 규제적 요구사항에
적합함을 보장하여야 한다
4.4.2 제품 안전
조직은 제품 안전에 관련된 제품 및 제조공정의 관리에 대한 문서화된 프로세스를 갖추어야
하며, 해당하는 경우 다음 사항을 포함하여야 하지만 이에 국한하지는 않는다.
안전 관련 요구사항 또는 문서의 특별 승인은 고객 또는 조직의 내부 프로세스에 의해
요구될 수 있다.
(1) 법적 요구사항 및 규제적 제품안전 요구사항에 대한 조직에 의한 파악
(2) 항목 (1)에서 요구사항에 대한 고객 통지
(3) 설계 FMEA에 대한 특별 승인
(4) 제품의 안전 관련 특성 파악
(5) 제조 시점에서 제품의 안전 관련 특성 파악 및 관리
(6) 관리 계획서 및 공정 FMEA의 특별 승인
(7) 최고 경영자 그리고 고객 통지를 포함한 책임, 단계적 확대 프로세스 정의 및 정보 흐름 규정
(8) 제품 및 연관된 제조 공정에 관련된 제품안전에 관여하는 인원에 대해 조직 또는
고객이 파악한 교육 훈련
(9) 공정 및 제품 변경사항에서 제품 안전에 대한 잠재적 영향평가를 포함한, 제품 또는
공정 변경사항의 실행 전 승인 받아야 한다.
(10) 고객 지정 출처를 포함한, 공급망 전체에 걸쳐 제품 안전에 관해 고객 요구사항의 이전
(11) 공급망 전체에 걸쳐 제조된 로트에 의한 제품 추적성', 35
WHERE NOT EXISTS (SELECT 1 FROM regulation_sections WHERE reg_code = 'QM' AND sort_order = 35);
