SELECT 'QM', '4.5 관련표준', '(1) 제품안전관리규정(D-1100)
[표 1] 품질환경안전(QES)경영시스템 프로세스', 36
WHERE NOT EXISTS (SELECT 1 FROM regulation_sections WHERE reg_code = 'QM' AND sort_order = 36);
