SELECT 'QM', '5. 리더십', '', 37
WHERE NOT EXISTS (SELECT 1 FROM regulation_sections WHERE reg_code = 'QM' AND sort_order = 37);
INSERT INTO regulation_sections (reg_code, section_title, section_body, sort_order)
SELECT 'QM', '5.1 리더십과 의지표명', '5.1.1 일반사항
최고경영자/사업본부장은 품질환안전보건경경영시스템에 대한 리더십과 의지표명,
개발 및 실행, 그리고 품질 환경 경영시스템에 대한 효과성을 지속적으로 개선하는데
대한 실행의지의 증거를 다음을 통하여 제시 하여야 한다.
(1) 품질환경안전경영시스템의 효과성에 대한 책무를 진다
(2) 법적 및 규제요구사항 뿐만 아니라 고객요구사항 충족의 중요성을 조직과 의사소통
(3) 품질 환경 방침과 목표 수립 및 보장
(4) 조직의 비즈니스 프로세스와 통합
(5) 프로세스 접근법 및 리스크기반 사고의 활용 촉진
(6) 자원의 가용성 보장
(7) 요구사항과의 적합성에 대한 중요성, 의사소통
(8) 품질 환경 경영시스템이 의도한 결과를 달성
(9) 품질 환경 경영시스템의 효과성에 기여하기 위한 인원을 적극참여시키고 지위하고
지원 함
(10) 개선 촉진
(11) 기타 관련 경영자/관리자의 책임분야에 리더십이 적용될 때 리더십을 실증하도록
그 경영자 역할에 대한 지원
(12) 제품실현 프로세스 및 지원 프로세스의 효과성과 효율성 평가 및 개선하기 위한
프로세스의 검토
(13) 조직의 프로세스 및 관련 출력을 관리하는 프로세스 책임자의 파악
※ 조직은 최소한 부패 방지 방침, 종업원 행동수칙, 윤리 에스컬레이션 방침을 포함한
기업 책임 방침인 윤리 규정을 따른다.
5.1.2 프로세스 효과성 및 효율성 : 최고 경영자는 조직의 품질,환경 경영시스템을 평가 및 개선하기
위하여 품질,환경 경영시스템의 효과성 및 효율성을 검토하여야 한다. 그 프로세스 검토 활동 결과는
경영 검토의 입력으로 포함하여야 한다.
5.1.2 고객중시
최고경영자는 다음 사항을 보장함으로써 고객중시에 대한 리더십과 의지표명을
실증하여야 한다.
(1) 최고경영자는 고객 요구사항과 적용되는 법적 및 규제적 요구사항이 결정되고 이해되면
고객만족을 증진시키기 위하여 고객 요구사항과 이 이행됨을 관리 하여야 한다.
(2) 제품 및 서비스 적합성, 고객만족을 증진시키는 능력에 영향을 미칠 수 있는 리스크와
기회를 반영하고 처리 해야 한다.
(3) 고객만족 증진의 중시가 유지되어야 한다.
(4) 영업 부서장은 고객 요구사항을 파악하여 관련조직에 전달 하여야 하며 고객만족을
위하여 정기적으로 고객만족도 평가를 실시 하여야 한다.
(5) 각 부서장은 고객 만족도 평가 결과에 따라 부적합 시 시정조치를 실시한다.', 38
WHERE NOT EXISTS (SELECT 1 FROM regulation_sections WHERE reg_code = 'QM' AND sort_order = 38);
INSERT INTO regulation_sections (reg_code, section_title, section_body, sort_order)
SELECT 'QM', '5.2 방침', '5.2.1 품질 환경 방침의 수립
최고경영자는 품질환경안전방침이 다음과 같이 되도록 보장하여야 한다.
(1) 회사의 목적, 활동, 제품 및 서비스의 특성, 규모, 환경영향, 안전보건에 적합하도록
설정하고 전략적 방향을 지원
(2) 지속적인 개선과 오염예방에 대한 의지를 포함
(3) 회사와 환경측면과 안전보건에 관련된 법규와 그 밖의 요구사항을 준수한다는
의지를 포함
(4) 품질 환경 목표와 세부목표를 수립하고, 검토하는 틀을 제공
(5) 지속적인 적절성을 위하여 연 1회 이상 경영검토 등을 통해 검토 실시
5.2.2 품질 환경 방침에 대한 의사소통
품질 환경 방침은 다음과 같아야 한다.
(1) 문서화된 정보로 이용 가능하고 유지되어야 함
(2) 조직 내에서 모든 인원에게 의사소통 되도록 게시 또는 교육하도록 함
(3) 해당되는 경우, 이해관계자가 이용 가능하도록 함', 39
WHERE NOT EXISTS (SELECT 1 FROM regulation_sections WHERE reg_code = 'QM' AND sort_order = 39);
INSERT INTO regulation_sections (reg_code, section_title, section_body, sort_order)
SELECT 'QM', '5.3 조직의 역할, 책임 및 권한', '5.3.1 최고경영자
최고경영자는 ㈜티피씨를 대표하는 최고경영자로써 회사운영에 대한 최종 책임과
권한을 가지며 품질 환경 경영시스템의운영에 있어서 다음사항을 관장한다.
(1) 고객요구사항뿐만 아니라 법적 및 규제요구사항 충족에 대한 중요성을 조직에 전달
(2) 품질환경안전방침의 수립
(3) 품질환경안전 목표수립 및 부서별 세부목표가 수립되도록 독려
(4) 경영검토의 수행
(5) 필요한 자원의 공급 및 가용성을 보장
(6) 품질환경안전시스템의 개선 및 경영자 검토 수행
(7) 조직의 책임과 권한 설정
(8) 고객 요구사항을 충족하는 것을 보장하기 위해 책임 및 권한을 갖는 인원을 할당
(9) 제품 요구사항과 시정 조치에 권한과 책임을 갖는 인원 보장
5.3.2 사 장
회사 업무를 총괄하며, 최고경영자의 경영방침에 맞추어 방책을 수립, 실행 및 관리한다.
(1) 품질환경안전경영시스템의 효율성 점검
(2) 고객중심으로 고객만족을 실현하기위한 노력
(3) 최고경영자 부재 시 품질 환경 경영 대리 업무수행
(4) 각 부서업무 관리 감독
(5) 기타 최고경영자를 보좌하며, 최고경영자 부재 시 최고경영자 업무수행/지시사항 수행
5.3.3 기술연구소장
(1) 품질 환경 경영시스템이 ISO 9001, IATF 16949, ISO 14001 규격에 따라 수립되고
유지됨을 지원
(2) 최고경영자에게 개선의 필요성을 포함하여 품질 환경 경영시스템의 성과에 대하여 보고
(3) 조직 전체에 걸쳐서 고객 요구사항에 대한 인식의 증진을 지원
5.3.4 영업부서장
(1) 고객요구사항 파악 및 관련부서에 전달
(2) 견적, 수주, 계약검토업무 수행
(3) 생산의뢰 및 생산일정 조정
(4) 제품의 출하 및 수불업무 관리
(5) 고객불만 사항 창구업무 수행
(6) 고객만족도 조사 지원
(7) 납품 및 고객정보 조직에 전달
(8) 개발주문 접수 및 고객요구사항 접수
(9) 원가관리
(10) 기술영업
(11) 고객과의 계약관련 문서, 납기등의 제반사항을 검토
(12) 제품의 출하, 운송에 대한 제반업무
5.3.5 품질보증부서장
(1) 품질문서 및 기록관리 절차 확립
(2) 경영검토업무 자료준비 및 후속조치 실시
(3) 내부심사 계획수립 실시 및 결과보고
(4) 모니터링 및 측정(검사 및 시험)계획 수립 및 실시결과 기록 유지
(5) 모니터링 및 측정장비 교정실시, 기록 유지 및 시험실 관리
(6) 부적합제품 처리 및 고객불만처리, 데이터 분석업무 총괄
(7) 품질 환경 시스템과 관련된 부적합사항에 대한 시정조치요구서 발행 및 종결처리
(8) 품질평가 및 개선 (검사, 개선, 공급업체 감사지도)
(9) 공급업체의 신규 및 사후평가
(10) 필요 통계적기법의 파악 및 교육
(11) 고객정보의 관리
5.3.6 총무부서장
(1) 회사 건축물 및 사무용품 관리
(2) 인원, 자산관리 및 회사조직 및 업무분장에 관한 사항
(3) 종업원의 복리위생, 급여 및 노사관계 개선관리, 보험, 산재 관리업무
(4) 외부문서 접수. 발송, 문서고 관리
(5) 교육훈련, 자격인정 관리
(6) 소방관리, 안전관리, 보건관리, 환경관리
(7) 외부문서 접수. 발송
(8) 문서 ,재등록, 증명관리 업무
(9) 내빈접대, 차량관리, 보일러실, 식당등 시설 유지관리
(10) 인사관리에 관한 업무
(11) 관할관청(소방서,환경청,경찰서,노동부 등) 창구업무 수행
(12) 환경측면파악 및 환경영향평가의 지도 및 검증
(13) 환경관련법규, 그 밖의 요구사항입수 및 법규 등록부 작성 해당부서에 전달
(14) 환경운영관리와 관련된 사외 이해관계자와의 의사소통(관할관청,주민 등) 주관
(15) 환경운영관리, 비상사태 대비 및 대응, 모니터링 및 측정을 위한 절차 확립
(16) 환경운영관리와 관련된 부적합사항에 대한 시정/예방조치요구서 발행 및 종결처리
(17) 회사 전 작업 현장 안전관리 및 안전보건법규 준수 관리
5.3.7 생산부서장
(1) 생산계획 수립/실적 관리 및 공정관리
(2) 작업표준서 작성 배포
(3) 원부재료 선입선출 관리
(4) 제조설비 및 치공구의 유지 및 보전
(5) 작업현장 3정5S 관리
(6) 생산제품의 포장, 취급, 보관, 식별 및 추적성 관리
(7) 부적합 제품에 대한 식별표시 및 격리
(8) 부적합제품에 대한 현품처리
(9) 부적합 예방을 위한 지속적 개선
(10) 환경설비 운영실무
(11) 공정관리 및 공정검사 실시
(12) 제품 부적합 및 고객불만의 처리
(13) 부적합 예방을 위한 지속적 개선
(14) 작업원 능력파악 (적격성 평가 및 자격 부여)
(15) 현장 안전관리
(16) 원가절감 및 가치효율향상(합리화 및 표준화 개선활동)
(17) 제조공정관리 및 작업표준관리', 40
