SELECT 'QM', '6.1 리스크 및 기회를 다루기 위한 조치', '6.1.1 일반사항
품질 환경 경영시스템을 기획하기 위하여 해당부서는 ISO 9001:2015 4.1항, 4.2항과
ISO 14001:2015 6.1항을 고려하여 요구사항을 충족시키기 위한 프로세스를 수립,
실행 및 유지하여야 한다.
전 부서장은 다음사항에 다루어야 할 리스크(부정적요소) 및 기회(긍정적요소)를
결정하여야 한다.
(1) 품질측면 리스크 및 기회의 결정
가. 품질경영시스템이 조직의 의도된 결과를 달성할 수 있음을 보장
나. 바람직한 영향의 증진
다. 원하지 않는 효과를 방지 및 개선
라. 개선의 달성
(2) 환경안전보건측면 리스크 및 기회의 결정
가. 조직상항과 관련된 이슈
나. 이해관계자의 니즈와 기대 이해와 관련된 요구사항
다. 환경안전보건경영시스템의 적용범위
라. 환경측면/안전보건측면
마. 준수의무
바. 그 밖의 이슈와 요구사항
사. 리스크와 기회를 다루어야할 사항
-. 환경 경영시스템이 의도된 결과를 달성 할 수 있도록 확신을 줄것
- 회사에 영향을 주는 외부 환경여건의 잠재성을 포함한 부정적인 영향을 예방하고
완화할 것
- 지속적인 개선을 달성 할 것
아. 회사에 환경안전보건영향을 미칠 수 있는 것을 포함하여 잠재적 비상상황을 결정
자. 문서화된 정보를 유지
- 다룰 필요가 있는 리스크 및 기회
- 6.1.1항에서 6.1.4항까지 필요한 프로세스, 계획대로 수행되는 것에 대한 확신이
필요한 정보
6.1.2 조치 기획
(1) 품질측면
가. 리스크 및 기회를 다루기 위한 조치 (중대한 환경측면, 준수의무 포함)
나. 조치를 품질경영시스템의 프로세스로 통합하고 실행
다. 조치의 효과성 평가
라. 제품 및 서비스의 적합성에 미칠 잠재적인 영향에 적절해야 한다.
마. 조직상황의 이슈 및 이해관계자의 니즈와 기대가 파악된 리스크와 기회
비고. 리스크를 다루기 위한 선택사항에는 리스크 회피, 기회를 잡기 위한 리스크 감수,
리스크의 원인 제거, 가능성이나 결과의 변경, 리스크 공유 또는 정보가 제공된
결정에 따른 리스크 유지 등이 포함 될 수 있다.
비고. 기회는 회사 또는 고객의 니즈를 다루기 위하여 새로운 실행방안의 채택, 신제품
출시, 신규시장 개척, 신규고객 창출, 파트너십 구축, 신기술 활용 및 그 밖의
바람직하고 실행 가능한 방안으로 이어질 수 있다.
바. 리스크 분석
조직은 리스크 분석 내에 최소한, 제품 리콜, 제품심사, 필드반송 및 수리, 불만사항
폐기 및 재작업으로부터의 학습교훈 / 정보기술 시스템에 대한 사이버 공격 위협
조직은 리스크 분석 결과의 증거로써 문서화된 정보를 보유하여야 한다.
사. 예방조치 : 부적합 발생 방지를 위해 잠재적 부적합 원인을 제거하기 위한 조치를
결정하고 실행
- 잠재적 부적합 및 그 원인 결정
- 부적합의 발생을 방지하기 위한 조치의 필요성 평가
- 필요한 조치의 결정 및 실행
- 취해진 조치의 문서화된 정보 및 예방 조치의 효과성 검토
- 재발 방지를 위한 학습 교훈 활용
아. 비상계획
- 생산 출력을 유지하고 고객 요구 사항을 충족하는 것을 보장하는데 필수적인 모든 제조 공정
및 기반시설의 내/외부 리스크 파악 및 평가
- 고객에게 영향 및 리스크에 따라 비상 계획 규정
- 다음의 모든 이벤트에서 공급 지속성을 위한 비상 계획을 준비하되, 이에 국한되지 않는다.
주요 장비고장, 외부에서 공급된 제품, 프로세스 및 서비스로부터의 중단, 자연재해 반복, 화재
팬데믹(pandemics/전염병), 유틸리티 중단, 정보기술 시스템에 대한 사이버 공격, 노동력 부족
또는 기반시설 붕괴
- 비상계획의 보충사항으로서, 고객 오퍼레이션에 영향을 주는 모든 상황의 정도 및 기간에
대해 고객 및 기타 이해관계자에게 통지 프로세스를 포함한다.
- 최고 경영자를 포함한 전문분야 협력팀을 사용하여 비상계획 검토(최소 매년)를 수행하여야
하고 필요하다면 업데이트하여야 한다.
- 비상계획을 문서화하여야 하고 변경사항에 권한이 부여된 인원을 포함한, 모든 재정(들)을
기술한 문서화된 정보를 보유하여야 한다.
- 적절한 종업원 교육훈련 및 인식의 개발과 실행을 비상계획에 포함하여야 한다.
비상계획은 정기적인 생산가동 중단 프로세스를 따르지 않은 경우와 생산이 중단되는 비상사태
다음의 생산 재시작 후에 제조된 제품이 고객 시방을 지속적으로 충족하는지 검증하는 규정을
포함하여야 한다.
6.1.3 환경측면 / 위험성 평가
환경안전보건경영시스템 적용범위 내에서 환경안전 부서장은 전과정 관점을
고려하여 관리 할 수 있는 활동, 제품 및 서비스의 환경측면과 관련된 환경영향 및
안전보건 영향을 미칠 수 있는 것들을 결정하여야 한다.
및 기반시설의 내/외부 리스크 파악 및 평가
(1) 환경측면을 파악 할때 다음을 숙고하여야 한다.
가. 계획된 개발이거나 신규 개발을 포함한 변화 및 신규이거나 변경된 활동, 제품, 서비스
나. 비 정상적인 조건 및 합리적으로 예측 가능한 비상상황
(2) 총무부서장은 수립된 기준을 활용하여 중대한 환경측면과 같은 중대한 환경영향을
미치거나 미칠 수 있는 측면들을 결정하여야 한다.
(3) 환경안전 부서장은 다음의 정보들을 문서화된 정보로 유지하여야 한다.
가. 환경측면과 관련된 환경영향
나. 중대한 환경측면을 결정하기 위해 사용된 기준
다. 중대한 환경측면
식별((identification of dependencies) 및 취약성 우선 순위 지정이 포함될 수 있다.
6.1.4 준수의무
총무부서장은 다음을 결정하여야 한다.
(1) 환경안전보건측면과 관련된 준수의무를 결정하고 접근
(2) 이러한 준수의무를 어떻게 조직에 적용할 것인지 결정한다.
(3) 환경안전보건경영시스템을 수립, 실행, 유지 및 지속적으로 개선할 때 준수의무 반영
(4) 준수의무에 대한 문서화된 정보를 유지한다.
- 적절한 종업원 교육훈련 및 인식의 개발과 실행을 비상계획에 포함하여야 한다.

[표]
아. 비상계획
- 생산 출력을 유지하고 고객 요구 사항을 충족하는 것을 보장하는데 필수적인 모든 제조 공정
- 고객에게 영향 및 리스크에 따라 비상 계획 규정
- 다음의 모든 이벤트에서 공급 지속성을 위한 비상 계획을 준비하되, 이에 국한되지 않는다.
주요 장비고장, 외부에서 공급된 제품, 프로세스 및 서비스로부터의 중단, 자연재해 반복, 화재
팬데믹(pandemics/전염병), 유틸리티 중단, 정보기술 시스템에 대한 사이버 공격, 노동력 부족
또는 기반시설 붕괴
- 비상계획의 보충사항으로서, 고객 오퍼레이션에 영향을 주는 모든 상황의 정도 및 기간에
대해 고객 및 기타 이해관계자에게 통지 프로세스를 포함한다.
- 비상 계획 효과성에 대해 주기적으로 시험하여야 한다. (예로 적절한 경우 시뮬레이션),
사이버 보안 테스트에는 사이버 공격 시뮬레이션 특정 위협에 대한 정기적인 모니터링, 종속성
테스트는 관련 고객 공급중단의 리스크에 적합하다.
참고: 사이버 보안 테스트는 조직이 내부적으로 관리하거나 필요에 따라 하도급할 수 있다
- 최고 경영자를 포함한 전문분야 협력팀을 사용하여 비상계획 검토(최소 매년)를 수행하여야
하고 필요하다면 업데이트하여야 한다.
- 비상계획을 문서화하여야 하고 변경사항에 권한이 부여된 인원을 포함한, 모든 재정(들)을
기술한 문서화된 정보를 보유하여야 한다.', 43
WHERE NOT EXISTS (SELECT 1 FROM regulation_sections WHERE reg_code = 'QM' AND sort_order = 43);
INSERT INTO regulation_sections (reg_code, section_title, section_body, sort_order)
SELECT 'QM', '6.2 품질환경안전 목표 및 품질환경안전 목표를 달성하기 위한 기획', '해당부서장은 품질환경안전경영시스템에 필요한 기능, 계측 및 프로세스, 중대한
환경측면, 관련된 준수의무, 회사의 리스크와 기회를 숙고하여 품질 환경 목표를
수립하여야 한다.
6.2.1 품질환경안전 목표
품질 환경 목표는 다음과 같아야 한다.
(1) 품질환경안전 방침과 일관성이 있어야 한다.
(2) 측정이 가능해야 함
(3) 적용되는 요구사항이 고려되어야 함
(4) 제품 및 서비스의 적합성 및 고개만족 향상과 관련됨
(5) 모니터링되어야 함
(6) 의사소통되어야 함
(7) 필요에 따라 갱신되어야 함
해당 부서장은 품질 환경 목표에 대한 문서화된 정보를 유지하여야 한다.
6.2.2 목표 달성을 위한 조치의 기획
해당부서장은 목표 달성 방법에 대한 기획을 위하여 다음을 결정하여야 한다.
(1) 달성대상
(2) 필요자원
(3) 책임자
(4) 완료시기
(5) 결과 평가 방법
최고 경영자는 고객 요구사항을 충족하는 품질 목표가 조직 전반에 걸쳐 정의되고
수립되고 유지됨을 보장하여야 함
이해 당사자의 요구사항에 대한 조직 검토의 결과는 매년 품질 목표 및 관련 성과 목표를
수립할 때 고려하여야 함
6.2.3 변경에 대한 기획
해당부서장은 품질 환경 경영시스템의 변경이 필요하다고 결정하는 경우(4.4항 참조),
변경은 계획적이고 체계적인 방식으로 수행되어야 하며 다음 사항을 고려하여야 한다.
(1) 변경의 목적 및 잠재적인 결과
(2) 품질환경안전경영시스템의 완전성
(3) 자원의 가용성
(4) 책임 및 권한의 부여 또는 재 부여

[표]
비상계획은 정기적인 생산가동 중단 프로세스를 따르지 않은 경우와 생산이 중단되는 비상사태
다음의 생산 재시작 후에 제조된 제품이 고객 시방을 지속적으로 충족하는지 검증하는 규정을
포함하여야 한다.', 44
WHERE NOT EXISTS (SELECT 1 FROM regulation_sections WHERE reg_code = 'QM' AND sort_order = 44);
INSERT INTO regulation_sections (reg_code, section_title, section_body, sort_order)
SELECT 'QM', '6.3 관련 표준', '(1) 경영관리 프로세스 (MP-01)
(2) 리스크 관리 규정 (A-8100)
(3) 공정 FMEA 작성 및 관리 지침 (J-1101)
(4) 사업계획 운영 규정 (A-2100)', 45
WHERE NOT EXISTS (SELECT 1 FROM regulation_sections WHERE reg_code = 'QM' AND sort_order = 45);
INSERT INTO regulation_sections (reg_code, section_title, section_body, sort_order)
SELECT 'QM', '7. 지원', '', 46
WHERE NOT EXISTS (SELECT 1 FROM regulation_sections WHERE reg_code = 'QM' AND sort_order = 46);
INSERT INTO regulation_sections (reg_code, section_title, section_body, sort_order)
SELECT 'QM', '7.1 자원', '7.1.1 일반사항
해당 부서장은 품질 환경 경영시스템의 수립, 실행, 유지 및 지속적 개선에 필요한
자원을 결정하고 확보하여 제공하며, 다음 사항을 고려한다.
(1) 기존 내부자원의 능력과 계약사항
(2) 외부공급자로부터 획득 할 필요가 있는 것
(3) 품질 환경경영시스템의 실행 및 유지, 그리고 효과성에 대한 지속적인 개선
(4) 고객요구사항 충족에 의한 고객만족의 증진
7.1.2 인원
해당 부서장은 제품 요구사항에 대한 적합성에 영향을 미치는 업무를 수행하는
인원은 적절한 학력, 교육 훈련, 숙련도 및 경험을 근거하여 적격하도록 관리한다.
(1) 품질 환경 경영시스템의 효과적인 실행, 그리고 프로세스의 운용과 관리에 필요한
인원을 정하고 제공한다.
(2) 제품요구사항에 대한 적합성은 품질환경안전경영시스템내의 어떤 업무든지 업무를
수행하는 인원에 의해 직접 또는 간접적으로 영향을 받을 수 있다.
7.1.3 기반구조
해당 부서장은 제품의 요구사항에 대한 적합성을 달성하는 데 필요한 기반구조를
결정, 확보 및 유지한다.
기반구조는 해당되는 경우 다음사항을 포함한다.
(1) 건물, 현장, 창고 및 관련 유틸리티
(2) 제조설비, 검사설비, 하드웨어 및 소프트 웨어
(3) 운송차량 또는 통신과 같은 지원 서비스
7.1.3.1 공장시설 및 장비기획
(1) 조직은 공장, 시설 및 장비 계획서를 개발 및 개선하기 위해 리스크 파악 및 리스크
완화 방법을 포함한 전문분야협력 접근법을 사용하여야 한다.
(2) 공장 배치도를 설계할 때 조직은 다음을 하여야 한다.
가. 자재 흐름, 자재 취급 그리고 부적합 제품의 관리를 포함한 작업장의 부가 가치적
이용 최적화하여야 한다.
나. 해당된다면 동기화된 자재 흐름을 촉진한다. 그리고
다. 제조를 지원하는 장비 및 시스템의 사이버 보호를 실행한다.
(3) 신규 제품 또는 신규 작업방법에 대해서는 제조 타당성을 평가하고 실행한다.
(4) 제조 타당성 평가는 생산능력 기획을 포함하여야 하고 기존 작업에 대한 신규
변경사항을 평가하는데 적용한다.
(5) 프로세스 승인, 관리계획서 유지 그리고 작업 셋업 검증동안 만들어진
모든 변경사항을 통합시키기 위해, 리스크와 관련한 주기적인 재평가를 포함한
프로세스 효과성을 유지하여야 한다.
(6) 제조 타당성 평가와 생산능력 기획 평가는 경영 검토의 입력사항이어야 한다.
7.1.4 프로세스 운영 환경
(1) 해당부서장은 프로세스 운영과 제품 및 서비스의 적합성을 달성하기 위하여 필요한
환경을 결정, 제공 및 유지하여야 한다. 적절한 환경은 다음과 같이 사람과 물리적
요인의 조합이 될 수 있다.
가. 사회적 (예: 비차별, 평온, 비대립);
나. 심리적 (예: 스트레스 완화, 극심한 피로 예방, 정서적 보호);
다. 물리적 (예: 온도, 열, 습도, 빛, 기류, 위생, 소음)
(2) 생산부서장은 제품 및 제조 공정 요구에 일치하도록 조직의 현장을 정돈, 청결 및
수리상태를 유지하여야 한다.
7.1.5 모니터링 및 측정자원
7.1.5.1 일반사항
품질보증부서장은 제품 및 서비스가 요구사항에 대한 적합성을 검증하기 위해
모니터링 또는 측정이 사용되는 경우유효하고 신뢰할 수 있는 결과를 보장하는 데
필요한 자원을 결정하고 제공한다. 제공되는 자원은 다음과 같이 보장한다.
(1) 수행되는 모니터링 및 측정활동의 특정유형에 적절하여야 한다.
(2) 자원의 목적에 지속적으로 적합함을 보장하도록 유지한다.
(3) 모니터링 및 측정자원의 목적에 적절하다는 증거로서 적절한 문서화된 정보를 보유한다.
7.1.5.1.1 측정시스템 분석
(1) 통계적 조사는 관리계획서에서 파악된 각 형태의 검사, 측정 및 시험장비 시스템의
결과로 나타난 변동을 분석하기 위하여 수행되어야 하고, 사용된 분석방법과 합격
판정기준은 측정 시스템 분석에 관한 참고 매뉴얼에 있는 사항들에 적합하여야 한다.
(2) 고객에 의해 승인되는 경우, 다른 분석방법 및 합격 판정기준이 사용 될 수 있다.
(3) 대체 방법의 고객 수용 기록은 대체 측정 시스템 분석으로부터의 결과와 함께 유지
되어야 한다.(9.1.1.1참조)
(4) 측정시스템 분석의 우선순위는 특별제품 또는 공정특성를 고려한다,
7.1.5.2 측정 및 소급성
(1) 측정 소급성이 요구사항이거나 회사에 의해 측정결과의 유효성에 신뢰를 제공하는
필수적인 부분으로 고려된 경우 유효한 결과를 유지 하는데 필요한 검사설비는
다음과 같이 관리 한다. 단, 이러한 표준이 없는경우 자체 교정기준을 마련후 시행한다.
가. 규정된 주기 또는 사용 전에 국제표준 또는 국가표준에 소급 가능한 측정표준으로
교정, 검증 또는 두가지 모두가 시행될 것. 그러한 표준이 없는 경우 교정 또는검증에
사용된 근거는 문서화된 정보로 유지 될 것.
나. 측정장비의 교정 상태를 결정할 수 있도록 식별될 것.
다. 측정결과를 무효화 시킬수 있는 조정으로 부터 보호 되어야 한다.
라. 취급, 유지보전 및 보관하는 동안 손상이나 열화로 부터 보호 되어야 한다.
7.1.5.3 교정/검증 기록
교정/검증 기록을 관리하기 위한 문서화된 프로세스를 가지고 있어야 하며, 내부
요구사항, 법적 요구사항 및 규제적 요구사항그리고 고객이 규정한 요구사항에 대한
적합성 증거를 제공하는데 필요한 모든 교정/검증 활동의 기록은 보유되어야 한다.
교정/검증 활동 및 기록은 다음 상세사항을 포함한다.
(1) 측정 시스템에 영향을 주는 엔지니어링 변경에 따른 개정
(2) 교정/검증 평가 시 규격에 벗어난 모든 측정값
(3) 규격에 벗어난 계측기에 의해 적용된 제품에 대한 리스크 평가
(4) 교정이 벗어나 결함이 발견된 경우 관련 계측기의 최종 교정 일자와 차기 유효일자를
포함하여, 이 계측기로 얻어진 이전 측정 결과에 대한 유효성에 관한 문서화된 정보
(5) 의심스런 제품 또는 자재가 선적된 경우 고객에게 통지
(6) 모든 게이지에 대한 교정 및 보수유지 활동 기록
(7) 제품 및 공정 관리에 사용된 생산 관련 소프트웨어 검증
7.1.5.4 시험실 요구사항 (내부 시험실 / 외부 시험실)
(1) 내부 시험실 시설은 요구되는 검사, 시험 또는 교정 서비스를 수행하기 위한
능력을 포함한 정의된 범위를 가지고 있어야 한다. 시험실 범위는 품질경영시스템
문서화에 포함되어야 하며, 최소한 다음의 요구사항을 규정하고 실행한다.
가. 시험실 기술적 절차의 충분성
나. 시험실 인원의 역량/적격성
다. 제품의 시험
라. 공인 규격(ASTM, EN, ISO, JIS 등)에 정확하게 추적 가능하거나 측정 시스템 능력 검증
마. 고객 요구사항
바. 관련된 기록의 검토
(2) 외부 시험실 시설은 조직에 의해 검사, 시험 또는 교정 서비스 목적으로 사용되는 외부.상업적
/독립적 시험실 시설은 요구되는 검사, 시험 또는 교정 및 어느 하나를 수행하기 위한 능력을
포함하는 정의된 시험실 범위를 갖추어야 한다
가. 시험실은 ILAC MRA(국제 시험기관 인정기구 협의체 상호 인정 협정 WWW/llac.org)의 인정
기관에 의해 ISO/IEC 17025 또는 이와 국가적으로 동등한 것(예:중국의 CNAS-CL01)에 따라
인정되어야 하고 인정(인증) 범위에서 관련 검사, 시험 또는 교정 서비스를 포함하여야 한다.
교정 또는 시험 보고서의 인증서는 국가 인정 기관의 마크를 포함하여야 한다. 또는
인정되지 않은 시험실을 활용할 경우(예를 들면 그러나 이에 국한하지 않음 : 전문가 또는 통합
장비, 소급가능한 국제표준 참조가 없는 파라미터에 대해 원래장비 제조업체) 조직은 시험실이
평가되었고 IATF16949 7.1.5.3.1절의 요구사항을 충족한다는 증거가 있는지 확인할 책임이
있다.
※비고 : 독점적 소프트웨어 사용을 포함한 측정 장비의 통합 자체(자가) 교정은 교정 요구사항을
충족하지 않는다.
7.1.6 조직의 지식
(1) 해당부서장은 프로세스 운영 그리고 제품 및 서비스의 적합성 달성을 위하여 필요한
지식을 정하여야 하며 이 지식은 유지되어야 하고, 필요한 정도까지 이용 가능하여야
한다.
(2) 니즈 및 경향(trend)의 변경을 다룰 경우, 회사는 현재의 지식을 고려하여야 하고
추가로 필요한 모든 지식 및 요구되는 최신 정보의 입수 또는 접근방법을 정하여야 한다.
(3) 조직의 지식은 조직에게 특정한 지식으로, 경험에 의해 얻어지며 이는 조직의 목표를
달성하기 위하여 활용되고 공유되는 정보이다.
(4) 조직의 지식은 다음을 기반으로 할 수 있다.
가. 내부 출처 (예: 지적 재산, 경험에서 얻은 지식, 실패 및 성공한 프로젝트로부터
얻은 교훈 문서화되지 않은 지식 및 경험의 포착 및 공유, 프로세스, 제품 및 서비스
에서 개선된 결과)
나. 외부 출처 (예: 표준, 학계, 컨퍼런스, 고객 또는 외부 공급자로부터 지식 수집)', 47
WHERE NOT EXISTS (SELECT 1 FROM regulation_sections WHERE reg_code = 'QM' AND sort_order = 47);
INSERT INTO regulation_sections (reg_code, section_title, section_body, sort_order)
SELECT 'QM', '7.2 역량 / 적격성', '7.2.1 총무/해당부서장은 역량/적격성의 증거로써 적절한 문서화된 정보를 보유 하여야
하며 다음사항을 실행 한다.
(1) 조직은 품질 환경시스템의 성과 및 효과성, 조직의 준수의무를 충속시키는 능력 및
환경안전보건 성과에 영향을 미치는 조직의관리하에 업무를 수행는 인원에게 필요한
역량/적격성 결정 한다.
(2) 인원이 적절한 학력, 교육훈련 또는 경험에 근거하여 역량/적적성이 있음을 보장 한다.
(3) 필요한 역량/적격성을 갖추기 위하여 조치를 취하고, 취해진 조치의 효과성을 평가 한다.
(4) 역량/적격성의 증거로써 적절한 문서화된 정보를 보유한다.
(5) 제품 및 공정 요구사항에 대한 적합성에 영향을 주는 활동을 수행하는 모든 인원의
인식 및 역량/적격성 성취를 포함한 문서화된 프로세스를 수립하고 유지한다.
(6) 고객 요구사항의 특수한 업무를 수행하는 인원은 요구된 자격요건을 만족한다.
(7) 상기의 역량/적격성 평가 및 교육훈련은 계약직 또는 대행인원에 대해서도 동일하게
적용한다.
7.2.2 교육훈련 계획 수립
(1) 해당 부서장은 매년 각 부서장에 차기년도 교육훈련계획을 수립토록 의뢰한다
(2) 각 부서장은 소속 직원의 교육 필요성을 파악하고 교육훈련을 신청한다.
(3) 법정교육, 계층교육, 전문기술교육 등은 해당 업무 주관부서에서 필요여부를 판단하여
교육을 신청한다.
(4) 품질 및 환경에 중대한 영향을 일으킬 가능성이 있는 업무를 담당하는 모든 사람이
적절한 교육을 받도록 규정한다.
(5) 상기 인원에는 회사에 근무하거나 회사를 대신해 업무를 수행하는 모든 인원이 포함된다.
7.2.3 교육실시, 평가 및 보고
(1) 각 부서는 교육계획에 따라 교육훈련을 실시한다.
(2) 사외 위탁교육이나 사내 정규교육의 경우 관리부서에서 주관하여 실시한다.
(3) 사외 교육훈련 실시후 수강자는 교육결과 보고서를 작성하며, 해당 부서장은 교육
효과성 평가를 실시하여 교육기록부에 기재한다.
(4) 사내교육 후에는 사내교육 결과 보고서를 작성하며 해당 교육 강사, 또는 주관부서는
교육 효과성 평가를 실시하고 기록을 유지한다.
7.2.4 자격관리
(1) 각 부서는 업무의 정확한 수행을 위하여 일정한 경험이나 학력, 또는 교육훈련을
실시하여 해당 직무자에 대하여 사내자격을 부여하고 관리한다.
(2) 세부 사항은 해당 규정 자격 조건을 따른다.
7.2.5 직무 교육훈련(OJT)
(1) 신입, 또는 보직변경 인원에 대하여 각 부서장은 해당 인원의 경력, 경험 및 교육 훈련을
감안하여 직무수행에 필요한 OJT 훈련계획을 수립한다.
(2) OJT는 해당 책임 부서장이 계획에 따라 시행하며 직무능력이 확보된 후 업무를 부여한다.
(3) 각 부서장은 신입/보직변경 인원의 OJT 훈련시 해당인원이 맡게된 일의 중요성과
품질목표 달성에의 기여도, 해당업무가 품질에 미치는 영향과 부적합이 고객에 미치는
영향을 숙지하도록 한다.
7.2.6 내부심사원 역량/적격성
조직은 내부 심사원이 모든 조직에 의해 규정한 요구사항 및 또는 고객지정 요구사항을
고려하여 역량이 있는지 검증하기 위한 문서화된 프로세스를 가지고 있어야 한다.
심사원 역량/적격성에 대한 추가적인 지침에 대해서는 ISO 19011을 참조한다.
조직은 자격 부여된 내부 심사원의 목록을 유지하여야 한다.
품질경영시스템 심사원은 다음의 다음의 적격성을 최소한 실증할 수 있어야 한다.
1) 리스크 기반 사고를 포함하여, 심사를 위한 자동차산업 프로세스 접근법의 이해
2) 해당하는 고객 지정 요구사항의 이해
3) 심사의 범위에 관련된 해당하는 ISO9001 및 IATF 16949, ISO 14001 의 요구사항 이해
4) 심사 범위에 관련된 해당하는 Core tools 요구사항의 이해
5) 계획, 수행, 보고와 심사 발견사항 종결 방법에 대한 이해
최소한 제조 프로세스 심사원은 프로세스 리스크 분석(PFMEA와 같은) 및 관리계획서를
포함한 심사되는 관련 제조 프로세스(들)에 대한 기술적 이해를 실증하여야 한다.
최소한 제품 심사원은 제품 적합성을 검증하기 위해 제품 요구사항 이해 및 관련 측정 및
시험장비를 사용하는 능력을 검증해야 한다.
역량을 성취하기 위해 조직의 인원이 교육훈련을 제공하는 경우 상기 요구사항과 함께
강사의 역량을 실증하기 위해 문서화된 정보가 보유되어야 한다.
1)조직에 의해 규정된 대로 매년 최소한의 심사 횟수 수행
2)내부 변경(예를들어 공정기술, 제품기술등) 및 외부 변경(예를들어 ISO9001, IATF16949,
ISO14001, CORE TOOLS 및 고객 지정 요구사항)을 기반으로 한 관련 요구사항의 지식 유지
7.2.7 2자 심사원 역량/적격성
2자 심사를 수행하는 심사원의 역량을 실증하여야 하며, 심사원 자격부여에 대한
고객 지정 요구사항을 충족하여야 하고 7.2.6 내부심사원 역량/적격성 항목을 갖춰야 한다.', 48
WHERE NOT EXISTS (SELECT 1 FROM regulation_sections WHERE reg_code = 'QM' AND sort_order = 48);
INSERT INTO regulation_sections (reg_code, section_title, section_body, sort_order)
SELECT 'QM', '7.3 인식', '7.3.1 인식
당사는 조직의 관리 하에 업무를 수행하는 관련 인원이 다음사항을 인식하도록 보장한다.
(1) 품질환경안전방침
(2) 관련된 품질목표
(3) 자신의 업무와 관련된 중대한 환경측면/안전보건측면과 실재적 또는 잠재적 영향
(4) 개선된 품질성과, 환경안전보건성과의 이득을 포함하여 품질 환경 경영시스템의
효과성에 대한 자신의 기여
(5) 조직의 준수의무를 이행하지 않는 것을 포함하여, 품질환경안전경영시스템의
요구사항에 부적합 경우의 영향
7.3.2 종업원 동기부여 및 역량강화
당사는 품질 목표를 달성하고, 지속적 개선을 실시하고, 그리고 혁신을 촉진하는
환경을 창조하도록 종업원에게 동기 부여하는문서화된 프로세스를 유지한다.
그 프로세스는 전 조직 전체에 걸쳐 품질 및 기술적 인식의 촉진을 포함한다.', 49
WHERE NOT EXISTS (SELECT 1 FROM regulation_sections WHERE reg_code = 'QM' AND sort_order = 49);
INSERT INTO regulation_sections (reg_code, section_title, section_body, sort_order)
SELECT 'QM', '7.4 의사소통', '7.4.1 해당 부서장은 다음사항을 포함하여 품질환경안전경영시스템에 관련된 내부 및
외부 의사소통에 필요한 프로세스를 수립하고실행 및 유지 하여여 하며 의사소통을
결정한다.
(1) 의사소통 내용
(2) 의사소통 시기
(3) 의사소통 대상
(4) 의사소통 방법
(5) 의사소통 담당자
7.4.2 의사소통 프로세스 기획
(1) 준수의무를 숙고
(2) 의사소통 되는 환경정보가 환경 경영 시스템 내에서 생성된 정보와 일치
(3) 의사소통의 근거로써 문서화된 정보 보유
7.4.3 환경 관련 외부 의사소통
7.4.3.1 총무부서장은 환경측면 및 환경 경영시스템과 관련하여 다음에 대한 절차를 수립,
실행 및 유지한다.
(1) 조직 내 여러 계층과 기능간의 내부 의사소통
(2) 외부 이해관계자와의 적절한 의사소통을 위한 접수, 문서화 및 회신
(3) 홈페이지 및 E-Mail을 이용하여 공개 및 게시
7.4.3.2 총무서장은 회사의 중대한 환경측면/안전측면에 대해 외부와 의사소통 할 것인지를
결정하고 회사의 결정을 문서화한다. 외부와 의사소통 하는 것으로 결정한 경우
총무부서장은 이 외부 의사소통을 위한 방법을 수립하고 실행한다.
7.4.5 환경 관련 내부 의사소통
(1) 품질 환경 경영시스템의 효과파악 및 지속적 개선을 위하여 지속적으로 협의한다.
(2) 제품 및 품질 환경 경영시스템의 개선을 위하여 TFT(Task Force Team-개선운영 팀)을
운영한다.
(3) 신규 수주 및 공정 프로세스 개발을 위하여 각 단계의 대표자를 참석 시킨다.
(4) 다양한 계층과 기능에서 환경안전보건경영시스템과 관련된 정보에 대하여 내부
의사소통 한다.
(5) 업무를 수행하고 있는 인원이 지속적 개선에 기여 할 수 있도록 보장 한다.', 50
WHERE NOT EXISTS (SELECT 1 FROM regulation_sections WHERE reg_code = 'QM' AND sort_order = 50);
INSERT INTO regulation_sections (reg_code, section_title, section_body, sort_order)
SELECT 'QM', '7.5 문서화된 정보', '7.5.1 일반사항
7.5.1.1 해당 부서장은 품질환경안전경영시스템 문서화는 다음사항을 포함한다.
(1) 문서화하여 표명된 품질환경안전방침, 품질환경안전목표
(2) 품질환경안전매뉴얼
(3) ISO 9001, IATF 16949, ISO 14001 규격이 요구하는 문서화된 절차 및 기록
(4) 이 프로세스의 효과적인 기획, 운영 및 관리를 보장하기 위하여 필요하다고 회사가
결정한 문저화된 정보, 기록을 포함하는 문서
7.5.2 문서화된 정보의 범위
(1) 조직의 규모 및 활동의 형태, 제품 및 서비스의 유형
(2) 프로세스의 복잡성 및 그 상호작용
(3) 인원의 역량/적격성
(4) 준수의무의 충족을 실증할 필요성
7.5.3 품질 환경 시스템의 구조
7.5.3.1 품질 환경 매뉴얼
품질보증부서장은 품질 환경 시스템의 구조와 정책을 정하고 품질 환경에 대한 원칙
및 기본방향이 되는 품질 환경 시스템의 최상위 문서로서 ISO 9001, IATF 16949,
ISO 14001 요구사항의 충족, 유효성, 회사의 정책 등을 고려하여 작성한다.
7.5.3.2 관리표준(규정/표준)
해당부서장은 품질 환경 매뉴얼을 구체적으로 실현하기 위한 문서로서, 업무 또는
활동의 수행을 위한 책임과 권한, 절차, 자원등을 정한 문서이며, 각 부문에서
매뉴얼에 언급된 품질 정책의 시행에 관한 것들을 ’어디서, 무엇을, 누가, 언제 하여야
하는지’ 를 중심으로 작성한다.
7.5.3.3 기술표준(지침서/기준/규격/시험방법 등)
해당부서장은 제품의 품질요구사항, 환경안전보건 요구사항을 실현하기 위하여
필요한 제품, 자재의 규격과 검사, 시험 등관련 세부활동의 방법 및 절차를 기술한
문서로서, 작업 또는 검사/시험을 구체적으로 방법을 기술하여 작성한다.
7.5.4 품질, 환경 경영 시스템 문서화
품질, 환경 매뉴얼은 최소한 다음 사항을 포함하여야 한다.
(1) 모든 적용 제외에 대한 정당성 및 세부 내용을 포함하는 품질경영시스템의 적용범위
(2) 품질,환경 경영시스템을 위해 수립된 문서화된 프로세스, 또는 그 프로세스의 인용
(3) 모든 외주 처리된 프로세스 관리의 유형 및 정도를 포함하는, 조직의 프로세스와
프로세스의 순서 및 상호작용 (입력 및 출력)
(4) 조직의 품질경영시스템 내에서 고객 지정 요구사항이 다루어 지고 있음을 나타내는 문서
(예를 들면 표, 목록, 또는 매트릭스)
7.5.2 작성 및 갱신
해당부서장은 문서화된 정보를 작성하거나 갱신할 때에는 품질환경안전경영시스템의
요구사항에 적합하다는 증거와 운영에 대한 증거를 제공하기 위하여 작성된 문서는
기록 유지되어야 한다. 문서화된 정보를 작성하거나 갱신 할 때 다음 사항이 적절함을
보장한다.
(1) 기록의 식별 및 내용 (제목, 날짜, 작성자, 문서번호 등)
(2) 형식 (언어, 소프트웨어 버전, 그래픽 등) 및 매체 (종이, 전자 매체 등)
(3) 적절성 및 충분성에 대한 검토 및 승인
7.5.3 문서화된 정보관리
7.5.3.1 해당 부서장은 품질환경안전경영시스템에 필요한 문서 관리, 기록은 문서의 특별한
형식으로 요구사항에 따라 관리 한다.
7.5.3.2 문서화된 정보는 다음 사항을 보장하기 위하여 관리 되어야 한다.
(1) 필요한 장소 및 시기에 사용 가능 해야 한다.
(2) 사용하기에 적절해야 한다.
(3) 충분하게 보호가 되어야 한다
(4) 필요 시 문서의 검토 및 갱신, 그리고 재 승인
(5) 문서의 변경 및 최신 개정 상태의 식별을 보장
(6) 적용되는 문서의 해당 본이 사용되는 장소에서 이용 가능함을 보장
(7) 문서가 읽기 쉽도록 유지되고, 쉽게 식별됨을 보장
(8) 효력이 상실된 문서의 의도되지 않은 사용을 방지하며 어떤 목적을 위해 보유할
경우에는 적절한 식별의 적용
(9) 배부, 접근, 회수, 보유, 처분 및 사용이 용이해야 하며 가독성을 보존을 포함한
보관 및 보존이 되어야 한다.
(10) 변경된 문서는 갱신, 변경 관리가 되어야 한다.
(11) 외부출처 문서화된 정보는 해당되는 경우 식별되고 관리 되어야 한다.
7.5.4 기록 보유
(1) 해당 부서장은 문서 보관 및 보존 규정에 의해 관리하며, 기록 관리는 법적 요구사항,
규제적 요구사항, 조직 요구사항 및 고객 요구사항을 만족시켜야 한다.
(2) 양산 부품 승인, 치공구 기록, 제품 및 공정 설계 기록, 구매 주문서 또는 계약서는
고객 또는 규제 기간에 의해 별도로 지정된 것이 없다면, 생산 및 서비스 요구사항에
대해 제품이 활성화 되는 기간에 일년을 더한 기간동안 보유되어야 한다.
7.5.6 엔지니어링 시방서
(1) 해당 부서장은 요구되는 경우, 모든 고객 엔지니어링 규격/시방서 및 관련 문서의
검토, 배포 및 실행을 기술하는 문서화된 프로세스를 갖추어야 한다.
(2) 엔지니어링 규격/시방서 변경사항이 제품 설계 변경 및 제품 실현성 변경의 결과가
된 경우 4M변경 관리 규정을 따른다.
(3) 검토는 엔지니어링 표준/시방서 변경사항의 통지는 수령 10일 이내에 완료되어야 한다.
(4) 이들 시방서가 설계기록에 참조되거나 관리계획서, 리스크 분석 등과 같은 양산부품
승인절차 문서에 영향을 미칠 경우 이들 규격/시방서의 변경은 고객 양산부품 승인의
갱신된 기록을 요구할 수 있다.', 51
WHERE NOT EXISTS (SELECT 1 FROM regulation_sections WHERE reg_code = 'QM' AND sort_order = 51);
