(2) 설비관리규정 (L-1100)
(3) 3정 5S활동 규정 (M-4100)
(4) 신뢰성 시험 업무 규정 (L-2200)
(5) 계측기 관리 규정 (L-3100)
(6) 측정시스템 평가 지침 (L-3101)
(7) 교육훈련 규정 (F-1100)
(8) 신규 보직자 관리 지침 (F-1101)
(9) 사내자격관리 규정 (F-2100)
(10) 의사소통 규정 (A-3200)
(11) 문서 및 자료관리 규정 (A-4100)
(12) 기록관리 규정 (A-4200)
(13) 4M 변경관리 규정 (J-3100)
(14) 환경법규 관리 규정 (E-2100)', 52
WHERE NOT EXISTS (SELECT 1 FROM regulation_sections WHERE reg_code = 'QM' AND sort_order = 52);
