WHERE NOT EXISTS (SELECT 1 FROM regulation_sections WHERE reg_code = 'QM' AND sort_order = 53);
INSERT INTO regulation_sections (reg_code, section_title, section_body, sort_order)
SELECT 'QM', '8.1 운용 기획 및 관리', '8.1.1 일반사항
8.1.1.1 해당 부서장은 다음사항을 통하여 품질환경안전경영시스템 요구사항, 제품 및
서비스의 제공을 위한 요구사항을 충족, 조치를 실행하기 위해 필요한 프로세스를
계획, 실행 및 관리하여야 하며 회사의 품질환경안전경영시스템의 다른 프로세스
요구사항과 일관성이 있어야 한다.
8.1.1.2 해당 부서장은 운영 기획 및 관리 할때 해당되는 경우 다음사항을 결정하여야 한다.
(1) 제품 및 서비스, 환경에 대한 요구사항
(2) 프로세스 기준 수립, 제품 및 서비스의 수락
(3) 제품 및 서비스 요구사항에 대한 적합성을 달성하기 위해 필요한 자원의 결정
(4) 기준에 따른 프로세스에 대한 관리 실행
(5) 다음을 위해 필요한 정도의 문서화된 정보를 결정 및 보유
가. 프로세스가 계획 대로 수행되었음에 대한 신뢰 확보
나. 제품 및 서비스가 요구사항에 적합함을 실증
(6) 프로세스 및 문서를 수립 할 필요성, 그리고 제품에 대한 특정 자원의 확보에 대한
필요성
(7) 제품 및 합격판정기준에 대해 특정하게 요구되는 검증, 타당성확인, 모니터링, 측정
검사 및 시험 활동
(8) 환경안전경영시스템이 전과정의 각 단계를 고려하여 제품과 서비스에 대하여 설계 및
개발 프로세스에서 다루어 지는 것을 보장하도록 관리체계를 수립
(9) 제품과 서비스의 조달에 대한 환경요구사항을 결정, 계약자들을 포함하여 외부
제공자에게 관련된 환경 요구사항을 결정
(10) 제품과 서비스이 운반이나 운송, 사용, 사용기간이 지난 제품의 처리 그리고 최종적
폐기와 관련된 잠재적인 중대한 환경영향에 대한 정보를 제공할 필요성을 고려해야 한다.
8.1.1.3 이러한 기획의 출력은 회사의 운영에 적절 하여야 한다.
8.1.1.4 해당 부서장은 계획된 변경사항을 관리하고 의도하지 않은 변경의 결과를 검토해야
하며 필요에 따라 모든 부정적인 영향을 완화하기 위한 조치를 취해야 한다.
또한 외주 처리 프로세스가 관리됨을 보장 하여야 한다.
8.1.2 운용 기획 및 관리
8.1.2.1 제품 실현에 대한 기획을 하는 경우 다음의 사항이 포함되어야 한다.
(1) 고객 제품 요구사항 및 기술 시방서
(2) 물류 요구사항 및 제조 타당성
(3) 프로젝트 기획 및 합격판정 기준
8.1.3 기밀 유지
조직은 관련된 제품 정보를 포함하여, 개발 중에 있는 고객과 계약된 제품 및 프로젝트에
대한 기밀유지를 보장하여야 한다.', 54
WHERE NOT EXISTS (SELECT 1 FROM regulation_sections WHERE reg_code = 'QM' AND sort_order = 54);
INSERT INTO regulation_sections (reg_code, section_title, section_body, sort_order)
SELECT 'QM', '8.2 제품 및 서비스에 대한 요구사항, 비상사태 대비 및 훈련', '(1) 환경 비상사태 대비 및 대응
총무부서장은 조직은 환경/안전에 영향을 줄 수 있는 잠재적 비상상황 및 사고를 파악
하고 이에 대응하기 위한 절차를 수립, 실행 및 유지하여야 한다.
(2) 조직은 다음사항을 수행하여야 한다.
가. 해당 부서장은 실제 비상상황 및 사고 발생 시 관련된 환경안전 영향을 방지하거나
완화할 수 있도록 대응하여야 한다.
나. 총무부서장은 비상사태에 대한 대비 및 대응 절차를 주기적으로 검토하고 필요 시
개정하여야 하며 특히 사고 또는 비상상황이 발생한 후에는 반드시 그리하여야 한다.
다. 해당 부서장은 비상사태에 대한 대비 및 대응 절차를 실행 가능한 방법으로 주기적으로
시험하여야 한다.
라. 실제적 비상사황에 대응
마. 비상상황과 잠재적 환경영향의 규모와 관련된 비상상황의 결고를 예방하거나 완화하기
위한 조치
바. 비상상황의 발생이나 시험 이후에는 프로세스와 계획된 대응을 주기적으로 검토 및 개정
사. 총무부서 관리하에 업무를 수행하는 인원을 포함하여 관련된 이해관계자에게 관련된
정보 및 교육훈련(비상상황의 준비 및 대응)을 제공 하여야 한다.
8.2.1 고객과의 의사소통
8.2.1.1 품질관련 고객과의 의사소통
영업 부서장은 다음사항과 관련된 고객과의 의사소통을 위한 효과적인 방법을
결정하고 실행하여야 한다.
(1) 제품 및 서비스 관련 정보 제공
(2) 변경을 포함하여 문의, 계약 또는 주문의 취급
(3) 고객 불평을 포함하여 제품 및 서비스에 관련된 고객의 피드백 입수
(4) 고객 재산의 취급 및 관리
(5) 관련 될 경우 비상조치에 대한 특정 요구사항 수립
(6) 서면 또는 구두 의사소통은 고객과 합의된 언어로 이루어져야 하며, 고객-지정 컴퓨터
언어 및 형식에 있는 데이터를 포함하여 필요한 정보를 의사 소통하는 능력을 갖추어야
한다.
8.2.2 제품 및 서비스와 관련된 요구사항의 결정
8.2.2.1 영업부서장은 제품과 관련된 요구사항을 파악하고 다음 사항을 결정 하여야 한다.
(1) 고객 요구사항
(2) 제품 사용 요건(명시되지 않았으나 사용에 필요한 요구사항 포함)
(3) 법적요구/규제적 요구사항(정부 법규, 환경, 안전 요구사항 포함)
(4) 사내 목적상 필요한 사항
(5) 재활용 환경적 영향/특성
(6) 인도후 활동
(7) 고객 지정 그 표시 및 관리방법
8.2.2.2 고객 또는 그 대리인이 위의 요구사항을 결정하여 전달한 경우 회사는 누락사항/추가
필요사항 존재 여부의 검토를 실시한다.
8.2.3 제품 및 서비스와 관련된 요구사항의 검토
8.2.3.1 해당 부서장은 고객에게 제공될 제품 및 서비스에 대한 요구사항을 충족시키는
능력이 있음을 보장하여야 한다. 고객에게 제품 및 서비스의 공급을 결정하기 전에,
다음 사항을 포함한 검토를 실시하여야 한다.
(1) 인도 및 인도 이후의 활동에 대한 요구사항을 포함한 고객 규정 요구사항
(2) 고객이 명시하지 않았으나 알려진 경우, 규정되거나 의도된 요구사항
(3) 당사에 의해 규정된 요구사항
(4) 제품이나 서비스에 적용되는 법적 및 규제적 요구사항
(5) 이전에 표현된 것과 상이한 계약 또는 주문 요구사항
(6) 공식적인 검토에 대해 요구사항에 대한 고객 승인 특채의 문서화된 증거를 보유하여야
한다.
(7) 지정, 승인 문서화, 그리고 특별 특성의 관리에 대한 고객 요구사항에 적합하여야 한다.
(8) 당사의 제조 프로세스가 고객에 의해 규정된 요구사항 모두를 충족하는 제품을
일관되게 생산하는 능력이 있다는 것이 실현 가능한지를 결정하는 분석을 수행하기
위해 전문분야협력접근법을 활용하여야 하며, 변경/신규 제조 또는 기술에 대해
제조타당성 확인 분석을 수행하여야 한다.
8.2.3.2 해당 부서장은 다음사항에 대한 문서화된 정보를 보유하여야 한다.
(1) 검토 결과
(2) 제품 및 서비스에 대한 모든 새로운 요구사항
8.2.4 제품 및 서비스와 관련된 요구사항의 변경
제품 및 서비스에 대한 요구사항이 변경되는 경우 관련부서장은 관련 문서화된 정보가
수정되고 관련 인원이 변경된 요구사항을 인식하고 있음을 보장하여야 한다.', 55
WHERE NOT EXISTS (SELECT 1 FROM regulation_sections WHERE reg_code = 'QM' AND sort_order = 55);
INSERT INTO regulation_sections (reg_code, section_title, section_body, sort_order)
SELECT 'QM', '8.3 제품 및 서비스의 설계 및 개발', '8.3.1 일반사항
해당 부서장은 제품 및 서비스의 설계와 개발 이후의 공급을 보장하기에 적합한 설계와
개발 프로세스를 수립, 실행 및 유지하여야 한다. 검출보다는 실수 방지에 초점을
맞추어야 하며, 설계 및 개발 프로세스를 문서화 하여야 한다.
8.3.2 설계와 개발 기획
설계와 개발에 대한 단계 및 관리를 결정할 때 다음 사항을 고려하여야 한다.
(1) 설계와 개발 활동의 성질, 기간 및 복잡성
(2) 적용되는 설계와 개발 검토를 포함하여, 요구되는 프로세스 단계
(3) 요구되는 설계와 개발 검증 및 실현성 확인/타당성 확인 활동
(4) 설계와 개발 프로세스에 수반되는 책임 및 권한
(5) 제품 및 서비스의 설계 및 개발을 대한 내부 및 외부 자원 필요성
(6) 설계와 개발 프로세스에 관여하는 인원 간의 연계성 관리의 필요성
(7) 설계와 개발 프로세스에 고객 및 사용자의 관여 필요성
(8) 제품 및 서비스의 설계와 개발 이후의 공급을 위한 요구사항
(9) 설계와 개발 프로세스에 대해 고객 및 기타 관련 이해관계자가 기대하는 관리의 수준
(10) 설계와 개발 요구사항이 충족되었음을 실증하는데 필요한 문서화된 정보
8.3.2.1 보충사항
당사는 설계 및 개발 기획이 조직 그리고 해당하는 경우 조직의 공급망 내에서
영향을 주는 모든 이해당사자를 포함하는 것을 보장한다. 전문분야협력 접근방법에
대한 사용의 예는 다음을 포함하지만 국한되지 않는다.
(1) 프로젝트 관리 (APQP 또는 VDA-RGA)
(2) 대체 설계 및 제조 공정 사용의 고려와 같은 제품 및 제조 공정 설계 활동 (DFM 및 DFA)
(3) 잠재적 리스크를 감소시키기 위한 조치를 포함하여, 제품설계 리스크 분석 개발 및 검토
(4) 제조 공정 리스크 분석의 개발 및 검토 (FMEA, 관리계획서, 작업 표준서)
비고. 전문분야협력 접근법은 조직의 개발, 영업, 품질, 생산, 구매, 생기, 공급자, 유지보수
및 기타 해당 기능을 포함한다.
8.3.2.2 제품 설계 스킬
당사는 제품 설계 책임을 가진 인원이 설계 요구사항을 달성하기 위하여 역량이 있고
적용 가능한 제품 설계 도구 및 기법에 숙련되어 있음을 보장한다.
8.3.3 설계와 개발 입력
(1) 해당 부서장은 설계와 개발이 될 특정 형태의 제품 및 서비스에 필수적인 요구사항을
정하여야 하며, 다음 사항을 고려하여야 한다.
가. 기능 및 성능/성과 요구사항
나. 이전의 유사한 설계와 개발활동으로부터 도출된 정보 (실패사례)
다. 법적 및 규제적 요구사항
라. 조직이 실행을 약속한 표준 또는 실행 실행지침
마. 제품 및 서비스 본질에 기인하는 실패의 잠재적 결과
(2) 입력은 설계와 개발 목적에 충분하며, 완전하고 명확해야 한다.
(3) 해당 부서장은 설계와 개발 입력에 대한 문서화된 정보를 보유한다.
8.3.3.1 제품 설계 입력
(1) 해당 부성장은 계약 검토 결과로써 제품 설계 입력 요구사항을 파악, 문서화 및
검토하여야 하고, 다음을 포함하되 국한하지 않는다.
가. 제품을 특별 특성으로 제한하지는 않지만 제품 시방을 포함하는 것
나. 영역 및 상호 연계 요구사항
다. 식별, 추적성 및 포장
라. 설계 대체 방법의 고려
마. 입력 요구사항과 함께 리스크의 평가와 제조타당성 분석으로부터의 사항을 포함한
리스크를 완화/관리하기 위한 조직의 능력
바. 보존, 신뢰성, 내구성, 서비스용이성, 보건, 안전, 환경, 개발 시점, 원가를 포함한
제품 요구사항의 적합성에 대한 목표
사. 만약 제공된다면, 고객의 식별된 국가의 도착지에 대한 해당되는 법적 요구사항 및 규제적 요구사항
아. 내장된 소프트웨어 요구사항
(2) 해당 부서장은 이전 설계 프로젝트, 경쟁사 제품 분석(벤치마킹), 공급자 피드백, 내부
입력사항, 필드 데이터 및 유사한 성격의 현재와 미래 프로젝트에 대한 기타 관련된
출처로부터 얻어진 정보를 전개하는 프로세스를 가지고 있어야 한다.
8.3.3.2 제품 공정 설계 입력
(1) 해당 부서장은 제조 공정 설계 요구사항을 파악, 문서화 및 검토하여야 하며 다음을
포함하되 국한하지 않는다.
가. 특별 특성을 포함한 제품 설계 출력 데이터
나. 생산성, 공정 능력, 시점 및 원가에 대한 목표
다. 제조 기술 대안
라. 고객 요구사항 (요구 있을 경우)
마. 이전의 개발로부터의 경험
바. 새로운 재료
사. 제품 취급 및 인체공학 요구사항
아. 제조 및 조립을 고려한 설계
(2) 제조공정 설계는 문제의 크기에 적절하고 당면한 리스크에 상응하는 정도로 실수방지
방법의 이용을 포함하여야 한다.
8.3.3.3 특별 특성
조직은 고객에 의해 결정된 특별특성과 조직에 의해 수행된 리스크 분석을 포함한 측별 특성
을 파악하는 조직의 프로세스(들)를 수립, 문서화 및 실행하기 위해 전문 분야 협력 접근법을
사용하여야 하고, 다음 사항을 포함하여야 한다.
(1) 제품 및 또는 제조 문서(요구되는 대로) 관련 리스크 분석(공정 FMEA와 같은) 관리계획서
및 표준 작업/작업자 지침상의 특별특성은 문서화, 특별특성은 특별표시(마킹)로 식별되고
이러한 특별 특성을 위해 작성 또는 요구되는 관리를 보여주는 제조 문서에 문서화되어 있다.
(2) 제품 및 생산공정의 특별특성에 대해 관리 및 모니터링 전략을 개발
(3) 요구되는 경우 고객 지정 승인
(4) 기호 전환표에서 규정된 대로 고객 지정 정의 및 기호 또는 조직의 동등한 기호 또는
표기에 대한 준수, 기호 전환표는 요구되는 경우 고객에게 제출되어야 한다.
8.3.4 설계와 개발 관리
해당 부서장은 설계 및 개발 프로세스에 다음을 보장하기 위한 관리를 적용하여야 한다.
(1) 달성될 결과가 규정될 것
(2) 설계 및 개발 결과가 요구사항을 충족하는지의 능력을 평가하기 위한 검토가 수행될 것
(3) 설계 및 개발 출력이 입력 요구사항에 충족함을 보장하기 위한 검증 활동이 수행될 것
(4) 결과로 나타난 제품 및 서비스가 요구사항에 충족됨을 보장하기 위한 실현성 확인
활동이 수행될 것
(5) 검토 또는 검증 및 실현성 확인 활동 중에 식별된 문제점에 대해 모든 필요한 조치가
취해질 것
(6) 이들 활동에 대한 문서화된 정보는 보유될 것
비고. 설계 및 개발 검토, 검증 및 실현성 확인은 별개의 다른 목적이 있으며, 제품 및
서비스에 적절하게 수행될 수 있다.
8.3.4.1 모니터링
(1) 제품 및 공정의 설계와 개발하는 동안 규정된 단계에서의 측정은 경영검토의
입력으로서 요약결과와 함께 정의되고 분석되고 보고되어야 한다.
(2) 고객 요청 시 제품 및 공정 개발 활동의 측정은 고객에 의해 규정된 또는 합의된
단계에서 고객에게 보고되어야 한다.
비고. 해당되는 경우, 이들 측정은 품질 리스크, 비용, 리드타임, 주요경로 및 기타 측정
사항을 포함할 수 있다.
8.3.4.2 설계 및 개발 실현성확인/타당성확인
(1) 설계 및 개발 실현성확인/타당성확인은 해당 산업과 정부 기관에서 발행된 규제적
표준을 포함한 고객 요구사항에 따라 수행한다.
(2) 설계 및 개발 실현성확인의 시점은 해당하는 경우 고객 지정 시점에 맞추어 계획되어야
한다.
(3) 고객과 합의된 경우, 최종 고객 제품 시스템 내 내장된 소프트웨어를 포함한, 조직
제품의 상호작용에 대한 평가를 포함하여야 한다.
8.3.4.3 시작품 프로그램
(1) 고객이 요구하는 경우, 조직은 시작품 프로그램 및 관리계획서를 갖추어야 한다.
(2) 조직은 가능한 한 양산에 사용될 것과 동일한 공급자, 치공구 및 제조공정을 사용하여야
한다.
(3) 모든 성능시험 활동은 시의 적절한 완료와 요구사항에 대한 적합성에 대해 모니터링
되어야 한다.
(4) 외주처리 된 경우, 조직은 외주 처리된 서비스가 요구사항에 적합하다는 것을 보장하기
위해 품질 경영 시스템의 범위에서 관리의 유형과 정도를 포함하여야 한다.
8.3.4.4 제품 승인 프로세스
(1) 해당 부서장은 고객에 의해 규정된 요구사항을 준수하는 제품 및 제조 승인 프로세스를
수립, 실행 및 유지하여야 하며, 고객에게 그들의 부품 승인을 제출에 앞서, ISO 9001
섹션 8.4.3에 따라 외부에서 공급된 제품 및 서비스를 승인하여야 한다.
(2) 고객에 의해 요구되는 경우, 문서화된 제품 승인을 얻어야 하며, 그러한 승인 기록은
보유되어야 한다.
비고. 제품 승인은 제조 공정의 검증 이후에 이루어져야 한다.
8.3.5 설계와 개발 출력
조직은 설계 및 개발 출력이 다음과 같음을 보장하여야 한다.
(1) 입력 요구사항을 충족
(2) 제품 및 서비스 제공을 위한 후속 프로세스에 충분함
(3) 해당되는 경우, 모니터링과 측정 요구사항의 포함 또는 인용, 그리고 합격 판전기준의
포함 또는 인용
(4) 의도한 목적에, 그리고 안전하고 올바른 제공에 필수적인 제품 및 서비스의 특성을 규정
(5) 조직은 설계 및 개발 출력에 대한 문서화된 정보를 보유해야 한다.
8.3.5.1 설계와 개발 출력 - 보충사항
제품 설계 출력은 제품 설계 입력 요구사항에 대하여 검증되고 실현성확인/타당성
확인 될 수 있는 관점에서 표현되어야 한다. 해당되는 경우 제품 설계 출력은 다음
사항을 포함하여야 하지만 이에 국한하지 않는다.
(1) 설계 리스크 분석 (FMEA)
(2) 신뢰성 조사 결과
(3) 제품 특별 특성
(4) DFSS, DFMEA, 및 FTA와 같은 제품 설계 실수-방지의 결과
(5) 3D모델, 기술적 데이터 패키지, 제품 제조 정보 및 기하학적 치수 및 허용오차
(GD&T)를 포함한 제품 정의
(6) 2D도면, 제품 제조 정보 및 기하학적 치수 및 허용오차
(7) 제품 설계 검토 결과
(8) 서비스 진단 가이드라인과 수리 및 서비스 지침
(9) 서비스 부품 요구사항
(10) 선적을 위한 포장 및 라벨링 요구사항
비고. 중간의 설계 출력은 트래드-오프 프로세스를 통해 해결될 모든 엔지니어링 문제를
포함하여야 할 것이다.
8.3.5.2 제조 공정 설계 출력
해당 부서장은 제조 공정 설계 입력에 대하여 검증 가능한 방식으로 제조 공정 설계 출력을 문서화
하여야 한다. 입력 요구사항과 비교하여 출력을 검증하여야 하며, 다음을 포함하되 국한하지 않는다.
(1) 제조 레시피(시방서) 및 도면
(2) 제품 및 제조 공정에 대한 특별 특성
(3) 특성에 영향을 주는 공정 입력 변수의 파악
(4) 장비 및 공정의 능력 조사를 포함한 생산 및 관리를 위한 치공구와 장비
(5) 제품, 공정 및 치공구의 연계성을 포함한 제조 공정 흐름도/배치도
(6) 생산능력 분석
(7) 제조 공정 FMEA
(8) 보전 계획 및 지침
(9) 관리 계획서
(10) 표준 작업 및 작업 지침서
(11) 공정 승인 합격 판정 기준
(12) 품질, 신뢰성, 보전성 및 측정가능성에 대한 데이터
(13) 해당되는 경우, 실수 방지 확인 및 검증의 결과
(14) 제품/제조 공정 부적합의 신속한 검출, 피드백 및 시정 방법
8.3.6 설계와 개발 변경
해당 부서장은 제품 및 서비스의 설계와 개발 과정, 또는 이후에 발생되는 변경사항을
요구사항의 적합성에 부정적 영향이 없음을 보장하는데 필요한 정도까지 식별, 검토 및
관리하여야 하며, 다음의 문서화된 정보를 보유하여야 한다.
(1) 설계와 개발 변경
(2) 검토 결과
(3) 변경의 승인
(4) 부정적 영향을 예방하기 위하여 취한 조치
8.3.6.1 설계와 개발 변경 - 보충사항
(1) 장착성, 형상, 기능, 성능 및/또는 내구성에 잠재적 영향에 대해, 조직 또는 조직의
공급자에 의해 제안된 변경사항을 포함한 최초 제품 승인 이후에 모든 설계 변경사항을
조직은 평가하여야 한다.
(2) 변경은 생산 실행에 앞서 내부적으로 승인되고 고객 요구사항과 비교하여 유효성
확인되어야 한다.
(3) 고객에 의해 요구되는 경우, 조직은 생산 실행에 앞서 고객으로부터의 문서화된
승인이나 문서화된 면제를 얻어야 한다.', 56
WHERE NOT EXISTS (SELECT 1 FROM regulation_sections WHERE reg_code = 'QM' AND sort_order = 56);
INSERT INTO regulation_sections (reg_code, section_title, section_body, sort_order)
SELECT 'QM', '8.4 외부에서 제공되는 프로세스, 제품 및 서비스의 관리', '8.4.1 일반사항
(1) 해당 부서장은 외부에서 제공되는 프로세스, 제품 및 서비스가 요구사항에 적합함을
보장한다.
(2) 해당 부서장은 다음의 경우 외부에서 제공되는 프로세스, 제품 및 서비스 적용 검토,
결정한다.
가. 외부 제공자의 제품 및 서비스가 조직자체의 제품 및 서비스에 포함되도록 의도한 경우
나. 제품 및 서비스가 조직을 대신한 외부 제공자에 의해 고객에게 직접 제공되는 경우
다. 프로세스 또는 프로세스의 일부가 조직에 의한 결정의 결과로 외부 제공자에 의해
제공되는 경우
(3) 요구사항에 따라 프로세스 또는 제품 및 서비스를 공급할 수 있는 능력을 근거로
외부 제공자의 평가, 선정, 성과 모니터링 및 재평가에 대한 기준을 결정하고 적용
하여야 한다.
(4) 해당 부서장은 이들 활동에 대하여 평가를 통해 발생한 모든 필요한 조치에 대하여
문서화된 정보를 보유한다.
8.4.1.1 일반사항 - 보충사항
해당 부서장은 외부에서 제공되는 제품, 프로세스 및 서비스의 그들 정의 범위에서
소조립, 서열, 분류, 재작업 및 교정 서비스 같은 고객 요구사항에 영향을 주는 모든
제품 및 서비스를 포함하여야 한다.
8.4.1.2 공급자 선정 프로세스
해당 부서장은 문서화된 공급자 선정 프로세스를 가지고 있어야 하며, 그 선정
프로세스는 다음을 포함하여야 한다.
(1) 제품 적합성과 그들의 고객에게 조직의 제품의 중단되지 않는 공급에 대해 선정되는
공급자 리스크의 평가
(2) 관련 품질 및 인도 성과
(3) 공급자 품질 경영 시스템의 평가
(4) 전문 분야 협력 의사 결정
(5) 해당하는 경우 소프트웨어 개발 능력의 평가
(6) 자동차산업 비즈니스의 생산량 (절대값 그리고 통 비즈니스 중의 비율로서)
(7) 재정 안전성
(8) 구매된 제품, 재료, 또는 서비스 복잡성
(9) 요구되는 기술 (제품 또는 공정)
(10) 이용 가능한 자원의 적절성 (사람, 기반구조 등)
(11) 설계 및 개발 능력 (프로젝트 관리를 포함한)
(12) 제조 능력
(13) 변경 관리 프로세스
(14) 비즈니스 지속성 기획 (재해 준비, 비상 기획 등)
(15) 물류 프로세스
(16) 고객 서비스
8.4.1.3 고개-직접 출처 (직접-구매)
(1) 고객에 의해 규정된 경우, 고객 직접 출처로부터 제품, 재료 또는 서비스를 구매하여야
한다.
(2) 8.4항의 모든 요구사항(IATF 16949 8.4.1.2 항의 요구사항을 제외한)은 구체적 합의가
조직과 고객 간의 계약에서 달리 정의하지 않는 한 고객 직접 출처에 대한 조직의
관리에 적용 가능하다.
8.4.2 관리의 유형과 정도
(1) 해당 부서장은 외부에서 제공되는 프로세스, 제품 및 서비스가 적합한 제품 및 서비스를
고객에게 일관되게 인도하는 능력에 부정적인 영향을 미치지 않음을 보장하여야 한다.
(2) 해당 부서장은 다음사항을 수행하여야 한다.
가. 외부에서 제공되는 프로세스가 조직의 품질경영시스템 관리 내에 유지됨을 보장
나. 외부 제공자에게 적용될 관리와 결과로 나타나는 출력에 적용될 관리 모두를 규정
다. 다음에 대한 고려
- 고객요구사항, 법적 및 규제적 요구사항을 일관되게 충족시켜야 하는 조직의 능력에
미치는 외부에서 제공되는프로세스, 제품 및 서비스의 잠재적 영향
- 외부 제공자에 의해 적용되는 관리의 효과성
라. 외부에서 제공되는 프로세스, 제품 및 서비스가 요사항을 충족시킴을 보장하기 위해
필요한 검증 또는 그 밖의 활동의 결정
8.4.2.1 관리의 유형과 정도 - 보충사항
(1) 조직은 내부(조직) 및 외주 고객 요구사항에 대해 외부에서 제공된 제품, 프로레스 및
서비스의 적합성을 검증하는데 사용되는 관리의 유형 및 정도를 선정하고 외주 처리된
프로세스를 파악하는 문서회된 프로세스를 가지고 있어야 한다,
(2) 프로세스는 공급자 성과와 제품, 자재 또는 서비스 리스크의 평가를 근간으로 하여
관리의 유형과 정도 및 개발 활동을 감소시키거나, 단계적 확대(escalate)시키는 기준 및
조치를 포함하여야 한다.
(3) 특별 또는 부품들이 실현성 확인 / 타당성 확인 또는 관리없이 조직의 품질, 환경 경영시스템을
"통과"한 경우, 조직은 제조시점에서 적절한 관리가 이루어 짐을 보장하여야 한다.
8.4.2.2 법적 요구사항 및 규제적 요구사항
(1) 해당 부서장은 제공되는 경우 구매되는 제품, 프로세스 및 서비스가 고객의 식별된
국가 도착지와 선적 국가, 반입 국가에서의 현재 적용 가능한 법적 요구사항 및 규제적
요구사항에 적합하다는 것을 보장하기 위해 그들의 프로세스를 문서화하여야 한다.
(2) 만약 고객이 법적 요구사항 및 규제적 요구사항을 갖는 어떤 제품에 대한 특별 관리를
규정한다면, 조직은 공급자를 포함하여 그것들이 규정된 대로 실행 및 유지됨을 보장
하여야 한다.
8.4.2.3 공급자 품질,환경 경영 시스템 개발
조직은 자동차 산업 제품 및 서비스의 공급자에게 이 자동차 품질,환경 경영시스템 표준에 대한
인증을 취득한 자격이 있는 조직의 궁극적인 목표에 따라 품질,환경 경영시스템을 개발, 실행
및 개선하도록 요구하여야 한다.
리스크 기반 모델을 사용하여, 조직은 각 공급자에 대해 최소 수용가능한 수준의 품질,환경
경영시스템 개발 및 목표 품질,환경 경영시스템 개발 수준을 규정해야 한다
고객에 의해 달리 승인되지 않는 한 ISO 9001/ISO14001에 인증된 품질,환경 경영시스템은 최초,
최소 수용가능한 수준의 개발이다. 고객에 대한 현재 성과 및 잠재적인 리스크를 근간으로 하여,
다음과 같은 품질,환경 경영시스템 개발 진행과정을 통해 공급자가 대응하도록 하는 것이 목표이다
(1) 3자 심사를 통한 ISO 9001/ISO 14001에 대한 인증; 고객에 의해 달리 규정되지 않는 한,
조직에 대한 공급자는 공인된 IAF MLA(국제인증 포럼 상호 인정 결정)의 인정 마크를 갖는 인증
기관에 의해 발행된 3자 인증을 유지함에 의해 ISO 9001/ISO 14001에 대한 적합성을 실증하여야
하고 인정 기관의 주요 범위는 ISO/IEC 17021에 대한 경영 시스템 인증을 포함하는 경우를 실증
하여야 한다
(2) 2자 심사를 통해 기타 고객이-규정한 품질,환경 경영시스템 요구사항(하위 단계 공급자에 대한
최소한의 자동차 품질,환경 경영시스템 요구사항[MAQMSR], 또는 이와 동등한)에 대한 준수와
함께 ISO 9001/ISO 14001 에 대한 인증
(3) 2자 심사를 통해 IATF 16949/iso 14001에 대한 준수와 함께 ISO 9001에 대한 인증
(4) 3자 인증 심사를 통해 IATF 16949 에 대한 인증(IATF-공인된 인증기관에 의해 IATF
16949 로 공급자에 대한 유효한 3 자 인증).
※품질,환경 경영 시스템 개발의 최소 수용가능한 수준은 고객에 의해 승인된 경우, 2자
심사를 통해 ISO 9001/ISO 14001에 대한 준수가 될 수 있습니다.
8.4.2.3.1 자동차 산업 제품-관련 소프트웨어 또는 소프트웨어가 내장된 자동차 산업 제품
- 해당없음
8.4.2.4 공급자 모니터링
조직은 내부 및 외부 고객 요구사항에 대한 외부에서 제공된 제품, 공정 및 서비스의
적합성을 보장하기 위해 공급자 성과를 평가하는 기준과 문서화된 프로세스를 가지고
있어야 한다. 최소한, 다음의 공급자 성과 지표는 모니터 되어야 한다.
(1) 요구사항에 대한 인도된 제품 적합성
(2) 야적 및 선적 중단을 포함한 반입 플랜트에서의 고객 공급 중단사항
(3) 인도 일정계획 성과
만약 고객사 제공시, 조직은 그들의 공급자 성과 모니터링에서 해당되는 경우 다음 포함
(4) 품질 또는 인도 문제와 관련된 고객 통지의 특별 상황
(5) 딜러 반송, 보증, 필드 조치 및 리콜
8.4.2.4.1 2자 심사
(1) 해당 부서장은 그들의 공급자 관리 접근방법에서 2자 심사 프로세스를 포함하여야
하며, 다음 사항에 대해 사용될 수 있다.
가. 공급자 리스크 평가
나. 공급자 모니터링
다. 공급자 품질겨영시스템 개발
라. 제품 심사
마. 프로세스 심사
(2) 최소한 제품안전/규제적 요구사항, 공급자 성과 및 품질경영시스템 인증수준을 포함한
리스크 분석을 근간으로 하여, 요구, 형태, 빈도 및 2자 심사 범위를 결정하는 기준을
문서화하여야 하며, 심사 보고서의 기록을 보존하여야 한다.
(3) 만약 3자 심사 범위가 공급자 품질 경영시스템을 평가하는 것이라면, 그 접근법은
자동차 산업 프로세스 접근법과 일관성이 있어야 한다.
8.4.2.5 공급자 개발
(1) 해당 부서장은 활동 중인 공급자를 위해 요구되는 공급자 개발 조치의 우선순위, 유형,
정도 및 시점을 결정하여야한다. 결정 입력은 다음 사항을 포함하지만 그것으로 제한
하지는 않는다.
가. 공급자 모니터링을 통해 파악된 성과 문제
나. 2자 심사 발견사항
다. 3자 품질경영시스템 인증 현황
라. 리스크 분석
(2) 미해결된 (불만족스러운) 성과 이슈를 해결하기 위해 필요한 조치를 실행하고 지속적
개선을 위한 기회를 추구하여야 한다.
8.4.3 외부 제공자를 위한 정보
(1) 해당 부서장은 외부제공자와 의사소통 하기 전에 요구사항의 충분성을 보장하여야 한다.
(2) 해당 부서장은 다음사항에 대한 조직의 요구사항을 외부 제공자에게 의사소통 하여야
한다.
가. 제공되는 프로세스, 제품 및 서비스
나. 다음에 대한 승인
- 제품 및 서비스
- 방법, 프로세스 및 장비
- 제품 및 서비스의 불출
다. 요구되는 모든 인원의 자격을 포함한 역량/적격성
라. 조직과 외부제공자의 상호작용
마. 외부제공자의 성과에 대하여 조직이 적용하는 관리 및 모니터링
바. 조직 또는 조직의 고객이 외부 제공자의 사업장에서 수행하고자 하는 검증 또는
실현성 확인 활동
8.4.3.1 외부 공급자를 위한 정보 - 보충사항
해당 부서장은 모든 해당되는 법적 요구사항 및 규제적 요구사항과 그들의
공급자에 대한 특별 제품 특성 및 공정 특성을 전개하여야 하고, 제조점에 있는
공급망에 모든 해당되는 요구사항을 공급자에게 연속 전개하도록 공급자에게
요구하여야 한다.', 57
WHERE NOT EXISTS (SELECT 1 FROM regulation_sections WHERE reg_code = 'QM' AND sort_order = 57);
INSERT INTO regulation_sections (reg_code, section_title, section_body, sort_order)
SELECT 'QM', '8.5 생산 및 서비스 제공', '8.5.1 생산 및 서비스 제공 관리
생산 부서장은 제품 및 서비스 제공을 관리되는 조건하에 실행하여야 하며 관리되는
조건에는 다음 사항이 포함되여야 한다.
(1) 다음을 규정한 문서화된 정보의 가용성
가. 생산될 제품, 제공될 서비스 또는 수행될 활동의 특성
나. 달성되어야 하는 결과
(2) 적절한 모니터링 및 측정 자원의 가용성 및 활용
(3) 프로세스 또는 출력의 관리에 대한 기준과 제품 및 서비스에 대한 합격 판정 기준에
충족됨을 검증하기 위해 적절한 단계에서 모니터링 및 측정 활동의 실행
(4) 프로세스 운영을 위한 적절한 기반구조 및 환경의 활용
(5) 요구되는 모든 자격을 포함하여, 적격한 인원의 선정
(6) 결과물이 후속되는 모니터링 및 측정에 의해 검증될 수 없는 경우, 생산 및 서비스
제공을 위한 프로세스의 계획된 결과를 달성하기 위한 능력의 실현성 확인 및 주기적인
재 실현성 확인
(7) 인적 오류를 예방하기 위한 조치의 실행
(8) 불출, 인도 및 인도 후 활동의 실행
8.5.1.1 관리 계획서
(1) 생산 부서장은 부품뿐만 아니라 대량 자재도 생산하는 공정에 대한 관리 계획서를
포함하여, 관련 제조 현장 및 모든 공급되는 제품에 대한 시스템, 하위 시스템, 구성품
및 재료 수준에서 관리 계획서를 개발하여야 한다.
(2) 동일계열 관리 계획서는 공통된 제조 공정을 사용한 대량 자재 및 유사한 부품에
대해서는 수용 가능하다.
(3) 설계 리스크 분석, 공정흐름도, 그리고 제조 공정 리스크 분석 출력으로부터 정보를
통합하고 연계성을 보여주는 양산 전 및 양산에 대한 관리 계획서를 갖추어야 한다.
(4) 고객 요구 시 양산 전 관리 계획서 또는 양산 관리 계획서든 실행동안 수집된 측정 및
적합성 데이터를 제공하여야 하며, 다음을 관리 계획서에 포함하여야 한다.
가. 작업 셋업 검증을 포함한 제조 공정 관리를 위해 사용되는 관리
나. 해당되는 경우 초물/중물 부품 실현성확인/타당성 확인
다. 고객 및 조직 모두에 의해 규정된 특별특성에 대한 통제를 실시하는 모니터링에
대한 방법
라. 만약 있다면, 고객이 요구하는 정보성
바. 규정된 대응계획 (부적합품이 검툴되는 경우 공정은 통계적으로 불안정하거나
통계적으로 능력이 없게 된다.)
사. 다음 중 어떤 경우에 대해서도 관리계획서를 검토하고 요구된 대로 갱신하여야 한다.
- 회사는 그것이 고객에게 부적합 제품을 선적하였던 것으로 결정한다.
- 제품, 제조공정, 측정, 물류, 공급 출처, 생산량 변경 또는 리스크 분석에 영향을
주는 어떤 변경이 발생하는 경우
- 해당되는 경우, 고객불만 및 연관된 시정조치의 실행 후
- 리스크 분석을 근간으로 한 설정된 빈도
아. 고객에 의해 요구되는 경우, 관리계획서의 검토 또는 제정 후 고객의 승인을
얻어야 한다.
8.5.1.2 표준화된 작업 - 작업지침서 및 시각적 표준
(1) 생산 부서장은 표준화된 업무 문서가 있다는 것을 보장하여야 한다.
가. 업무 수행에 책임이 있는 종업원에 의해 이해되도록 의사소통 되는
나. 읽을 수 있는
다. 그것을 따라야 할 책임이 있는 인원에 의해 이해되는 언어로 보여주는
라. 지정된 작업 구역에서 사용을 위해 접근 가능한
(2) 표준화된 업무 문서는 작업자 안전을 위한 규칙을 또한 포함해야 한다.
8.5.1.3 작업 셋업 검증
생산 부서장은 다음을 하여야 한다.
(1) 작업 셋업은 작업의 첫 가동, 자재 교체 또는 새로운 셋업이 요구되는 작업 변경과
같이, 수행될 때 검증되어야 한다.
(2) 셋업 인원을 위한 문서화된 정보를 유지하여야 한다.
(3) 해당되는 경우, 통계적 검증밥법을 사용하여야 한다.
(4) 해당되는 경우 초물/종물 부품 실현성확인/타당성확인을 수행한다. 초물 부품은
종물 부품과 비교를 위해 보존되어야 한다.
(5) 셋업 및 초물/종물 부품 실현성확인/타당성확인에 따르는 공정 및 제품 승인 프로세스
기록을 보존한다.
8.5.1.4 생산 가동정지 후 검증
생산 부서장은 계획되거나 또는 계획되지 않은 생산 가동정지 기간 후 요구사항에
대한 제품 적합성을 보장하기 위해 필요한 조치를 규정하고 실행하여야 한다.
8.5.1.5 총체적 예방 보전
생산 부서장은 문서화된 총체적 예방보존 시스템을 개발, 실행 및 유지하여야 하며,
최소한 시스템은 다음을 포함하여야 한다.
(1) 요구되는 생산량으로 적합한 제품을 생산하기 위해 필요한 공정장비의 파악
(2) 항목 (1)에서 파악된 공정장비에 대한 교체부품의 가용성
(3) 기계, 장비 및 시설 유지보수를 위한 자원 확보
(4) 장비, 치공구 및 게이지의 포장 및 보존
(5) 해당되는 고객 지정요구사항
(6) 문서화된 보전 목표, 예를 들면 OEE(총체적 장비 효과성),MTBF(평균 고장 간격 시간),
MTTR(평균 수리 시간) 그리고 예방보전 준수 성과지표. 보전 목표에 대한 성과는
경영검토의 입력으로 구성한다.
(7) 보전 계획 및 목표에 대한 정기적인 검토 그리고 보전 목표가 달성되지 않은 경우
시정조치를 다루는 문서화된 조치 계획
(8) 예방보전 방법의 사용
(9) 해당되는 경우, 예측보전 방법의 사용
(10) 주기적인 완전분해점검
8.5.1.6 생산 치공구와 제조, 시험, 검사 치공구 및 장비의 관리
(1) 해당 부서장은 생산 및 서비스 자재와 대량자재에 대한 검증활동을 위한 자원을
제공하여야 하며, 다음 사항을 포함하여 당사 소유 또는 고객 소유든 간에 생산 치공구
관리를 위한 시스템을 수립하고 실행하여야 한다.
가. 보전 및 수리 시설과 인원
나. 보관 및 복구
다. 셋업
라. 소모성 치공구에 대한 치공구 교환 프로그램
마. 제품의 엔지니어링 변경 수준을 포함한 치공구 설계 수정의 문서화
바. 치공구 수정 및 문서에 대한 제정
사. 일련 또는 자산번호와 같은 치공구 식별; 수리 또는 폐기, 책임자 및 위치와 같은 현황
(2) 고객소유의 금형, 제조 장비 및 시험/검사 장비가 각 품목의 책임자 및 적용이 결정될 수
있도록 관리 및 검증하여야 한다.
8.5.1.7 생산 일정 계획
해당 부서장은 공정의 주요단계에서 생산 정보에 대한 접근을 허용하고 고객
주문/수요를 충족하도록 일정계획 수립됨을 보장하며, 생산 일정계획 동안, 예를 들면
고객주문, 공급자 적시 인도성과, 생산능력, 공유되는 부하/생산량(복수의 부품 작업장)
리드타임, 재고수준, 예방보존 및 교정과 같은 관련 기획정보를 포함하여야 한다.
8.5.2 식별 및 추적성
(1) 해당 부서장은 제품실현의 모든 단계에서 해당되는 경우 적절한 수단으로 제품을
식별하여야 한다.
(2) 해당 부서장은 제품실현의 모든 단계에서 모니터링 및 측정 요구사항과 관련하여
제품상태를 식별하여야 한다.
(3) 추적성이 요구사항 인 경우, 해당 부서장은 제품의 고유한 식별을 관리하고 기록을
유지 하여야 한다.
(4) 추적성이 가능하기 위해 필요한 문서화된 정보를 보유하여야 한다.
비고. 검사 및 시험 상태는 자동화된 생산이송 공정 내에 있는 자재와 같이, 본질적으로
명백하지 않는 한 생산흐름 내에 있는 제품의 위치에 의해 나타내지 못한다. 만약
그 상태가 명료하게 식별 되고, 문서화되고, 지정된 목적을 달성한다면 대체 방법은
허용된다.
8.5.2.1 식별과 추적성 - 보충사항
(1) 추적성의 목적은 품질 및 안전 관련 부적합을 포함할 수 있는 필드 또는 고객에 의해
접수된 제품에 대한 명료한 시작점과 종료점의 식별을 지원하기 위한 것이며, 조직은
아래 기술된 대로 식별 및 추적성 프로세스를 실행하여야 한다.
(2) 종업원, 고객 및 소비자에 대한 리스크 수준 또는 고장 심각도를 근간으로 한 추적성
포함하여 모든 자동차산업 제품에 대한 내부요구사항, 고객 요구사항 및 규제적 추적성
요구사항의 분석을 수행하여야 한다.
(3) 이러한 계획은 적절한 추적성 시스템, 프로세스 그리고 다음에 대한 제조 장소, 제품,
공정 별 방법을 규정하여야 한다.
가. 조직이 부적합 제품 또는 의심스러운 제품을 식별 가능하도록 하는 것
나. 조직이 부적합 또는 의심스러운 제품을 격리 가능하도록 하는 것
다. 고객 또는 규제적 대응 시간 요구사항을 충족하기 위한 능력을 보장하는 것
라. 조직이 대응 시간 요구사항을 충족 가능하도록 하는 형태(전자, 인쇄본, 아카이브)로
문서화된 정보가 보유됨을 보장하는 것
마. 만약 고객 또는 규제적 표준에 의해 규정된다면, 개별 제품의 일련번호가 부여된
식별을 보장하는 것
바. 식별 및 추적성 요구사항이 안전/규제적 특성을 갖는 외부로 제공된 제품으로 확대
되도록 보장하는 것
8.5.3 고객 또는 외부 제공자의 재산
(1) 당사 관리 하에 있거나 당사에 의하여 사용 중에 있는 고객 또는 외부 공급자의 자산에
대하여 주의를 기울여야 한다.
(2) 제품 및 서비스에 사용되거나 포함되도록 제공된 고객 / 외부 공급자의 자산을 식별,
검증, 보호 및 안전하게 유지해야 한다.
(3) 고객 또는 외부 공급자 자산이 분실, 손상 또는 사용하기에 부적절한 것으로 판명된 경우,
조직은 고객 또는 외부 공급자에게 이를 보고해야 하며, 발생한 사항에 대해 문서화된
정보를 보유해야 한다.
비고. 고객 또는 외부제공자 재산에는 자재, 부품, 공구 및 장비, 고객 사업장, 지적소유권 및
개인 정보가 포함될 수 있다.
8.5.4 보존
요구사항에 적합함을 보장하기 위해 필요한 범위까지 생산 및 서비스를 제공하는 동안
출력을 보존하여야 한다.
비고. 보존은 식별, 취급, 오염관리, 포장, 보관, 전달, 운송 및 보호가 포함될 수 있다.
8.5.4.1 보존 - 보충사항
(1) 보존은 식별, 취급, 봉쇄 관리, 포장, 보관, 전송 또는 운송 및 보호를 포함하여야 한다.
(2) 보존은 선적과 고객에게 인도되고 합격될 때 까지를 포함한, 반입에서 가공까지 외부 및
내부 공급자로부터의 자재 및 구성품에 적용하여야 한다.
(3) 품질저하를 검출하기 위해, 조직은 재고로 있는 제품의 상태, 보관 T/K 등의 보관 환경을
적절한 계획 주기로 평가하여야 한다.
(4) 지속적으로 재고 회전을 최적화하고 ''선입 선출''과 같은 재고 회전을 보장하기 위해
재고관리 시스템을 사용하여야 한다.
(5) 효력이 상실된 제품이 부적합 제품과 유사한 방식으로 관리됨을 보장하여야 한다.
(6) 고객에 의해 제공된 대로 보존, 포장, 선적 및 라벨링 요구사항을 준수하여야 한다.
8.5.6 인도 후 활동
(1) 해당 부서장은 제품 및 서비스와 관련된 인도 후 활동에 대한 요구사항을 충족하여야
한다.
(2) 요구되는 인도 후 활동의 범위를 결정할 때, 다음사항을 고려하여야 한다.
가. 법적 및 규제적 요구사항
나. 제품 및 서비스와 관련된 잠재적으로 원하지 않는 결과
다. 제품 및 서비스이 특성, 사용과 의도된 수명
라. 고객 요구사항
마. 고객의 피드백
비고. 인도 후 활동은 보증규정에 따른 활동, 재활용, 최종 처분 등의 유지서비스와 부가
서비스와 같은 계약상 의무사항에 따른 활동을 포함 할 수 있다.
8.5.5.1 서비스로부터 정보의 피드백
해당 부서장은 제조, 자재 취급, 물류, 엔지니어링 및 설계 활동에 대한 서비스 우려사항
에 관하여 정보 의사소통을 위한 프로세스가 수립, 실행 및 유지됨을 보장하여야 한다.
비고 1. ''서비스 우려사항''을 추가한 의도는 고객 위치 또는 필드에서 확인될 수 있는부적합
제품 및 자재에 대하여 인식하고 있음을 보장하기 위한 것이다.
비고 2. ''서비스 우려사항''은 해당되는 경우 필드 고장 시험 분석의 결과를 포함하여야
할 것이다.
8.5.5.2 고객과의 서비스 계약
고객과의 서비스 계약이 있는 경우, 조직은 다음을 하여야 한다.
(1) 관련 서비스 센터가 해당 요구사항을 준수하고 있음을 검증하여야 한다.
(2) 모든 특수 목적 치공구 또는 측정 장비의 효과성을 검증하여야 한다.
(3) 모든 서비스 인원이 해당 요구사항에 대해 교육훈련 되었다는 것을 보장하여야 한다,
8.5.6 변경관리
(1) 품질보증부서장은 규정된 요구사항에 적합함을 지속적으로 보장하는데 필요한 범위에서
제품 및 서비스 제공에 필수적인 변경을 검토하고 관리하여야 한다.
(2) 회사는 변경사항에 대한 검토 결과, 변경 승인자 및 검토결과 발생한 필요한 조치사항을
기술한 문서화된 정보를 보유하여야 한다.
8.5.6.1 변경사항 - 보충 사항
(1) 제품 실현에 영향을 미치는 변경들에 대해 관리 및 대응하는 문서화된 프로세스를
가지고 있어야 한다.
(2) 당사, 고객 또는 모든 공급자에 의해 야기된 변경사항을 포함한 모든 변경의 영향은
다음을 평가하여야 한다.
가. 고객 요구사항의 준수를 보장한느 검증 및 실현성확인/타당성확인 활동을 규정하는 것.
나. 실행 전에 변경사항을 타당성확인 하는 것
다. 관련된 리스크 분석의 증거를 문서화하는 것
라. 검증 및 실현성확인/타당성확인의 기록을 보유하는 것
(3) 공급자에서 만들어진 것을 포함한 변경사항은 제조 공정의 모든 변경에 영향을 타당성
확인 하기 위해 변경의 검증(부품 설계, 제조 위치 또는 제조 공정에 대한 변경과 같은)을
위한 생산 시험 가동을 요구하여야 할 것이다.
(4) 고객에 의해 요구되는 경우, 조직은 다음을 하여야 할 것이다.
가. 가장 최근 제품 승인 이후 모든 계획된 제품 실현 변경을 고객에게 통보한다.
나. 변경의 실행에 앞서 문서화된 승인을 얻는다.
다. 생산 시험 가동 및 새로운 제품 실현성 확인과 같은 추가적인 검증 또는 식별
요구사항을 완수한다.
8.5.6.1.1 공정 관리의 임시 변경
(1) 조직은 검사, 측정, 시험 및 실수 방지 기기를 포함한 공정 관리 목록을 파악하고,
문서화하고 유지하여야 한다. 빽업 또는 대체 방법이 존재하는 경우, 공정관리 목록에는 중요
공정 관리 및 승인된 빽업 또는 대체 방법이 포함되어야 한다.
(2) 해당 부서장은 대체 관리 방법의 사용을 관리하는 프로세스를 문서화한다.
(3) 리스크 분석, 심각도, 그리고 대체 관리 방법의 생산 실행에 앞서 얻어진 내부 승인을
프로세스에 포함한다.
(4) 만약 요구되는 경우 대체 방법을 사용하여 검사되고 시험된 제품의 선적 전에, 조직은
고객으로부터 승인을 얻어야 한다.
(5) 해당 부서장은 관리 계획서에 언급된 승인된 대체 공정 관리 방법의 목록을 주기적으로
검토하고 유지한다.
(6) 표준 작업 지침서는 각각의 대체 공정 관리 방법을 위해 이용 가능하여야 한다.
가능한 한 빨리 관리계획서에 의해 규정된 대로 표준 프로세스로 돌아가는 목표를 갖고
표준 작업의 실행을 검증하기 위해서 최소한 매일 대체 공정 관리의 운영을 검토하여야
한다. 예시 방법은 다음을 포함하지만 다음으로 국한되지는 않는다.
가. 매일 품질 중심의 심사 (예를 들어, 해당되는 경우 계층별 프로세스 심사)
나. 매일 리더십 회의
(7) 공정의 모든 특성이 효과적으로 복원되는지에 대한 확인과 심각도를 기반으로 하여
재시작 검증은 규정된 기간에 대해 문서화된다.
(8) 모든 대체 공정 관리 기기 또는 공정이 사용되고 있는 동안 생산된 모든 제품에 대한
추적성을 실행하여야 한다.
(예를 들어 모든 고대조로부터의 초물 및 종물의 검증과 보존)', 58
WHERE NOT EXISTS (SELECT 1 FROM regulation_sections WHERE reg_code = 'QM' AND sort_order = 58);
INSERT INTO regulation_sections (reg_code, section_title, section_body, sort_order)
SELECT 'QM', '8.6 제품 및 서비스의 불출 / 출시', '(1) 품질보증 부서장은 제품 및 서비스 요구사항이 충족되었음을 검증하기 위하여 적절한
단계에서 계획된 결정사항을 실행 하여야 한다.
(2) 고객이 승인한 경우를 제외하고는 계획된 결정사항이 만족스럽게 완료될 때까지 제품 및
서비스는 고객에게 불출되지 않아야 한다.
(3) 해당 부서장은 제품 및 서비스의 불출과 관련된 문서화된 정보를 보유하여야 하며
다음사항이 포함 되어야 한다.
가. 합격판정기준에 적합하다는 증거
나. 불출 승인을 위한 인원에 대한 역량/적격성
8.6.1 제품 및 서비스의 불출 / 출시 - 보충사항
(1) 제품 및 서비스 요구사항이 관리계획서에 규정된 대로 문서화되고 관리계획서를 아울러
충족되었음을 검증하기 위해 계획된 준비사항을 보장하여야 한다.
(2) 제품 및 서비스의 최초 출시에 대한 계획된 준비사항이 제품 또는 서비스 승인을 포함
한다는 것을 보장하여야 한다.
(3) 조직은 제품 또는 서비스 승인이 ISO 9001, 섹션 8.5.6에 따라 최초 출시에 뒤따른
변경 후 완수됨을 보장하여야 한다.
8.6.2 정밀 검사 및 기능 시험
해당되는 고객 엔지니어링 자재 및 성능규격에 대한 정밀검사 및 기능검등은 관리계획서
내에 규정된 대로 각각의 제품에 대하여 수행되어야 하며 결과는 고객 검토를 위해 이용
가능하여야 한다.
비고 1. 정밀 검사는 설계 기록상에 나타난 모든 제품 치수의 완전한 측정이다.
비고 2. 정밀 검사의 빈도는 고객에 의해 결정된다.
8.6.3 외관 품목
''외관 품목''으로 고객에 의해 지정된 제조 부품에 대하여, 다음을 제공하여야 한다.
(1) 평가를 위한 조명을 포함한 적절한 자원
(2) 해당되는 경우 색상, 입자, 광택, 금속성 광도, 조직, 이미지구별, 촉각 기술을 위한 표본
(3) 외관 표본 및 평가 장비의 보전 및 관리
(4) 외관 평가 수행인원이 그렇게 수행하기에 유능하고 자격 부여되었는지를 검증
8.6.4 외부에서 제공된 제품 및 서비스에 대한 적합성의 검증 및 수용
다음 방법 중 하나 이상을 활용하여 외부에서 제공된 공정 제품 및 서비스의 품질을
보장하는 프로세스를 갖고 있어야 한다.
(1) 공급자에 의해 조직에게 제공된 통계적 데이터의 접수 및 평가
(2) 성과를 기반으로 한 샘플링과 같은 수입검사 및 시험
(3) 합격 가능한 인도된 제품 요구사항에 대한 적합성의 기록과 연결될 경우 제 2자 또는
제 3자평가 혹은 공급자 현장에 대한 심사
(4) 지정된 시험실에 의한 부품 평가
(5) 고객과 합의된 또 다른 방법
8.6.5 법적 및 규제적 적합성
생산 흐름으로 외부에서 제공된 제품의 불출 전에 외부에서 제공된 프로셋, 제품 및
서비스가 만약 제공된다면 고객이 식별한 국가의 도착지로 그리고 그들이 제조된
국가에서의 최신의 적용 가능한 법적 규제적 및 기타 요구사항에 적합하다는 것에
대한 증거를 제공할 수 있고 확인하여야 한다.
8.6.6 합격 판정기준
(1) 합격 판정기준은 조직에 의해서 정의되어야 하고 해당되거나 요구되는 경우 고객에
의해 승인되어야 한다.
(2) 계수치 데이터 샘플링에 대해 합격수준은 무결점이 되어야 한다.', 59
WHERE NOT EXISTS (SELECT 1 FROM regulation_sections WHERE reg_code = 'QM' AND sort_order = 59);
INSERT INTO regulation_sections (reg_code, section_title, section_body, sort_order)
SELECT 'QM', '8.7 부적합 출력의 관리', '8.7.1 부적합품 관리
(1) 품질 부서장 의도하지 않은 사용 또는 인도를 방지하기 위하여, 제품 요구사항에 적합
하지 않은 제품이 식별되고 관리됨을 보장하여야 한다.
(2) 부적합의 성질에, 그리고 제품 및 서비스의 적합성에 대하여 부적합이 미치는 영향에
따라 적절한 조치를 취하여야 한다. 이것은 제품의 인도 후, 서비스의 제공 중 또는
제공 후 발견된 제품 및 서비스 부적합에도 적용된다.
(3) 부적합 출력을 다음의 하나 또는 그 이상의 방법으로 처리하여야 한다
가. 시정
나. 제품 및 서비스 제공의 격리, 봉쇄/억제, 반품 또는 정지
다. 고객에게 통지
라. 특채에 의해 인수를 위한 승인의 획득
8.7.1.1 특채를 위한 고객 승인
(1) 조직은 제품 또는 제조공정이 현재 승인된 것과 상이할 때마다 더 이상 진행에 앞서 고객
특채 또는 기준이탈 허가를 받아야 한다.
(2) 조직은 부적합 제품의 수리와 ''현재 상태로 사용''을 위한 더 이상의 진행에 앞서 고객 승인을
얻어야 한다. 만약 하위 구성품이 제조 공정에서 재 사용되는 경우 그 하위 구성품의 재
사용은 특채 또는 기준 이탈에 대해 고객에게 명확하게 의사소통 되어야 한다.
(3) 특채 하에서 승인된 수량 또는 유효만기 일자의 기록을 유지하여야 한다.
(4) 승인이 만료된 경우 본래 또는 대체되는 시방 및 요구사항의 적합성을 또한 보장하여야 한다.
(5) 특채 하에 선적된 자재는 각 선적 컨테이너 상에 적절하게 식별되어야 한다.
(이것은 구매된 제품에 대해 동일하게 적용한다)
(6) 고객에게 제출 전에 공급자로부터의 모든 요청을 승인하여야 한다.
8.7.1.2 부적합 제품의 관리 - 고객 지정 프로세스
품질보증 부서장은 부적합 제품에 대해 해당되는 고객-지정 관리를 준수하여야 한다.
8.7.1.3 의심 제품의 관리
(1) 식별되지 않았거나 의심스런 상태의 제품은 부적합 제품으로 분류되고 관리됨을
보장하여야 한다.
(2) 모든 적절한 제조 인원이 의심스런 제품 및 부적합 제품의 봉쇄에 대한 교육훈련을
받았음을 보장하여야 한다.
8.7.1.4 재 작업된 제품의 관리
(1) 해당 부서장은 제품을 재작업 하는 결정에 앞서 재작업 프로세스에서의 리스크를
평가하는 리스크 분석 방법론을 활용하여야 한다.
고객에 의해 요구되는 경우, 조직은 제품의 재작업 시작에 앞서 고객으로부터 승인을
얻어야 한다.
(2) 해당 부서장은 본래의 시방에 대한 적합성을 검증하는 관리계획서 또는 기타 관련
문서화된 정보에 따라 재작업 확인에 대한 문서화된 프로세스를 가지고 있어야 한다.
(3) 재검사 및 추적성 요구사항을 포함한 분해 또는 재작업에 대한 지침은 적절한 인원에
의해 활용되고 접근 가능하여야 한다.
(4) 수량, 처분, 처분 일자 및 해당되는 추적성 정보를 포함한 재작업 제품의 처분에
관한 문서화된 정보를 보유하여야 한다.
8.7.1.5 수리된 제품의 관리
(1) 해당 부서장은 제품을 수리하는 결정에 앞서 수리 프로세스에서의 리스크를 평가하는
리스크 분석 방법론을 활용하여야 한다. 제품 수리 시작 전에 고객으로부터 승인을
얻어야 한다.
(2) 해당 부서장 관리계획서 또는 기타 관련 문서화된 정보에 따라 수리 확인에 대한
문서화된 프로세스를 가지고 있어야 한다.
(3) 재검사 및 추적성 요구사항을 포함한 분해 또는 수리에 대한 지침을 적절한 인원에
의해 활용되고 접근 가능하여야 한다.
(4) 해당 부서장은 수리 된 제품에 대한 특채를 위해 문서화된 고객 승인을 얻어야 한다.
(5) 해당 부서장은 수량, 처분, 처분 일자 및 해당되는 추적성 정보를 포홤한 수리된 제품의
처분에 대한 정보에 관해 문서화된 정보를 보유하여야 한다.
8.7.1.6 고객 통보
부적합 제품이 출하되었을 경우 고객에게 즉시 통보하여야 한다. 최초 의사소통은
이벤트의 상세한 문서화와 함께 따라야 한다.
8.7.1.7 부적합 제품 처분
(1) 품질보증부서장은 재작업 또는 수리의 대상이 아닌 부적합 제품의 처분에 대한 문서화된
프로세스를 갖고 있어야 한다.
(2) 요구사항을 충족하지 않는 제품에 대해 조직은 처리에 앞서 폐기될 제품이 사용
불가능한 상태로 만들어지는지를 검증하여야 한다.
(3) 해당 부서장은 이전 고객 승인 없이 서비스 또는 기타 사용으로 부적합 제품을
전환시켜서는 안된다.
8.7.2 품질보증 부서장은 다음의 문서화된 정보를 보유하여야 한다.
(1) 부적합에 대한 기술
(2) 취해진 조치에 대한 기술
(3) 승인된 특채에 대한 기술
(4) 부적합에 관한 활동을 결정하는 책임의 식별', 60
WHERE NOT EXISTS (SELECT 1 FROM regulation_sections WHERE reg_code = 'QM' AND sort_order = 60);
