INSERT INTO regulation_sections (reg_code, section_title, section_body, sort_order)
SELECT 'QM', '9.1 모니터링, 측정, 분석 및 평가', '9.1.1 일반사항
(1) 해당부서장은 다음 사항에 필요한 모니터링, 측정, 분석 및 평가를 결정하여야 한다.
가. 모니터링 및 측정대상
나. 유효한 결과를 보장하기 위하여 필요한 모니터링, 측정, 분석 및 평가에 대한 방법
다. 모니터링 및 측정 수행 시기
라. 모니터링 및 측정의 결과에 대한 분석 및 평가 시기
마. 조직의 환경성과의 평가기준과 적절한 지표
(2) 해당부서는 품질 환경 경영시스템의 성과 및 효과성을 평가하여야 하며 교정 및 검증된
모니터링 및 측정 장비가 사용 및 유지됨을 보장하여야 한다.
(3) 또한 내부 및 외부적으로 관련된 환경안전보건 성과정보를 의사소통 하여야하며
모니터링, 측정, 분석 및 평가결과의 증거로서 적절한 문서화된 정보를 보유하여야 한다.
9.1.1.1 제조 공정의 모니터링 및 측정
특별 특성에 대한 것을 포함하여 공정능력을 검증하고 공정관리를 위한 추가적인
입력을 제공하기 위해모든 새로운 제조 공정에 관하여 공정조사를 수행하여야 한다.
(1) 생산 부서장은 고객승인 요구사항의 준수를 위하여 공정성과를 유지/관리한다.
(2) 장.설비수리 등의 주요 공정변동 사항은 관리도 또한 체크시트에 기록한다.
(3) 생산 부서장은 다음을 포함하여 공정흐름도, 공정 FMEA, 관리계획서, 작업표준이 준수
되도록한다.
가. 측정방법
나. 샘플링 계획
다. 합격판정 기준
라. 계량치 데이터에 대한 실제 측정값 또는 시험결과의 기록
마. 합격 판정 기준에 충족하지 못했을 경우 대응 계획 및 단계적 확대 프로세스
(4) 공정능력이 부족하거나 불안전 공정에 대해서는 공정능력 확보시까지 100% 검사를
포함한 특별관리를 실시하며 이 경우 일정과 책임자를 포함하는 조치계획을 수립하여
고객이 요구하는 경우 고객의 검토/승인을 받는다.
9.1.1.1.1 환경관련 모니터링 및 측정
(1) 총무 부서장은 중대한 환경영향을 줄 수 있는 조직 운영의 주요 특성을 정기적으로
모니터링 및 측정하기 위한 절차를 수립, 실행 및 유지하여야 한다.
(2) 이 절차에는 조직의 환경목표 및 세부목표에 관련된 성과, 적용되는 운영관리 및
적합성을 모니터링 하기 위한 정보의 문서화를 포함하여야 한다.
(3) 품질보증 부서장은 사용하고 유지하는 모니터링 및 측정장비를 교정 또는 검증하여야
하며 관련 기록을 보유하여야 한다.
9.1.1.1.2 제품의 모니터링 및 측정
(1) 검사기준의 수립
가. 품질보증 부서장은 제품 요구사항이 충족된다는 것을 검증하기 위하여 제품의
모니터링 및 검사를 실시한다.
나. 모니터링 및 검사는 계획된 결정사항에 따라 적절한 단계에서 실시 되어야 한다
(2) 수입검사
가. 제품의 생산을 위하여 입고된 자재 및 외주가공품의 수입검사를 실시한다.
나. 수입검사는 공급업체의 관리실적, 이전의 검사결과 및 부품이 제품에 미치는
영향을 고려하여 탄력적으로 실시한다.
(3) 공정검사
가. 공정의 완료 각 단계에서 공정검사를 실시한다.
나. 공정검사는 사전에 계획된 공정단계에서 실시 되어야 하며, 작업자의 자주검사와
품질보증팀의 검사원에 의한 슨회검사로 공정을 검사 한다.
(4) 제품검사
가. 제품의 완성단계에서 관리계획서(제품 규격서)를 참고로 제품검사를 실시한다.
나. 제품검사는 검사전에 앞서 계획된 검사가 실시되었는가를 확인 한다.
(5) 검사/시험 및 시험상태
가. 원/부자재는 합격품에 한하여 입고시키고 합부 상태는 검사 이력 및 부품식별표로서
확인한다,
나. 공정검사 결과 불량품은 부적합품 보관장소에 별도 격리, 보관한다.
다. 완제품 출고대기 장소에는 모든 검사에 합격한 제품만을 이동 시킨다.
(6) 측정관리 및 유지
가. 검사는 합격판정 기준에 적합하다는 증거로서 검사기준서, 작업표준 등 기술 문서를
작성, 유지 하여야 한다.
나. 각 단계에서 실시된 검사의 결과는 기록으로 유지 되어야 하며 기록에는 제품의
불출을 승인하는 인원이 나타나야 한다
다. 자격이 부여된 검사원 또는 고객의 승인한 경우를 제외 하고는 제품 불출 및 인도는
모든 검사 활동이 만족스럽게 완료되기 전에 진행해서는 안된다.
9.1.1.2 통계적 도구의 파악
해당 부서장은 통계적 도구의 적절한 사용을 결정하여야 하며, 적절한 통계적 도구가
사전 품질 기획 프로세스의 일부로써 포함되고, 설계 리스크 분석(DFMEA), PFMEA,
관리 계획서가 포함됨을 검증하여야 한다.
9.1.1.3 통계적 개념의 적용
산포, 관리(안전성), 공정 능력 및 과잉 공정의 결과 같은 통계적 개념은 통계적
데이터의 수집, 분석 및 관리에 관여되는 종업원에 의해 이해되고 이용되어야 한다.
9.1.2 고객 만족
9.1.2.1 고객 만족
(1) 해당 부서장은 품질경영시스템 성과 측정의 하나로 고객의 니즈 및 기대가 어느정도
충족되었는지에 대한 고객의 인식과 관련된 정보를 모니터링 하여야 한다.
(2) 이 정보의 수집, 모니터링 및 검토하기 위한 방법을 결정하여야 한다.
비고. 고객인식에 대한 모니터링의 사례에는, 고객설문조사, 인도된 제품 또는 서비스에 대한
고객 피드백, 고객과의 미팅, 시장점유율 분석, 고객불만, 보증클레임 그리고 판매업자
보고서를 포함할 수 있다.
9.1.2.2 고객 만족 - 보충사항
고객만족은 제품 및 고객 요구사항에 대한 준수를 보장하기 위해 내/외부 성과
지표의 지속적 평가를 통해 모니터 되어야 한다.
(1) 고객만족도 조사
가. 해당 부서장은 년 1회 외부고객만족도 조사를 실시한다.
나. 고객만족도 조사는 설문조사, 방문조사, 유선조사 등의 방법을 취하며 분석후 문서화
하여야한다.
다. 해당 부서장은 조사결과 고객만족도가 낮거나 잠재적 불만 항목등 회사의 조치를
필요로하는 항목을 도출한다.
(2) 고객 성과 지표
해당 부서장은 다음을 포함한 프로세스 성과를 모니터링한다.
가. 납품된 제품 품질
나. 고객 생산중단, 반품, 리콜 및 품질 보증서
다. 품질/납기 관련 일정 계획 고객 통보
라. 특별 상황을 포함한, 품질 또는 인도 이슈에 과련되 고객 통지
(3) 조사, 분석결과의 활용
가. 고객만족도 조사 결과 즉각 조치를 필요로하는 항목에 대해서는 시정조치를 실시한다.
나. 즉각 조치가 어려운 항목은 중장기 과제로 하거나 사업계획에 반영하여 추진되도록
한다.
다. 품질 및 생산 부서장은 고객요구 달성을 위하여 제조 프로세스 성과의 모니터링을
실시한다.
9.1.2.3 환경안전관련 준수 평가
(1) 총무 부서장은 준수에 대한 회사의 의지와 일관되게 회사에 적용되는 법규 요구사항의
준수 여부와 준수 의무가 충족됨을 평가하기 위한 절차를 수립, 실행 및 유지하여야
한다.
(2) 총무 부서장은 회사가 동의한 그 밖의 요구사항에 대한 준수 여부를 평가하여야 하며
법규 준수 여부에 대한 평가와 통합하거나 별도의 절차를 수립하여 평가할 수 있다.
(3) 총무 부서장은 다음을 수행하여야 한다.
가. 준수평가의 주기 결정
나. 준수평가를 실시하고 필요한 경우 조치 실시
다. 준수상태에 대한 지식과 이해를 유지
(4) 해당부서는 준수평가 결과의 증거로서 적절한 문서화된 정보를 보유하여야 한다.
9.1.3 분석 및 평가
(1) 해당 부서장은 모니터링 및 측정에서 발생된 적절한 데이터 및 정보를 분석 및 평가
하여야 한다.
(2) 모니터링 및 측정의 결과로 생성된 데이터 및 다른 관련 출처로부터 생성된 데이터를
포함하여야 하며, 통계적 기법을 포함한 적용 가능한 방법 및 사용 정도에 대한 결정을
포함하여야 한다.
(3) 분석결과는 다음 사항의 평가를 위하여 사용되어야 한다.
가. 제품 및 서비스의 적합성
나. 고객 만족도
다. 품질 환경 경영시스템의 성과 및 효과성
라. 기획의 효과적인 실행 여부
마. 리스크 및 기회를 다루기 위하여 취해진 조치의 효과성
바. 외부 제공자의 성과
사. 품질 환경 경영시스템의 개선 필요성
(4) 품질 및 운영성과의 경향은 목표대비 진척사항과 비교되어야 하며, 고객 만족 향상을
위한 조치의 우선순위를 지원하기 위한 조치를 이끌어야 한다.
비고. 데이터 분석 방법에는 통계적 기법이 포함 될 수 있다.
9.1.3.1 통계적 도구의 파악
품질보증 부서장은 각 업무 중 통계적 기법의 적용이 필요한 업무와 적용될 통계적
기법을 파악한다.
9.1.3.2 통계적기법의 보급
(1) 품질보증 부서장은 각 부서가 업무에 필요한 통계적기법을 적절히 활용하고 있는지
확인하며 통계적기법 활용 대상인원에 필요 교육을 실시한다.
(2) 품질보증 부서장은 통계적기법의 신규도입, 기존기법의 갱신필요 여부를 검토 및
관리하며 또한 변동(산포), 관리/안정, 공정능력등 기본적인 통계 개념을 확산시킨다.
9.1.3.3 통계적기법의 적용
(1) 전 부서장은 파악된 통계적 기법을 품질향상을 위한 업무에 적용한다.
(2) 전 부서장은 통계적기법을 활용 결과 품질의개선 및 경영방향을 결정하는데 사용한다.', 63
WHERE NOT EXISTS (SELECT 1 FROM regulation_sections WHERE reg_code = 'QM' AND sort_order = 63);
INSERT INTO regulation_sections (reg_code, section_title, section_body, sort_order)
SELECT 'QM', '9.2 내부심사', '9.2.1 일반사항
품질보증 부서장은 품질 환경 경영시스템이 다음에 대한 정보를 제공하기 위하여
연 1회 이상 내부심사를 주관하여 수행하여야 한다.
(1) 품질 환경 경영시스템에 대한 조직의 자체 요구사항
(2) 이 표준의 요구사항
(3) 품질환경안전경영시스템이 효과적으로 실행되고 유지되는지 여부
9.2.2 내부심사 프로그램
품질보증 부서장은 다음 사항을 실행하여야 한다.
(1) 심사 주기, 방법, 책임, 요구사항의 기획 및 보고를 포함하는 심사 프로그램을 수립,
실행 및 유지하여야 한다.
(2) 내부심사프로그램에서는 관련 프로세스의 중요성, 회사에 영향을 미치는 변경 그리고
이전 심사 결과를 고려해야 한다.
(3) 심사 기준, 적용범위, 주기 및 방법을 정하여야 한다.
(4) 심사원 선정 및 심사수행에는 심사프로세스의 객관성 및 공정성이 보장되어야 한다.
(5) 심사원은 자신의 업무에 대하여 심사를 수행하여서는 안 된다.
(6) 품질보증 부서장은 심사의 계획 및 수행, 기록 수립 및 결과 보고에 대한 책임과 요구
사항을 규정하기 위한 문서화된 절차를 수립하여야 한다.
(7) 심사와 결과에 대한 기록은 유지되어야 한다
(8) 심사대상 업무에 책임을 지는 경영자는 발견된 부적합 및 원인을 제거하기 위한 모든
필요한 시정 및 시정조치가 적시에 취해질 수 있도록 보장하여야 한다.
(9) 후속조치는 취해진 조치의 검증 및 검증 결과의 보고를 포함하여야 한다.
(10) 심사 프로그램의 실행 및 심사결과의 증거로 문서화된 정보의 보유 하여야 한다.
9.2.2.1 내부심사 프로그램 - 보완사항
(1) 품질보증 부서장은 문서화된 내부 심사 프로세스를 갖추어야 한다.
(2) 내부심사 프로세스는 품질 환경 시스템 심사, 제조 프로세스 심사, 제품 심사를 포함한
전체 시스템을 다루도록 한다.
(3) 심사 프로그램은 리스크, 내/외부 성과 경향과 프로세스의 중대성을 근간으로 하여
우선순위화 하여야 한다.
(4) 심사 프로그램의 효과성은 경영검토의 일부로 검토되어야 한다.
9.2.2.2 품질경영시스템 심사
조직은 자동차 산업 품질,환경 경영시스템 표준에 대한 준수여부를 검증하기 위해 프로세스
접근법을 사용하여, 년간 프로그램에 따라 3년 심사 사이클로 모든 품질,환경 경영시스템 프로
세스를 심사 하여야 한다.
이들 심사와 통합하여 조직은 효과적인 실행을 위해 고객지정 품질,환경 경영시스템 요구사항을
샘플 취해야 한다.
전체 심사 사이클은 3년이다. 3년 심사 사이클 내에서 심사되는 개별 프로세스의 품질,환경
경영시스템 심사 빈도는 내부 및 외부 성과 및 리스크를 기반으로 해야 한다. 조직은 그들의
프로세스의 할당된 심사 빈도에 대한 정당성을 유지해야 한다.
모든 프로세스는 3년 심사 사이클 동안 샘플링 되어야 하며 ISO 9001/ISO 14001 기본 요구
사항 및 모든 고객지정 요구 사항을 포함하여 IATF 16949 표준의 모든 해당 요구 사항에
대해 심사햬야 한다.
9.2.2.3 제조공정 심사
(1) 프로세스 심사에 대한 고객지정의 요구되는 접근법을 사용하여 그들 시스템의 효과성
및 효율성을 결정하기 위해 각 3년 주기로 모든 제조 프로세스를 심사하여야 한다.
(2) 개별 심사 계획서 내에는 각 제조 프로세스가 교대 조 인계의 적절한 샘플링을 포함하여,
모든 교대조에 관해 심사한다.
(3) 제조 프로세스 심사는 프로세스 리스크 분석(P FMEA), 관리계획서 및 관련된 문서의
효과적인 실행에 대한 심사를 포함한다.
9.2.2.4 제품 심사
규정된 요구사항에 대한 적합성을 검증하기 위해 생산 및 인도의 적절한 단계에서
고객 지정의 요구되는 접근법을 사용하여 제품을 심사하여야 한다.', 64
WHERE NOT EXISTS (SELECT 1 FROM regulation_sections WHERE reg_code = 'QM' AND sort_order = 64);
INSERT INTO regulation_sections (reg_code, section_title, section_body, sort_order)
SELECT 'QM', '9.3 경영검토/경영평가', '9.3.1 일반사항
(1) 최고 경영자는 품질환경안전경영시스템의 지속적인 적절성, 충족성, 효과성 및 정렬성을
보장하기 위하여 년 1회 경영검토를 시행한다.
(2) 경영검토의 빈도는 성과 관련된 이슈과 품질 환경 경영시스템에 영향을 주는 내/외부
변경의 결과로 발생하는 고객 요구사항을 준수하는데 리스크를 근간으로 선정한다.
(3) 경영검토시 시스템의 개선 기회 및 변경에 대한 필요성을 평가한다.
9.3.2 경영검토 입력사항
경영검토에 대한 입력은 다음을 포함하여야 한다.
(1) 이전 경영검토에 따른 조치의 상태
(2) 품질 환경 경영시스템과 관련된 외부 및 내부 이슈의 변경
(3) 다음의 경향을 포함한 품질 환경 경영시스템의 성과 및 효과성에 대한 정보
가. 고객만족 및 관련 이해관계자로부터의 피드백
나. 품질 환경 목표의 달성 정도
다. 프로세스 성과, 그리고 제품 및 서비스의 적합성
라. 부적합 및 시정조치
마. 모니터링 및 측정 결과
바. 심사 결과
사. 외부공급자의 성과
(4) 자원의 충족성
(5) 리스크와 기회를 다루기 위하여 취해진 조치의 효과성
(6) 개선 기회
(7) 조직의 중대한 환경안전보건측면 , 준수의무를 포함한 이해관계자의 니즈 및 기대
9.3.2.1 경영검토 입력사항 - 보충사항
(1) 저 품질 비용 (내부 및 외부 부적합 비용)
(2) 프로세스 효과성의 조치들
(3) 적용 가능한 경우, 제품 실현 프로세스에 대한 프로세스 효율성의 조치들
(4) 제품 적합성
(5) 새로운 시설 또는 새로운 제품에 대해 그리고 기존 운용(오퍼레이션)에 대한 변경에 대해
수행된 제조 타당성 평가
(6) 고객 만족
(7) 보전 목표 대비 성과 검토
(8) 보증 성과 (해당되는 경우)
(9) 고객 점수표 검토 (해당되는 경우)
(10) 리스크 분석을 통해 파악된 잠재적 필드 고장의 파악 (FMEA와 같은)
(11) 실제 필드 고장 및 안전 또는 환경에 대한 그들의 영향
(12) 해당되는 경우, 제품 및 공정의 설계와 개발동안 규정된 단계에서 측정의 요약 결과
9.3.3 경영검토 출력사항
9.3.3.1 경영검토 출력사항에는 다음과 관련된 결정 및 조치가 포함되어야 한다.
(1) 품질 환경 경영시스템의 지속적인 적절성, 충족성 및 효과성에 대한 결론 및 개선 기회
(2) 품질 환경 경영시스템 변경에 대한 모든 필요성
(3) 자원의 필요성
(4) 고객 성과 목표가 달성되지 않은 경우 필요한 조치 계획
9.3.3.2 경영검토 결과의 증거로 문서화된 정보를 보유하여야 한다.', 65
WHERE NOT EXISTS (SELECT 1 FROM regulation_sections WHERE reg_code = 'QM' AND sort_order = 65);
INSERT INTO regulation_sections (reg_code, section_title, section_body, sort_order)
SELECT 'QM', '9.4 관련표준', '(1) 고객만족도 관리 규정 (H-3100)
(2) 고객불만 처리 규정 (H-3200)
(3) 내부심사 규정 (A-5100)
(4) 공정 및 제품심사 규정 (A-5200)
(5) 통계적 기법 적용 규정 (L-4100)
(6) 관리도 운영 지침 (L-4101)
(7) 공정능력 운영 지침 (L-4102)
(8) 경영검토 규정 (A-2200)
(9) 신뢰성 시험업무 규정 (L-2200)
(10) 측정 시스템 쳥가 지침 (L-3101)', 66
WHERE NOT EXISTS (SELECT 1 FROM regulation_sections WHERE reg_code = 'QM' AND sort_order = 66);
INSERT INTO regulation_sections (reg_code, section_title, section_body, sort_order)
SELECT 'QM', '10. 개선', '', 67
WHERE NOT EXISTS (SELECT 1 FROM regulation_sections WHERE reg_code = 'QM' AND sort_order = 67);
INSERT INTO regulation_sections (reg_code, section_title, section_body, sort_order)
SELECT 'QM', '10.1 일반사항', '10.1.1 해당 부서장은 품질 환경 경영방침, 목표, 심사결과, 데이터분석, 시정조치, 경영검토,
조직사항 및 리스크 등의 활용을 통하여 개선기회를 결정하고 선택하여야 하며, 고객의
요구사항을 충족시키고 고객 만족을 증진하는데 필요한 모든 조치를 실행하여야 한다.
10.1.2 조치에는 다음사항이 포함되어야 한다.
(1) 요구사항을 충족하기 위한 것 뿐만 아니라 미래의 니즈 및 기대를 다루기 위한 제품 및
서비스의 개선
(2) 시정, 예방 또는 바람직하지 않은 영향의 완화
(3) 품질 환경 경영시스템의 성과 및 효과성 개선
비고. 개선의 사례에는 시정, 시정조치, 지속적 개선, 획기적인 변화, 혁신 및 조직 개편이
포함될 수 있다.', 68
WHERE NOT EXISTS (SELECT 1 FROM regulation_sections WHERE reg_code = 'QM' AND sort_order = 68);
INSERT INTO regulation_sections (reg_code, section_title, section_body, sort_order)
SELECT 'QM', '10.2 부적합 및 시정조치', '10.2.1 부적합 및 시정조치
10.2.1.1 해당 부서장은 불만족에서 야기된 모든 것을 포함하여, 부적합이 발생한 경우
부적합의 재발방지를 목적으로부적합의 원인을 제거하여 시정조치를 취하여야 한다.
10.2.1.2 모든 조치를 위하여 다음을 실행하여야 한다.
(1) 부적합에 대처해야 하며, 해당되는 경우
가. 부적합을 관리하고 시정하기 위한 조치 실시
나. 결과를 처리
(2) 부적합이 재발하거나 다른 곳에서 발생하지 않도록 부적합의 원인을 제거하기 위한
조치의 필요성을 다음사항을 통해 평가한다.
가. 부적합의 검토 및 분석
나. 부적합의 원인 결정
다. 유사한 부적합의 존재여부 또는 잠재적인 발생여부 결정
(3) 필요한 모든 조치의 결정 및 실행
(4) 취해진 모든 시정 조치의 효과성 검토 및 결과 기록
(5) 필요한 경우, 기획 시 결정된 리스크 및 기회의 갱신
(6) 필요한 경우, 품질환경경영시스템의 변경
10.2.1.3 시정조치 요구
(1) 각 부서장은 업무수행 중 발견되는 부적합 사항에 대하여 내용의 중대성, 긴급성 등을
고려 후 시정조치 필요여부를 판단후 해당조직에 시정조치를 요구한다.
(2) 고객불만 발생시 영업부서장은 세부내용 및 원인을 조사하여 원인 조직에 시정조치
요구 또는 관련자 회의를 통하여 대책을 수립한다.
10.2.1.4 원인분석 및 대책실시
조치 부서는 부적합 사항에 대한 원인을 분석하고 대책을 수립/실시한다.
10.2.1.5 효과 확인
(1) 해당 부서장은 대책 내용을 검토하고 실시효과 확인을 하며 필요에 따라 재 시정조치를
요구한다.
(2) 시정조치 결과 관련 표준의 제/개정이 필요한 경우 조치부서 및 관련 부서가 협의
검토하여 표준의 제/개정을 실시한다.
10.2.2 문서화된 정보
해당 부서장은 다음 사항의 증거로 문서화된 정보를 보유하여야 한다.
(1) 부적합의 성격 및 취해진 모든 후속조치
(2) 모든 시정조치의 결과
10.2.3 문제 해결
조직은 다음 사항을 포함하는 재발을 방지하는 문제해결을 위한 문서화된 프로세스를
갖추어야 한다.
(1) 다양한 형태 및 크기의 문제에 대한 규정된 접근법 (예를 들어, 신제품개발, 현 제조
이슈, 필드 고장, 심사 발견사항)
(2) 봉쇄, 임시조치 그리고 부적합 출력물의 관리를 위해 필요한 관련된 활동
(3) 근본원인 분석, 사용된 방법론, 분석 및 결과
(4) 유사한 프로세스 및 제품에 대한 영향에 대한 고려를 포함한 시스템적인 시정조치의 실행
(5) 실행된 시정조치의 효과성에 대한 검증
(6) 적절한 문서화된 정보의 검토와 필요한 경우, 갱신 (예 - PFMEA, 관리계획서)
고객이 문제해결에 대한 특정 규정된 프로세스, 도구 또는 시스템을 갖고 있는 경우, 조직은
고객에 의해 달리 승인하지 않는 한 그러한 프로세스, 도구 또는 시스템을 사용하여야 한다.
10.2.4 실수 방지
(1) 해당 부서장은 적절한 실수방지 방법론의 사용을 결정하기 위한 문서화된 프로세스를 갖추
어야 한다. 사용된 방법의 상세 내용은 공정 리스크 분석에 문서화되어야 하고 시험 빈도가
관리계획서에 문서화되어야 한다.
(2) 고장 또는 시뮬레이트 된 고장에 대한 실수방지 기기의 시험을 포함하여야 하며, 기록은
유지되어야 한다. 사용된 경우 챌린지 부품은 실현 가능한 만큼 식별, 관리, 검증 및 교정되어야
한다. 실수방지장치 고장은 대응계획을 갖추어야 한다.
10.2.5 보증 관리 시스템
(1) 제품에 대한 보증을 제공하도록 요구되는 경우, 보증관리 프로세스를 실행하여야 한다.
(2) 원인불명고장(NTF : no trouble found)을 포함하여 보증 부품 분석을 위한 방법론을
포함하여야 한다.
10.2.6 고객불만 및 필드고장 시험 분석
(1) 모든 반송된 부품을 포함하여 고객불만 및 필드고장에 관한 분석을 수행하여야 하고,
재발을 방지하기 위해 시정조치 및 문제해결을 착수하여야 한다.
(2) 고객에 의해 요청된 경우, 고객의 최종 제품의 시스템 내에서 조직의 제품에 내장된
소프트웨어의 상호작용에 대한 분석을 포함하여야 하며, 고객 및 조직 내에서도 시험/
분석결과를 의사소통하여야 한다.', 69
WHERE NOT EXISTS (SELECT 1 FROM regulation_sections WHERE reg_code = 'QM' AND sort_order = 69);
INSERT INTO regulation_sections (reg_code, section_title, section_body, sort_order)
SELECT 'QM', '10.3 지속적 개선', '10.3.1 해당 부서장은 품질 환경시스템의 적절성, 충분성 및 효과성을 지속적으로 개선하여야
한다.
(1) 각 부서장은 매년말 차기년도 목표 수립시 시행할 개선계획을 수립한다.
(2) 해당되는 경우, 해당부서장은 매월 전월의 주요 실적/문제점을 검토하여 개선과제를
선정한다.
(3) 개선과제의 선정은 품질환경안전방침, 품질환경안전목표, 데이터 분석, 내/외부 심사,
경영검토 등 다양한 경로를 활용 할수있다.
(4) 해당 부서장은 자체 또는 다른 부서의 지원을 받아 개선을 실시하고 진도관리를
실시하며 효과를 확인한다.
(5) 개선을 실시한 후에는 해당 개선에 관련된 상세 내용을 기술하여 보고한다.
(6) 해당 부서장은 분석 및 평가의 결과, 경영검토의 출력을 고려하여 다루어야 할 필요성
또는 기회가 있는지를 결정한다.
10.3.2 지속적 개선에 대한 문서화된 프로세스를 갖추어야 하며, 다음사항을 프로세스 내에
포함하여야 한다.
(1) 사용된 방법론, 목표, 측정, 효과성 및 문서화된 정보에 대한 파악
(2) 공정 변동 및 낭비의 감소에 관한 강조를 갖는 제조공정 개선 조치 계획
(3) 리스크 분석 (FMEA)
10.3.3 제조 공정이 통계적으로 능력이 있고 안정적이거나 제품 특성이 예측 가능하고 고객
요구사항을 충족하는 경우 지속적 개선이 실행된다.', 70
WHERE NOT EXISTS (SELECT 1 FROM regulation_sections WHERE reg_code = 'QM' AND sort_order = 70);
INSERT INTO regulation_sections (reg_code, section_title, section_body, sort_order)
SELECT 'QM', '10.4 관련표준', '(1) 지속적인 개선 프로세스 (SP-03)
(2) 시정조치 규정 (B-2100)
(3) 지속적 개선업무 규정 (B-2200)
(4) 고객불만 처리 규정 (H-3200)', 71
WHERE NOT EXISTS (SELECT 1 FROM regulation_sections WHERE reg_code = 'QM' AND sort_order = 71);

