SELECT 'PROC', 'MP-02 리스크 관리 프로세스', '리스크 관리 프로세스 · 문서번호 TPC - MP - 02 · 개정 REV.5 · 재·개정일 2023-05-01
적용 범위 | 품질경영시스템이 조직의 의도된 결과를 달성 할 수 있음을 보장하고 바람직한 영향을 증진시키고, 바람직하지 않은 영향을 예방 또는 완화시키며, 개선을 달성 할 수 있도록 리스크 및
기회를 결정한다.
목 적 | 본 규정은 품질경영시스템 운영시 발생할 수 있는 제반 리스크를 효율적으로 관리하기 위한 조직과 관리방법에 관하여 필요한 사항을 규정함으로써 조직의 지속적 성장과 경영안정을 통한
기업가치의 극대화에 이바지함을 목적으로 한다.
